#[tokio::test]
async fn tax_publish_writes_the_tax_node_onto_the_store_layer() {
    let tax_rates = FakeTaxRates::default();
    let class = TaxClassId::new(Ulid::from_u128(7));
    tax_rates.rows.lock().expect("lock").push((
        tenant(),
        TaxRateEntry::new(class, SalesChannel::DineIn, TaxRate::from_percent(10)),
    ));
    let config_trees = FakeConfigTrees::default();
    let router = tax_publish_app(provisioned_admin(), tax_rates, config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let published = router
        .oneshot(put_with_cookie(
            "/admin/config/tax",
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &cookie,
        ))
        .await
        .expect("route tax publish");
    assert_eq!(published.status(), StatusCode::OK);

    // The store's Store config layer (index 2) now carries the `tax` node — the serialized rate table.
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    let tax = &state.record.layers[2]["tax"];
    assert!(tax.is_array(), "the tax node is the serialized rate table");
    assert_eq!(tax.as_array().expect("array").len(), 1);
}

/// A capturing [`OtaReportStore`] — what the `/internal/ota/report` route actually recorded.
///
/// The route had no test coverage before ADR-0078 Amendment 1, which is how a two-state field
/// survived into a three-state read model unnoticed.
#[derive(Clone, Default)]
struct FakeOtaReports {
    rows: Arc<Mutex<Vec<RecordedReport>>>,
}

/// One captured report: who reported, the version, and the tri-state verdict.
type RecordedReport = (TenantId, StoreId, String, Option<bool>);

impl OtaReportStore for FakeOtaReports {
    async fn record_report(
        &self,
        tenant: TenantId,
        store: StoreId,
        installed: &str,
        self_test_passed: Option<bool>,
        _reported_at: Timestamp,
    ) -> Result<(), FleetStoreError> {
        self.rows.lock().expect("lock").push((
            tenant,
            store,
            installed.to_owned(),
            self_test_passed,
        ));
        Ok(())
    }
}

/// The router with the OTA-report ingest merged in.
fn ota_report_app(reports: FakeOtaReports) -> axum::Router {
    let app = app(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
    );
    http::router(app).merge(http::ota_report_router(
        reports,
        clock(),
        FakeKeys::default(),
        Some(internal_secret()),
    ))
}

/// The report router with a key store a test can issue a store token against — what the `/sync`
/// route authenticates. Returns the router and the keys, so a caller can mint the token it needs.
fn store_report_app(reports: FakeOtaReports) -> (axum::Router, FakeKeys) {
    let keys = FakeKeys::default();
    let app = app_full(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        keys.clone(),
        provisioned_admin(),
        FakeConfigTrees::default(),
    );
    let router = http::router(app).merge(http::ota_report_router(
        reports,
        clock(),
        keys.clone(),
        Some(internal_secret()),
    ));
    (router, keys)
}

/// The body an edge posts, with `self_test_passed` supplied by the caller so each case can choose
/// present-and-true, present-and-false, or absent.
fn report_body(self_test: Option<bool>) -> serde_json::Value {
    let mut body = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "store_id": store_id().as_ulid().to_string(),
        "installed": "1.4.0",
    });
    if let Some(passed) = self_test {
        body["self_test_passed"] = serde_json::json!(passed);
    }
    body
}

#[tokio::test]
async fn an_ota_report_records_all_three_self_test_states() {
    // A store that has never installed anything omits the field. This is the case the amendment
    // exists for: the report still says which binary the store runs, and the verdict is recorded as
    // absent rather than as a pass or a failure it never earned.
    let reports = FakeOtaReports::default();
    let accepted = ota_report_app(reports.clone())
        .oneshot(post_internal("/internal/ota/report", &report_body(None)))
        .await
        .expect("route the report");
    assert_eq!(accepted.status(), StatusCode::NO_CONTENT);
    assert_eq!(
        reports.rows.lock().expect("lock").as_slice(),
        [(tenant(), store_id(), "1.4.0".to_owned(), None)],
        "an omitted self-test is recorded as absent, not defaulted"
    );

    // An edge built before the amendment still posts the field, and its verdict is read unchanged —
    // in both directions, because a dropped `false` would hide exactly the failure the column warns
    // about.
    for passed in [true, false] {
        let reports = FakeOtaReports::default();
        let accepted = ota_report_app(reports.clone())
            .oneshot(post_internal(
                "/internal/ota/report",
                &report_body(Some(passed)),
            ))
            .await
            .expect("route the report");
        assert_eq!(accepted.status(), StatusCode::NO_CONTENT);
        assert_eq!(
            reports.rows.lock().expect("lock").as_slice(),
            [(tenant(), store_id(), "1.4.0".to_owned(), Some(passed))],
            "an explicit self_test_passed={passed} is recorded as given"
        );
    }
}

#[tokio::test]
async fn a_malformed_ota_report_is_refused_and_records_nothing() {
    let reports = FakeOtaReports::default();
    let router = ota_report_app(reports.clone());

    // A store id that is not a ULID.
    let mut bad_id = report_body(Some(true));
    bad_id["store_id"] = serde_json::json!("not-a-ulid");
    let refused = router
        .clone()
        .oneshot(post_internal("/internal/ota/report", &bad_id))
        .await
        .expect("route the report");
    assert_eq!(refused.status(), StatusCode::BAD_REQUEST);

    // An empty installed version — the one field a report cannot be useful without.
    let mut blank = report_body(Some(true));
    blank["installed"] = serde_json::json!("   ");
    let refused = router
        .oneshot(post_internal("/internal/ota/report", &blank))
        .await
        .expect("route the report");
    assert_eq!(refused.status(), StatusCode::BAD_REQUEST);

    assert!(
        reports.rows.lock().expect("lock").is_empty(),
        "a refused report writes nothing to the read model"
    );
}

/// The router with the OTA levers merged in ([ADR-0052](../../docs/adr/0052-ota-rollout-config.md),
/// ADR-0078) — the rollout publish/halt/read and the placement publish/read.
fn ota_app(admin: FakeAdmin, config_trees: FakeConfigTrees) -> axum::Router {
    ota_app_hosting(admin, config_trees, &["1.4.0"])
}

/// The OTA levers, with `hosted` releases already in the registry.
///
/// A rollout naming a version the cloud does not host is refused ([ADR-0088](../../docs/adr/0088-ota-artifact-hosting.md)
/// Amendment 2), so a test about *publishing* has to host its version first. Pass an empty slice to
/// exercise the refusal itself.
fn ota_app_hosting(
    admin: FakeAdmin,
    config_trees: FakeConfigTrees,
    hosted: &[&str],
) -> axum::Router {
    let app = app_full(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
    );
    let releases = FakeOtaArtifacts::default();
    for release in hosted {
        releases
            .artifacts
            .lock()
            .expect("the artifact list is not poisoned")
            .push(pos_cloud::ota::ReleaseArtifact {
                release: (*release).to_owned(),
                target: pos_cloud::ota::TargetTriple::parse(TEST_TARGET).expect("a triple"),
                size_bytes: 4,
                sha256: "00".repeat(32),
                recorded_at: Timestamp::from_milliseconds_since_epoch(1_777_000_000_000)
                    .expect("a valid timestamp"),
            });
    }
    http::router(app).merge(http::ota_config_router(
        config_trees,
        admin,
        clock(),
        Arc::new(NoopAuditRecorder),
        releases,
    ))
}

/// The OTA levers with a real trail behind them, for the tests that assert what a bump *recorded*
/// rather than what it wrote. `ota_app` uses a no-op recorder, which is fine for the routes whose
/// evidence is the config tree and useless for the ones whose evidence is the audit entry.
fn ota_app_with_audit(
    admin: FakeAdmin,
    config_trees: FakeConfigTrees,
    audit: Arc<dyn AuditRecorder>,
) -> axum::Router {
    let app = app_full(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
    );
    http::router(app).merge(http::ota_config_router(
        config_trees,
        admin,
        clock(),
        audit,
        FakeOtaArtifacts::default(),
    ))
}

#[tokio::test]
async fn a_rollout_and_a_placement_land_on_their_own_config_layers() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let published = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/ota",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "target_version": "1.4.0",
                "min_ring": "fleet",
                "rollout_percent": 40,
                "signing_key_id": "a1a1a1a1a1a1a1a1",
            }),
            &cookie,
        ))
        .await
        .expect("route the rollout publish");
    assert_eq!(published.status(), StatusCode::OK);

    let placed = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/ota/placement",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "ring": "fleet",
                "canary_bucket": 10,
            }),
            &cookie,
        ))
        .await
        .expect("route the placement publish");
    assert_eq!(placed.status(), StatusCode::OK);

    // The two nodes sit on different layers, and publishing the second does not disturb the first —
    // the rollout is a Store-level fact, the placement a Device-level one.
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    assert_eq!(
        state.record.layers[2]["fleet_update"]["target_version"],
        "1.4.0"
    );
    assert_eq!(
        state.record.layers[2]["fleet_update"]["rollout_percent"],
        40
    );
    assert_eq!(state.record.layers[3]["device_ota"]["ring"], "fleet");
    assert_eq!(state.record.layers[3]["device_ota"]["canary_bucket"], 10);

    // And both reach the *effective* document, which is what a store actually pulls — a node authored
    // onto a layer nothing merges would be invisible to the edge that has to read it.
    let effective = &state
        .record
        .history
        .last()
        .expect("a published version")
        .effective;
    assert_eq!(effective["fleet_update"]["min_ring"], "fleet");
    assert_eq!(effective["device_ota"]["canary_bucket"], 10);

    // The read-backs answer from the layer each node was authored onto.
    let rollout = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/ota?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the rollout read");
    assert_eq!(rollout.status(), StatusCode::OK);
    assert_eq!(json_body(rollout).await["target_version"], "1.4.0");

    let placement = router
        .oneshot(get_with_cookie(
            &format!("/admin/config/ota/placement?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the placement read");
    assert_eq!(placement.status(), StatusCode::OK);
    assert_eq!(json_body(placement).await["canary_bucket"], 10);
}

/// A replacement box numbers above what the cloud has seen
/// ([ADR-0149](../../../docs/adr/0149-a-replacement-box-numbers-above-what-the-cloud-has-seen.md)):
/// the bump publishes the highest receipt number the log holds as `receipt_floor`, in the **same**
/// version as the `lease` node, and a log with no settled bill publishes no floor at all.
#[tokio::test]
async fn a_lease_bump_publishes_the_receipt_floor_beside_the_lease() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let body = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "store_id": store_id().as_ulid().to_string(),
    });

    let first = router
        .clone()
        .oneshot(bump_with_if_match(&body, &cookie, "*"))
        .await
        .expect("route the first bump");
    assert_eq!(first.status(), StatusCode::OK);
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    assert!(
        state.record.layers[2].get("receipt_floor").is_none(),
        "a store the cloud has seen no receipt from gets no floor"
    );

    *config_trees.highest_receipt.lock().expect("lock") = Some(40);
    let second = router
        .clone()
        .oneshot(bump_with_if_match(&body, &cookie, "\"0\""))
        .await
        .expect("route the second bump");
    assert_eq!(second.status(), StatusCode::OK);
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    let effective = &state
        .record
        .history
        .last()
        .expect("a published version")
        .effective;
    assert_eq!(
        effective["receipt_floor"],
        serde_json::json!({ "number": 40 })
    );
    assert_eq!(
        effective["lease"],
        serde_json::json!({ "generation": 1 }),
        "the floor and the lease arrive in the same version"
    );
}

#[tokio::test]
async fn a_lease_bump_advances_the_authority_and_publishes_the_node_the_store_reads() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    // A store nobody has issued a lease to reads `null` — "no lease in force", which the edge treats
    // as `Active` so the fleet behaves exactly as it did before the mechanism existed. It is
    // deliberately not generation `0`, which is a real first lease (ADR-0108, ADR-0049).
    let unissued = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/lease?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the lease read");
    assert_eq!(unissued.status(), StatusCode::OK);
    assert!(json_body(unissued).await["generation"].is_null());

    // The first bump establishes the counter at generation 0 and supersedes nobody.
    let first = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &cookie,
            "*",
        ))
        .await
        .expect("route the first bump");
    assert_eq!(first.status(), StatusCode::OK);
    assert!(
        !json_body(first).await["config_version_id"]
            .as_str()
            .unwrap_or_default()
            .is_empty(),
        "a bump publishes a config version, because the node is how the store learns"
    );

    // The second bump is the act of replacing the machine: the counter moves, and the Store layer
    // now carries a `lease` node the edge will weigh its held generation against.
    let second = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &cookie,
            "\"0\"",
        ))
        .await
        .expect("route the second bump");
    assert_eq!(second.status(), StatusCode::OK);

    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/lease?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the lease read");
    assert_eq!(
        json_body(read).await["generation"],
        1,
        "the only write is a bump: 0, then 1, and there is no way to set a value"
    );

    // The published node is what the edge parses, on the **Store** layer — not the Device layer the
    // placement uses. `device_ota` decides which release a store takes; `lease` decides whether this
    // box is the store, and merging them would let a placement edit touch the lease.
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    assert_eq!(
        state.record.layers[2]["lease"],
        serde_json::json!({ "generation": 1 }),
        "the node is derived from the counter, so the two cannot drift"
    );
    // And it reaches the *effective* document, which is what a store actually pulls: a node authored
    // onto a layer nothing merges would be invisible to the edge that has to weigh it.
    let effective = &state
        .record
        .history
        .last()
        .expect("a published version")
        .effective;
    let parsed: pos_core::lease::LeaseConfig = serde_json::from_value(effective["lease"].clone())
        .expect("the edge's own type reads the effective node back");
    assert_eq!(
        parsed.generation(),
        pos_core::lease::LeaseGeneration::new(1)
    );
}

/// The `edge_placement` recorded by the most recent `config.lease.bump`, and whether that bump chose
/// it. Read from the trail rather than from the fake's own map, because the trail is what an
/// operator answering "when did this store become hosted, and who moved it?" actually has.
async fn last_bump_placement(audit: &FakeAudit) -> (String, bool) {
    let recorded = audit.list(None, 20).await.expect("list audit entries");
    let after = recorded
        .iter()
        .find(|entry| entry.action == "config.lease.bump")
        .expect("a bump was audited")
        .after
        .clone()
        .expect("a bump records what it wrote");
    (
        after["edge_placement"]
            .as_str()
            .expect("the trail names the placement")
            .to_owned(),
        after["edge_placement_moved"]
            .as_bool()
            .expect("the trail says whether this bump moved the store"),
    )
}

#[tokio::test]
async fn a_bump_is_the_only_thing_that_writes_where_a_store_runs() {
    let audit = FakeAudit::default();
    let config_trees = FakeConfigTrees::default();
    let router = ota_app_with_audit(
        provisioned_admin(),
        config_trees.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    // A first bump that names nothing puts the store under the lease where every store in the fleet
    // already is. `IN_STORE` is the column's default rather than something the route invents, so a
    // console that never learned the field keeps working and keeps telling the truth.
    let first = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &cookie,
            "*",
        ))
        .await
        .expect("route the first bump");
    assert_eq!(first.status(), StatusCode::OK);
    assert_eq!(
        last_bump_placement(&audit).await,
        ("EDGE_PLACEMENT_IN_STORE".to_owned(), false),
        "a bump that named no placement did not move the store"
    );

    // Naming one is a move, and it is the same act as issuing the generation — one request, one
    // write. The trail records both halves, so "who moved this store off the shop LAN, and when"
    // has an answer that does not require reading a second table at a second time (ADR-0110).
    //
    // The region rides the same request, and is required here rather than optional: a hosted
    // placement without one is the state ADR-0114 exists to prevent, so the route refuses this body
    // without it. Which is why this test names a region and the swap below does not.
    let moved = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "edge_placement": "EDGE_PLACEMENT_HOSTED_BY_PLATFORM",
                "region_country": "SG",
                "region_label": "ap-southeast-1",
            }),
            &cookie,
            "\"0\"",
        ))
        .await
        .expect("route the move");
    assert_eq!(moved.status(), StatusCode::OK);
    assert_eq!(
        last_bump_placement(&audit).await,
        ("EDGE_PLACEMENT_HOSTED_BY_PLATFORM".to_owned(), true),
        "naming a placement moves the store, and the trail says so"
    );

    // ADR-0003's swap: the hosted box is replaced by another hosted box. The generation moves and
    // the placement does not, because the request named none. This is the case that would break if
    // a bump silently reset the column — a store quietly readvertised as offline-capable when it is
    // not, which is the one direction ADR-0110 calls dangerous.
    let swapped = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                // Generation 0 was left undrained by the move above, so this swap has to say it is
                // abandoning it. Without the acknowledgement the route refuses — which is the whole
                // point, and is asserted on its own elsewhere.
                "acknowledge_undrained": 0,
            }),
            &cookie,
            "\"1\"",
        ))
        .await
        .expect("route the swap");
    assert_eq!(swapped.status(), StatusCode::OK);
    assert_eq!(
        last_bump_placement(&audit).await,
        ("EDGE_PLACEMENT_HOSTED_BY_PLATFORM".to_owned(), false),
        "a swap in place keeps the placement it had"
    );

    // The generation kept moving throughout: 0, 1, 2. The placement rode along inside those writes
    // rather than beside them.
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/lease?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the lease read");
    assert_eq!(json_body(read).await["generation"], 2);
}

/// A handover that does not exist cannot be settled or retired, and neither route invents one.
#[tokio::test]
async fn neither_hand_made_act_works_on_a_store_with_no_handover() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let named = serde_json::json!({
        "tenant_id": tenant_ulid,
        "store_id": store_ulid,
        "superseded_generation": 0,
    });

    // No lease at all: both are 404, rather than a handover conjured on a store that has none.
    for uri in ["/admin/config/lease/settle", "/admin/config/lease/retire"] {
        let refused = router
            .clone()
            .oneshot(post_with_cookie(uri, &named, &cookie))
            .await
            .expect("route the request");
        assert_eq!(
            refused.status(),
            StatusCode::NOT_FOUND,
            "{uri} on a store with no lease is a 404, not a handover"
        );
    }

    // A first lease supersedes nobody, so there is still nothing to settle — and the refusal says
    // so rather than succeeding quietly and putting an attestation about nothing in the trail.
    let issued = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &cookie,
            "*",
        ))
        .await
        .expect("route the first issue");
    assert_eq!(issued.status(), StatusCode::OK);

    let nothing_to_settle = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/config/lease/settle",
            &named,
            &cookie,
        ))
        .await
        .expect("route the settle");
    assert_eq!(nothing_to_settle.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(
        json_body(nothing_to_settle).await["error"]["details"][0]["reason"],
        "NO_HANDOVER_IN_FLIGHT",
        "a settle against a store with no handover says so rather than succeeding quietly"
    );
}

/// The handover's two hand-made steps over the routes, in the order an operator lives them.
///
/// One test rather than four, because the states only mean anything in sequence: `retired` is
/// reachable only from `settled`, and `settled` only from an in-flight handover. Split apart, each
/// assertion would have to fabricate the state before it — which is the fabrication the
/// preconditions exist to prevent.
#[tokio::test]
async fn a_handover_settles_then_retires_and_each_step_refuses_out_of_order() {
    let audit = FakeAudit::default();
    let config_trees = FakeConfigTrees::default();
    let router = ota_app_with_audit(
        provisioned_admin(),
        config_trees.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let store = serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid });
    let named = |generation: u64| {
        serde_json::json!({
            "tenant_id": tenant_ulid,
            "store_id": store_ulid,
            "superseded_generation": generation,
        })
    };

    // Generation 0, then 1 — so generation 0's machine is now the one being displaced.
    for if_match in ["*", "\"0\""] {
        let bumped = router
            .clone()
            .oneshot(bump_with_if_match(&store, &cookie, if_match))
            .await
            .expect("route the bump");
        assert_eq!(bumped.status(), StatusCode::OK);
    }

    // Retiring now is the refusal that matters most: the outgoing machine may hold the only copy of
    // a night's sales, and nobody gets to call it unnecessary until that is settled.
    let too_early = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/config/lease/retire",
            &store,
            &cookie,
        ))
        .await
        .expect("route the early retire");
    assert_eq!(too_early.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(
        json_body(too_early).await["error"]["details"][0]["reason"],
        "0",
        "the refusal names the generation still owing events"
    );

    // Attesting about the wrong machine is refused, and the body says which one is actually in
    // flight. This is the guard against a stale console closing a handover nobody looked at.
    let wrong_machine = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/config/lease/settle",
            &named(7),
            &cookie,
        ))
        .await
        .expect("route the mis-aimed settle");
    assert_eq!(wrong_machine.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(
        json_body(wrong_machine).await["error"]["details"][0]["reason"],
        "0",
        "the refusal names the handover that is actually in flight"
    );

    // The operator has read the powered-off box and attests it is empty; now the machine can be
    // decided unnecessary. A second retirement is refused rather than overwriting the first
    // decision's who and when — the row's entire job is to hold the first.
    for (uri, body, expected) in [
        (
            "/admin/config/lease/settle",
            named(0),
            StatusCode::NO_CONTENT,
        ),
        (
            "/admin/config/lease/retire",
            store.clone(),
            StatusCode::NO_CONTENT,
        ),
        (
            "/admin/config/lease/retire",
            store.clone(),
            StatusCode::UNPROCESSABLE_ENTITY,
        ),
    ] {
        let response = router
            .clone()
            .oneshot(post_with_cookie(uri, &body, &cookie))
            .await
            .expect("route the request");
        assert_eq!(response.status(), expected, "{uri}");
    }

    assert_both_decisions_are_in_the_trail(&audit).await;
}

/// A store on its first lease has nothing to retire, and says so rather than recording a decision
/// ([ADR-0110](../../docs/adr/0110-edge-placement-is-a-deployment-axis.md)).
///
/// Generation `0` is a store's first-ever lease: it supersedes nobody, so there is no previous
/// machine and no handover. Before the `generation > 0` precondition the other two conditions both
/// held on such a store, and a retire recorded that its *only* machine — the one selling in the shop
/// — was no longer needed. The console never offered it (a gen-0 store derives no handover state, so
/// there is no button), which is exactly why the route needed the guard: nothing an operator can see
/// was stopping them.
///
/// `422` and not `404`: the store is there, and the act does not apply to it.
#[tokio::test]
async fn a_store_on_its_first_lease_has_no_previous_machine_to_retire() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app_with_audit(
        provisioned_admin(),
        config_trees.clone(),
        Arc::new(AuditSink::new(FakeAudit::default())),
    );
    let cookie = admin_cookie(&router).await;
    let store = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "store_id": store_id().as_ulid().to_string(),
    });

    // One bump: the store now holds generation 0 and has never handed over.
    let bumped = router
        .clone()
        .oneshot(bump_with_if_match(&store, &cookie, "*"))
        .await
        .expect("route the bump");
    assert_eq!(bumped.status(), StatusCode::OK);

    let refused = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/config/lease/retire",
            &store,
            &cookie,
        ))
        .await
        .expect("route the retire");
    assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(refused).await;
    assert_eq!(
        body["error"]["details"][0]["field"], "generation",
        "the refusal names the generation that makes the act inapplicable: {body}"
    );
    assert_eq!(body["error"]["details"][0]["reason"], "0");

    // And nothing was written: a second attempt gets the same refusal, not "already retired". That
    // is the assertion that would have caught the original defect — a recorded decision would make
    // this one `AlreadyRetired`.
    let again = router
        .oneshot(post_with_cookie(
            "/admin/config/lease/retire",
            &store,
            &cookie,
        ))
        .await
        .expect("route the second retire");
    assert_eq!(again.status(), StatusCode::UNPROCESSABLE_ENTITY);
    assert_eq!(
        json_body(again).await["error"]["details"][0]["field"],
        "generation",
        "the first refusal recorded nothing, so the second is the same refusal"
    );
}

/// Both hand-made decisions reached the trail, and the retirement names its decider **by id**.
///
/// The identifier matters: the row carries the admin's ULID and the trail carries the email as it
/// stood, so a reader with the standing to resolve one gets a person and a reader without one gets
/// an opaque id. Asserting both halves here is what keeps an address from drifting into the
/// operational row later.
async fn assert_both_decisions_are_in_the_trail(audit: &FakeAudit) {
    let recorded = audit.list(None, 20).await.expect("list audit entries");
    let actions: Vec<&str> = recorded.iter().map(|entry| entry.action.as_str()).collect();
    assert!(
        actions.contains(&"config.lease.settle") && actions.contains(&"config.lease.retire"),
        "both hand-made decisions are recorded, found {actions:?}"
    );
    let retire = recorded
        .iter()
        .find(|entry| entry.action == "config.lease.retire")
        .expect("the retirement is recorded");
    let after = retire
        .after
        .clone()
        .expect("a retirement records what it wrote");
    assert_eq!(
        after["retired_by"], retire.actor.admin_id,
        "the row's decider and the trail's actor are the same admin, by id"
    );
    assert!(
        after["retired_by"] != *retire.actor.email,
        "the operational row carries the id, never the address — the trail is where an email belongs"
    );
}

/// A bump that abandons an undrained machine records *which* generation it abandoned.
///
/// The number is nowhere else. An acknowledged bump does not clear `superseded_generation`; it rolls
/// it forward to the machine being displaced now. So without this the fact that an earlier
/// machine's sales were written off, and by whom, would exist in no record at all.
#[tokio::test]
async fn an_acknowledged_bump_records_the_generation_it_abandoned() {
    let audit = FakeAudit::default();
    let config_trees = FakeConfigTrees::default();
    let router = ota_app_with_audit(
        provisioned_admin(),
        config_trees.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let store = serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid });

    for if_match in ["*", "\"0\""] {
        let response = router
            .clone()
            .oneshot(bump_with_if_match(&store, &cookie, if_match))
            .await
            .expect("route the bump");
        assert_eq!(response.status(), StatusCode::OK);
    }

    // Generation 0 is still in flight, so this third bump has to say it is abandoning it.
    let abandoning = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "acknowledge_undrained": 0,
            }),
            &cookie,
            "\"1\"",
        ))
        .await
        .expect("route the abandoning bump");
    assert_eq!(abandoning.status(), StatusCode::OK);

    let recorded = audit.list(None, 20).await.expect("list audit entries");
    let latest = recorded
        .iter()
        .find(|entry| entry.action == "config.lease.bump")
        .expect("a bump was audited")
        .after
        .clone()
        .expect("a bump records what it wrote");
    assert_eq!(
        latest["abandoned_generation"], 0,
        "the trail names the generation whose events were written off"
    );
    assert_eq!(
        latest["generation"], 2,
        "and the generation the store moved to, which is a different number"
    );
}

/// ADR-0114: a hosted edge placement moves a whole store's operational data — three parts of it
/// personal — onto a machine somebody chose, and until this landed nothing recorded *where*.
///
/// The move and the record are one request, because they are one act. A second route that could
/// edit the region on its own would let the record say a store rests in Singapore while the machine
/// holding its lease sits in Tokyo.
#[tokio::test]
async fn a_hosted_move_records_where_the_store_now_rests_and_the_trail_names_it() {
    let audit = FakeAudit::default();
    let config_trees = FakeConfigTrees::default();
    let router = ota_app_with_audit(
        provisioned_admin(),
        config_trees.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let moved = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "edge_placement": "EDGE_PLACEMENT_HOSTED_BY_OPERATOR",
                "region_country": "sg",
                "region_label": "  ap-southeast-1  ",
            }),
            &cookie,
            "*",
        ))
        .await
        .expect("route the hosted move");
    assert_eq!(moved.status(), StatusCode::OK);

    let entry = |audit: &[AuditEntry]| {
        audit
            .iter()
            .find(|entry| entry.action == "config.lease.bump")
            .expect("a bump was audited")
            .after
            .clone()
            .expect("a bump records what it wrote")
    };
    let recorded = audit.list(None, 20).await.expect("list audit entries");
    let after = entry(&recorded);
    assert_eq!(
        after["region_country"], "SG",
        "the code is normalised on the way in, so the console's comparison against a store's \
         published locale is an equality test rather than a case fold"
    );
    assert_eq!(
        after["region_label"], "ap-southeast-1",
        "the label is trimmed, because the emptiness and length checks ran on the trimmed value"
    );
    assert_eq!(after["edge_placement"], "EDGE_PLACEMENT_HOSTED_BY_OPERATOR");

    // A swap in place: the machine is replaced, the *place* is not. The trail has to keep naming
    // the region, because a reader asking "where has this store been running since March" is asking
    // about the store, not about what this particular request happened to mention.
    let swapped = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "acknowledge_undrained": 0,
            }),
            &cookie,
            "\"0\"",
        ))
        .await
        .expect("route the swap");
    assert_eq!(swapped.status(), StatusCode::OK);
    let recorded = audit.list(None, 20).await.expect("list audit entries");
    let after = entry(&recorded);
    assert_eq!(after["region_country"], "SG");
    assert_eq!(after["region_label"], "ap-southeast-1");
    assert_eq!(
        after["edge_placement_moved"], false,
        "and the trail still distinguishes a move from a swap, which is the flag ADR-0110 added"
    );

    // Moving the store back into its shop ends the region: an in-store machine is in the shop, and
    // a stale `SG` on the row would answer the transfer question with a lie.
    let home = router
        .clone()
        .oneshot(bump_with_if_match(
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "edge_placement": "EDGE_PLACEMENT_IN_STORE",
                "acknowledge_undrained": 0,
            }),
            &cookie,
            "\"1\"",
        ))
        .await
        .expect("route the move home");
    assert_eq!(home.status(), StatusCode::OK);
    let recorded = audit.list(None, 20).await.expect("list audit entries");
    let after = entry(&recorded);
    assert!(
        after["region_country"].is_null() && after["region_label"].is_null(),
        "an in-store placement has no region, and the columns are cleared by the same statement"
    );
}

/// Five refusals, each naming the one field an admin can fix, and none of them issuing a
/// generation on the way to refusing ([ADR-0114](../../../docs/adr/0114-region-is-required-recorded-visible.md)).
#[tokio::test]
async fn a_region_that_does_not_belong_or_does_not_parse_is_refused_by_field() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let hosted = "EDGE_PLACEMENT_HOSTED_BY_PLATFORM";

    // (what the body adds, which field the refusal must name, what the case is)
    let cases: [(serde_json::Value, &str, &str); 7] = [
        (
            serde_json::json!({ "edge_placement": hosted }),
            "region_country",
            "a hosted placement with no region at all",
        ),
        (
            serde_json::json!({ "edge_placement": hosted, "region_country": "SG" }),
            "region_country",
            "a country with no label names a place nobody can picture",
        ),
        (
            serde_json::json!({ "edge_placement": hosted, "region_label": "a rack" }),
            "region_country",
            "a label with no country is missing the one field the framework reads",
        ),
        (
            serde_json::json!({
                "edge_placement": hosted,
                "region_country": "Singapore",
                "region_label": "a rack",
            }),
            "region_country",
            "the country is an alpha-2 code, not a name",
        ),
        (
            serde_json::json!({
                "edge_placement": hosted,
                "region_country": "SG",
                "region_label": "   ",
            }),
            "region_label",
            "whitespace is not a place",
        ),
        (
            serde_json::json!({
                "edge_placement": "EDGE_PLACEMENT_IN_STORE",
                "region_country": "SG",
                "region_label": "a rack",
            }),
            "region_country",
            "an in-store machine is in the shop and has no region",
        ),
        (
            serde_json::json!({ "region_country": "JP", "region_label": "Sakai" }),
            "region_country",
            "a bump naming no placement is a swap in place, so this would edit the region alone",
        ),
    ];

    for (extra, field, why) in cases {
        let mut body = serde_json::json!({
            "tenant_id": tenant_ulid,
            "store_id": store_ulid,
        });
        for (key, value) in extra.as_object().expect("an object of extra fields") {
            body[key] = value.clone();
        }
        let refused = router
            .clone()
            .oneshot(post_with_cookie("/admin/config/lease/bump", &body, &cookie))
            .await
            .expect("route the bump");
        assert_eq!(refused.status(), StatusCode::BAD_REQUEST, "{why}");
        let payload = json_body(refused).await;
        assert_eq!(payload["error"]["details"][0]["field"], field, "{why}");
    }

    // And nothing moved. Every refusal above ran before the counter did, so this store is still one
    // nobody has leased — a refusal that had already bumped would supersede a box over a typo.
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/lease?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the lease read");
    assert!(json_body(read).await["generation"].is_null());
}

/// The label's ceiling is 64 *characters*, not bytes
/// ([ADR-0114](../../../docs/adr/0114-region-is-required-recorded-visible.md)).
///
/// A byte limit would give a fork writing Japanese a third of the field a fork writing English
/// gets, for a value neither of them parses. 64 Japanese characters is 192 bytes, so a byte limit
/// refuses the case this asserts must pass.
#[tokio::test]
async fn the_region_labels_ceiling_counts_characters_rather_than_bytes() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let hosted = "EDGE_PLACEMENT_HOSTED_BY_PLATFORM";

    for (label, expected) in [
        ("堺".repeat(64), StatusCode::OK),
        ("堺".repeat(65), StatusCode::BAD_REQUEST),
    ] {
        let response = router
            .clone()
            .oneshot(bump_with_if_match(
                &serde_json::json!({
                    "tenant_id": tenant_ulid,
                    "store_id": store_ulid,
                    "edge_placement": hosted,
                    "region_country": "JP",
                    "region_label": label,
                }),
                &cookie,
                "*",
            ))
            .await
            .expect("route the bump");
        assert_eq!(
            response.status(),
            expected,
            "{} characters",
            label.len() / 3
        );
    }

    // The accepted label issued exactly one generation; the refused one issued none.
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/lease?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the lease read");
    assert_eq!(
        json_body(read).await["generation"],
        0,
        "a refusal that had already bumped would supersede a box over a typo in a label"
    );
}

#[tokio::test]
async fn a_placement_the_framework_does_not_define_is_refused_by_name() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    // Three refusals that all have to be refusals, and would each be a different silent bug:
    //
    //   * a token from nowhere — a typo, or a console built against a fork that added a mode;
    //   * the empty string — a form field the operator opened and left blank, which must not read
    //     as "keep what you had", because that hides the mistake;
    //   * an explicit UNSPECIFIED — the wire's "this message did not say", which looks like an
    //     answer and is not. Omitting the field is how you mean that.
    for token in [
        "EDGE_PLACEMENT_ON_THE_MOON",
        "",
        "EDGE_PLACEMENT_UNSPECIFIED",
    ] {
        let refused = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/config/lease/bump",
                &serde_json::json!({
                    "tenant_id": tenant_ulid,
                    "store_id": store_ulid,
                    "edge_placement": token,
                }),
                &cookie,
            ))
            .await
            .expect("route the bump");
        assert_eq!(
            refused.status(),
            StatusCode::BAD_REQUEST,
            "{token} is not a placement this framework defines"
        );
        let body = json_body(refused).await;
        let message = body["error"]["message"].as_str().unwrap_or_default();
        assert!(
            message.contains("EDGE_PLACEMENT_HOSTED_BY_OPERATOR"),
            "the refusal names what it accepts, not only what it rejected: {message}"
        );
        assert_eq!(body["error"]["details"][0]["field"], "edge_placement");
    }

    // And nothing moved. A refused bump must not have issued a generation on the way to refusing:
    // the store is still one nobody has leased.
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/lease?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the lease read");
    assert!(
        json_body(read).await["generation"].is_null(),
        "a refusal that had already bumped the counter would supersede a box for a typo"
    );
}

#[tokio::test]
async fn an_unplaced_store_reads_null_and_an_illegal_placement_is_refused_with_reasons() {
    let config_trees = FakeConfigTrees::default();
    let router = ota_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    // A store nobody has placed reads `null`, not a fabricated ring. The edge treats that as "no
    // placement" and installs nothing, which is the safe end of the trade (ADR-0048).
    let unplaced = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/config/ota/placement?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the placement read");
    assert_eq!(unplaced.status(), StatusCode::OK);
    assert!(json_body(unplaced).await.is_null());

    // A ring that names no ring and a bucket past 99 are refused by the shared `pos-core` rules the
    // edge also runs, with every violation at once rather than one per attempt.
    let refused = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/ota/placement",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "ring": "everyone",
                "canary_bucket": 200,
            }),
            &cookie,
        ))
        .await
        .expect("route the placement publish");
    assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let violations = json_body(refused).await;
    assert_eq!(violations["error"]["status"], "UNPROCESSABLE");
    let listed = violations["error"]["message"]
        .as_str()
        .expect("the violations join into the message");
    assert!(
        listed.contains("device_ota.ring"),
        "the bad ring is named: {listed:?}"
    );
    assert!(
        listed.contains("device_ota.canary_bucket"),
        "the bad bucket is named: {listed:?}"
    );

    // The refusal changed nothing: the store is still unplaced, so a rejected publish cannot leave a
    // half-applied placement behind.
    assert!(
        config_trees
            .load(tenant(), store_id())
            .await
            .expect("load")
            .is_none(),
        "a refused publish persists no tree"
    );
}

#[tokio::test]
async fn the_placement_routes_require_a_session() {
    let router = ota_app(provisioned_admin(), FakeConfigTrees::default());
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let write = router
        .clone()
        .oneshot(put_json(
            "/admin/config/ota/placement",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "ring": "fleet",
                "canary_bucket": 10,
            }),
        ))
        .await
        .expect("route the placement publish");
    assert_eq!(write.status(), StatusCode::UNAUTHORIZED);

    let read = router
        .oneshot(get(
            &format!("/admin/config/ota/placement?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            None,
        ))
        .await
        .expect("route the placement read");
    assert_eq!(read.status(), StatusCode::UNAUTHORIZED);
}

