/// The store's registered identity reaches the `store_profile` node, and a registration number that
/// is not the shape the country issues is refused before it can reach an invoice
/// ([ADR-0106](../../docs/adr/0106-the-store-is-a-legal-person.md)).
#[tokio::test]
async fn a_store_profile_publish_writes_the_node_and_checks_the_registration_shape() {
    let config_trees = FakeConfigTrees::default();
    let router = store_profile_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let published = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/store-profile",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "legal_name": "Pizza 4P's Japan K.K.",
                "trading_name": "Pizza 4P's Ginza",
                "address_lines": ["中央区銀座 1-2-3", "   "],
                "tax_registration_number": "T1234567890123",
                "tax_registration_label": "登録番号",
                "country_code": "JP",
            }),
            &cookie,
        ))
        .await
        .expect("route the profile publish");
    assert_eq!(published.status(), StatusCode::OK);

    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    let profile = &state.record.layers[2]["store_profile"];
    assert_eq!(profile["trading_name"], "Pizza 4P's Ginza");
    assert_eq!(
        profile["address_lines"],
        serde_json::json!(["中央区銀座 1-2-3"]),
        "a blank line is dropped rather than printed on every receipt"
    );
    assert_eq!(profile["tax_registration_label"], "登録番号");

    // `T` and thirteen digits is Japan's shape; twelve is a typo that would otherwise reach a
    // qualified invoice, where it stops the buyer claiming input tax.
    let typo = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/store-profile",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "legal_name": "Pizza 4P's Japan K.K.",
                "tax_registration_number": "T123456789012",
                "country_code": "JP",
            }),
            &cookie,
        ))
        .await
        .expect("route the typo");
    assert_eq!(typo.status(), StatusCode::BAD_REQUEST);

    // A country this cloud does not carry stores the number unchecked rather than refusing: a fork
    // serving a market it has not written a pack for must still be able to provision a store.
    let unknown_country = router
        .oneshot(put_with_cookie(
            "/admin/config/store-profile",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "legal_name": "Pizza 4P's Bangkok",
                "tax_registration_number": "anything at all",
                "country_code": "TH",
            }),
            &cookie,
        ))
        .await
        .expect("route the unknown country");
    assert_eq!(unknown_country.status(), StatusCode::OK);
}

/// The node an edge actually receives says how many decimals the store's currency has
/// ([ADR-0134](../../../docs/adr/0134-a-currency-says-how-many-decimals-it-has.md)).
///
/// Through the route rather than through `checked_locale_node`, because the value comes from the
/// compiled country registry the *router* is handed: a builder unit test passes just as happily
/// against a state wired with an empty map, and the wiring is half of what was missing.
///
/// The rupee is the case worth writing. Vietnam's exponent is zero and so is the edge session's
/// bootstrap, so a VND store cannot tell a published answer from an absent one — which is why the
/// gap survived two releases of work that depended on it.
#[tokio::test]
async fn a_locale_publish_tells_the_store_how_many_decimals_its_currency_has() {
    let config_trees = FakeConfigTrees::default();
    let router = locale_publish_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;

    let published = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/locale",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": store_id().as_ulid().to_string(),
                "country_code": "IN",
                "currency_code": "INR",
                "timezone": "Asia/Kolkata",
                "cutoff_hour": 4,
                "prices_include_tax": true,
            }),
            &cookie,
        ))
        .await
        .expect("route locale publish");
    assert_eq!(published.status(), StatusCode::OK);

    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    assert_eq!(
        state.record.layers[2]["locale"]["currency_exponent"], 2,
        "without this the edge keeps its bootstrap zero, `GET /api/locale` serves that zero as an \
         answer, and an Indian store prints `INR 26145` on a tax invoice"
    );
    assert_eq!(
        state.record.layers[2]["locale"]["default_retention_days"], 365,
        "the store's retention period travels on the same node and from the same registry \
         (ADR-0107), so the wiring that carries one carries both"
    );
}

#[tokio::test]
async fn locale_publish_validates_and_writes_the_locale_node() {
    let config_trees = FakeConfigTrees::default();
    let router = locale_publish_app(provisioned_admin(), config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let ok = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/locale",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                // Required since ADR-0114: this is the country a hosted store's region is compared
                // against, and it belongs beside the currency and timezone below rather than
                // anywhere new. Lower case in, upper case out.
                "country_code": "vn",
                "currency_code": "VND",
                "timezone": "Asia/Ho_Chi_Minh",
                "cutoff_hour": 4,
            }),
            &cookie,
        ))
        .await
        .expect("route locale publish");
    assert_eq!(ok.status(), StatusCode::OK);
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    assert_eq!(
        state.record.layers[2]["locale"]["timezone"],
        "Asia/Ho_Chi_Minh"
    );
    assert_eq!(state.record.layers[2]["locale"]["currency_code"], "VND");
    assert_eq!(
        state.record.layers[2]["locale"]["country_code"], "VN",
        "normalised on the way in, so the fleet console's comparison is an equality test"
    );

    // A malformed IANA timezone is a 400, validated before anything is written.
    let bad = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/locale",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "store_id": store_ulid,
                "country_code": "VN",
                "currency_code": "VND",
                "timezone": "Nowhere/Nope",
                "cutoff_hour": 4,
            }),
            &cookie,
        ))
        .await
        .expect("route bad timezone");
    assert_eq!(bad.status(), StatusCode::BAD_REQUEST);

    // A publish that names no country is refused by name (ADR-0114). Absent and malformed answer
    // the *same* refusal, on the AIP-193 envelope: the field defaults to the empty string rather
    // than being a bare required field, because a missing field would otherwise be axum's own `422`
    // with a plain body, off the envelope every other `/admin` refusal uses.
    for country in [serde_json::Value::Null, serde_json::json!("Vietnam")] {
        let mut body = serde_json::json!({
            "tenant_id": tenant_ulid,
            "store_id": store_ulid,
            "currency_code": "VND",
            "timezone": "Asia/Ho_Chi_Minh",
            "cutoff_hour": 4,
        });
        if !country.is_null() {
            body["country_code"] = country.clone();
        }
        let refused = router
            .clone()
            .oneshot(put_with_cookie("/admin/config/locale", &body, &cookie))
            .await
            .expect("route the countryless publish");
        assert_eq!(
            refused.status(),
            StatusCode::BAD_REQUEST,
            "a store must say which country it is in: {country}"
        );
        let payload = json_body(refused).await;
        assert_eq!(payload["error"]["details"][0]["field"], "country_code");
    }
}

#[tokio::test]
async fn catalog_creates_and_lists_an_item_and_a_menu() {
    let router = catalog_app(provisioned_admin(), FakeCatalog::default());
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/items",
            &serde_json::json!({
                "tenant_id": tenant,
                "name": "Margherita",
                "tax_class_id": ulid_text(7),
                // Per-locale names (ADR-0074): a real one, plus a blank row the handler drops.
                "name_translations": { "vi": "Bánh Margherita", "": "ignored", "ja": "  " },
                // An item photo (ADR-0075) — a media id round-tripped as image_ref.
                "image_ref": ulid_text(42),
            }),
            &cookie,
        ))
        .await
        .expect("route create item");
    assert_eq!(created.status(), StatusCode::CREATED);
    let created = json_body(created).await;
    assert_eq!(created["name"], "Margherita");
    assert_eq!(created["status"], "active");
    assert_eq!(
        created["image_ref"],
        ulid_text(42),
        "the item photo round-trips"
    );
    assert_eq!(
        created["name_translations"]["vi"], "Bánh Margherita",
        "a real per-locale name is kept"
    );
    assert!(
        created["name_translations"].get("").is_none()
            && created["name_translations"].get("ja").is_none(),
        "a blank-key or blank-value translation row is dropped"
    );
    let item_id = created["menu_item_id"]
        .as_str()
        .expect("an item id")
        .to_owned();

    let listed = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/items?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route list items");
    assert_eq!(listed.status(), StatusCode::OK);
    let items = json_body(listed).await;
    assert_eq!(items.as_array().expect("array").len(), 1);
    assert_eq!(items[0]["menu_item_id"], item_id);
    assert_eq!(items[0]["name_translations"]["vi"], "Bánh Margherita");

    // The CSV export (ADR-0075, Track M5): the item master as text/csv, no price column.
    let exported = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/export/items?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route export items");
    assert_eq!(exported.status(), StatusCode::OK);
    let csv = text_body(exported).await;
    let mut lines = csv.lines();
    assert_eq!(
        lines.next().unwrap(),
        "menu_item_id,name,status,tax_class_id,item_category_id,item_subcategory_id,image_ref"
    );
    let row = lines.next().expect("one item row");
    assert!(row.contains("Margherita") && row.contains(&item_id));
    assert!(row.contains(&ulid_text(42)), "the image ref is a column");
    assert!(
        !csv.to_lowercase().contains("price"),
        "no price is exported"
    );

    // A menu, optionally with a parent — created by name, id minted server-side.
    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/menus",
            &serde_json::json!({ "tenant_id": tenant, "name": "Standard" }),
            &cookie,
        ))
        .await
        .expect("route create menu");
    assert_eq!(created.status(), StatusCode::CREATED);
    assert_eq!(
        json_body(created).await["parent_menu_id"],
        serde_json::Value::Null
    );

    let listed = router
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/menus?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route list menus");
    assert_eq!(json_body(listed).await.as_array().expect("array").len(), 1);
}

#[tokio::test]
async fn a_paged_item_read_searches_and_sorts_on_the_server() {
    // The wire half of B3-3: `?q=`, `?sort=` and `?order=` have to reach the store, not be parsed
    // and dropped. Each assertion here would pass against a handler that ignored its parameter if
    // the fixture were smaller — so the fixture is three items whose name order differs from their
    // creation order.
    let router = catalog_app(provisioned_admin(), FakeCatalog::default());
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);
    for name in ["Zucchini", "Anchovy", "Margherita"] {
        let created = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/catalog/items",
                &serde_json::json!({
                    "tenant_id": tenant,
                    "name": name,
                    "tax_class_id": ulid_text(7),
                    "name_translations": { "vi": format!("Bánh {name}") },
                }),
                &cookie,
            ))
            .await
            .expect("route create item");
        assert_eq!(created.status(), StatusCode::CREATED);
    }

    let names = |body: &serde_json::Value| -> Vec<String> {
        body["items"]
            .as_array()
            .expect("the window")
            .iter()
            .map(|row| row["name"].as_str().expect("a name").to_owned())
            .collect()
    };
    let read = |query: &str| {
        let router = router.clone();
        let cookie = cookie.clone();
        let uri = format!("/admin/catalog/items?tenant_id={tenant}&{query}");
        async move {
            let response = router
                .oneshot(get_with_cookie(&uri, &cookie))
                .await
                .expect("route the paged read");
            assert_eq!(response.status(), StatusCode::OK);
            json_body(response).await
        }
    };

    // Default order is newest-first, unchanged from the unpaged read.
    let newest = read("limit=10").await;
    assert_eq!(names(&newest), ["Margherita", "Anchovy", "Zucchini"]);

    // `?sort=name` is a different order, and `?order=desc` reverses it.
    let by_name = read("limit=10&sort=name").await;
    assert_eq!(names(&by_name), ["Anchovy", "Margherita", "Zucchini"]);
    let reversed = read("limit=10&sort=name&order=desc").await;
    assert_eq!(names(&reversed), ["Zucchini", "Margherita", "Anchovy"]);

    // `?q=` narrows the rows *and* the total, so the pager does not offer empty pages.
    let searched = read("limit=10&q=anch").await;
    assert_eq!(names(&searched), ["Anchovy"]);
    assert_eq!(searched["total"], 1, "the total counts the match");

    // The search reaches the per-locale names too (ADR-0074): "Bánh" is in no primary name.
    let vietnamese = read("limit=10&q=B%C3%A1nh").await;
    assert_eq!(
        vietnamese["total"], 3,
        "every item's Vietnamese name matches"
    );

    // A search and a sort compose, and the page still carries the matching total.
    //
    // The needle is `i`, chosen after this test first asserted the wrong number: every per-locale
    // name here begins "Bánh", so a needle containing `n`, `a` or `h` matches all three through the
    // translation and proves nothing about narrowing. `i` appears in Zucchini and Margherita, in
    // neither Anchovy nor "Bánh".
    let both = read("limit=1&sort=name&q=i").await;
    assert_eq!(
        names(&both),
        ["Margherita"],
        "first by name among the matches, not the first match in the default order",
    );
    assert_eq!(both["total"], 2, "Margherita and Zucchini contain an i");
}

#[tokio::test]
async fn the_item_list_returns_the_whole_master_unpaged_and_a_page_when_a_limit_is_named() {
    let router = catalog_app(provisioned_admin(), FakeCatalog::default());
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);
    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/items",
            &serde_json::json!({
                "tenant_id": tenant,
                "name": "Margherita",
                "tax_class_id": ulid_text(7),
            }),
            &cookie,
        ))
        .await
        .expect("route create item");
    assert_eq!(created.status(), StatusCode::CREATED);
    let item_id = json_body(created).await["menu_item_id"]
        .as_str()
        .expect("an item id")
        .to_owned();

    // An absent limit is the whole item master as a bare array, which the menu compiler and the
    // item pickers depend on — five of the six console consumers of this read are not tables.
    let whole = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/items?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route the whole-set list");
    assert_eq!(
        json_body(whole)
            .await
            .as_array()
            .expect("a bare array, not an envelope")
            .len(),
        1,
    );

    // Naming a limit asks for a page instead (ADR-0098): the window, plus the size of the master.
    let paged = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/items?tenant_id={tenant}&limit=1"),
            &cookie,
        ))
        .await
        .expect("route the paged list");
    assert_eq!(paged.status(), StatusCode::OK);
    let paged = json_body(paged).await;
    assert_eq!(paged["items"].as_array().expect("the window").len(), 1);
    assert_eq!(paged["items"][0]["menu_item_id"], item_id);
    assert_eq!(paged["total"], 1, "one item in the master");
    assert_eq!(paged["limit"], 1, "the bounds used are echoed back");
    assert_eq!(paged["offset"], 0);
    assert!(
        paged["items"][0]["etag"].is_string(),
        "a paged row keeps the per-row etag ADR-0095 put on it",
    );

    // A page past the end is empty and not an error, and still reports the master's size.
    let beyond = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/items?tenant_id={tenant}&limit=10&offset=50"),
            &cookie,
        ))
        .await
        .expect("route the page past the end");
    let beyond = json_body(beyond).await;
    assert!(beyond["items"].as_array().expect("the window").is_empty());
    assert_eq!(beyond["total"], 1);

    for (bound, field) in [
        ("limit=100000", "limit"),
        ("limit=0", "limit"),
        ("offset=1", "offset"),
        // A page-shaping parameter without a limit: the fix is "add a limit", not "correct the
        // value", so it gets its own sentence and names the parameter it arrived with.
        ("q=marg", "q"),
        ("sort=name", "sort"),
        ("order=desc", "order"),
        // Inside the paged form, a token outside the route's closed set is refused with the list of
        // what it accepts, rather than answered with the default order.
        ("limit=5&sort=price", "sort"),
        ("limit=5&order=sideways", "order"),
    ] {
        let refused = router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/catalog/items?tenant_id={tenant}&{bound}"),
                &cookie,
            ))
            .await
            .expect("route the bad bound");
        assert_eq!(
            refused.status(),
            StatusCode::BAD_REQUEST,
            "`{bound}` is a client mistake, not a page",
        );
        assert_eq!(
            json_body(refused).await["error"]["details"][0]["field"],
            field,
            "`{bound}` names the parameter that was wrong",
        );
    }
}

#[tokio::test]
async fn catalog_creates_lists_and_renames_a_tax_class() {
    let router = catalog_app(provisioned_admin(), FakeCatalog::default());
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    // Created by name, the id minted server-side — an operator never types a tax-class ULID.
    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/tax-classes",
            &serde_json::json!({ "tenant_id": tenant, "name": "Standard 10%" }),
            &cookie,
        ))
        .await
        .expect("route create tax class");
    assert_eq!(created.status(), StatusCode::CREATED);
    let created = json_body(created).await;
    assert_eq!(created["name"], "Standard 10%");
    assert_eq!(created["status"], "active");
    let tax_class_id = created["tax_class_id"]
        .as_str()
        .expect("a tax class id")
        .to_owned();
    // The create hands back the version the record starts at (ADR-0094), so the edit below needs no
    // second round trip to learn it.
    let etag = created["etag"].as_str().expect("an etag").to_owned();

    let listed = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/tax-classes?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route list tax classes");
    assert_eq!(listed.status(), StatusCode::OK);
    assert_eq!(json_body(listed).await.as_array().expect("array").len(), 1);

    // Rename + archive in one PATCH.
    let renamed = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{tax_class_id}"),
            &serde_json::json!({ "tenant_id": tenant, "name": "Alcohol", "status": "archived" }),
            &cookie,
            &etag,
        ))
        .await
        .expect("route rename tax class");
    assert_eq!(renamed.status(), StatusCode::OK);
    let renamed = json_body(renamed).await;
    assert_eq!(renamed["name"], "Alcohol");
    assert_eq!(renamed["status"], "archived");

    // A PATCH to an unknown id is a 404, not a silent success — and not a 412 either: a
    // well-formed version for a row that does not exist is an absence, not a conflict (ADR-0094).
    let missing = router
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{}", ulid_text(999)),
            &serde_json::json!({ "tenant_id": tenant, "name": "Nope", "status": "active" }),
            &cookie,
            &etag,
        ))
        .await
        .expect("route rename unknown tax class");
    assert_eq!(missing.status(), StatusCode::NOT_FOUND);
}

/// The catalog's nine record-shaped entities are on the same conditional-write mechanism as the
/// registry (ADR-0094), and this is the case that matters: a second editor holding a stale copy is
/// refused, and the first editor's change is still there.
///
/// One entity stands for the nine because the seam, adapter and handler shape is identical across
/// them — what a per-entity copy of this test would prove is that the same code was pasted nine
/// times, not that nine behaviours are right.
#[tokio::test]
async fn a_stale_catalog_write_is_refused_and_the_first_edit_survives() {
    let router = catalog_app(provisioned_admin(), FakeCatalog::default());
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/tax-classes",
            &serde_json::json!({ "tenant_id": tenant, "name": "Standard 10%" }),
            &cookie,
        ))
        .await
        .expect("route create tax class");
    let created = json_body(created).await;
    let tax_class_id = created["tax_class_id"].as_str().expect("an id").to_owned();
    // Both editors load the record at the same version.
    let both_read = created["etag"].as_str().expect("an etag").to_owned();

    let first = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{tax_class_id}"),
            &serde_json::json!({ "tenant_id": tenant, "name": "Alcohol", "status": "active" }),
            &cookie,
            &both_read,
        ))
        .await
        .expect("route the first save");
    assert_eq!(first.status(), StatusCode::OK);

    let second = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{tax_class_id}"),
            &serde_json::json!({
                "tenant_id": tenant, "name": "Stale Overwrite", "status": "archived",
            }),
            &cookie,
            &both_read,
        ))
        .await
        .expect("route the second save");
    assert_eq!(second.status(), StatusCode::PRECONDITION_FAILED);
    assert_eq!(
        json_body(second).await["error"]["status"],
        "VERSION_MISMATCH"
    );

    let listed = router
        .oneshot(get_with_cookie(
            &format!("/admin/catalog/tax-classes?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route the listing");
    let rows = json_body(listed).await;
    assert_eq!(
        rows[0]["name"], "Alcohol",
        "the refused write must not have applied: {rows}"
    );
    assert_eq!(
        rows[0]["status"], "active",
        "nor any other field it carried: {rows}"
    );
}

/// Archiving a taxonomy row that active items still point at is refused, and the refusal names how
/// many.
///
/// The failure this prevents is at the payment screen, not the console: `pos_core::billing` raises
/// `TaxRateNotConfigured` when no rate matches a line's tax class and channel, so an item left
/// pointing at a class nobody publishes a rate for is a shop that takes the order and cannot close
/// the bill. Nothing before that says a word — which is why the refusal has to be at the archive,
/// where an operator is still looking at the thing they are about to break.
#[tokio::test]
async fn archiving_a_tax_class_active_items_still_use_is_refused() {
    let router = catalog_app(provisioned_admin(), FakeCatalog::default());
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/tax-classes",
            &serde_json::json!({ "tenant_id": tenant, "name": "Standard 10%" }),
            &cookie,
        ))
        .await
        .expect("route create tax class");
    let created = json_body(created).await;
    let tax_class_id = created["tax_class_id"].as_str().expect("an id").to_owned();
    let class_etag = created["etag"].as_str().expect("an etag").to_owned();

    let item = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/items",
            &serde_json::json!({
                "tenant_id": tenant, "name": "Margherita", "tax_class_id": tax_class_id,
            }),
            &cookie,
        ))
        .await
        .expect("route create item");
    let item = json_body(item).await;
    let item_id = item["menu_item_id"].as_str().expect("an id").to_owned();
    let item_etag = item["etag"].as_str().expect("an etag").to_owned();

    let refused = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{tax_class_id}"),
            &serde_json::json!({
                "tenant_id": tenant, "name": "Standard 10%", "status": "archived",
            }),
            &cookie,
            &class_etag,
        ))
        .await
        .expect("route the archive");
    assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(refused).await;
    assert_eq!(body["error"]["status"], "UNPROCESSABLE");
    let message = body["error"]["message"].as_str().expect("a message");
    assert!(
        message.contains('1') && message.contains("item"),
        "the refusal names the size of the problem, not just that there is one: {message}"
    );

    // Renaming it is untouched — the guard is on the archive, not on the row.
    let renamed = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{tax_class_id}"),
            &serde_json::json!({ "tenant_id": tenant, "name": "Standard", "status": "active" }),
            &cookie,
            &class_etag,
        ))
        .await
        .expect("route the rename");
    assert_eq!(renamed.status(), StatusCode::OK);
    let class_etag = json_body(renamed).await["etag"]
        .as_str()
        .expect("an etag")
        .to_owned();

    // Retire the item, and the class is free. An *archived* item's reference does not count: it is
    // not sold, so holding a tax class hostage to it would make this guard the thing operators
    // route around rather than the thing that protects them.
    let archived_item = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/items/{item_id}"),
            &serde_json::json!({
                "tenant_id": tenant,
                "name": "Margherita",
                "tax_class_id": tax_class_id,
                "status": "archived",
            }),
            &cookie,
            &item_etag,
        ))
        .await
        .expect("route archive the item");
    assert_eq!(archived_item.status(), StatusCode::OK);

    let allowed = router
        .oneshot(patch_with_etag(
            &format!("/admin/catalog/tax-classes/{tax_class_id}"),
            &serde_json::json!({ "tenant_id": tenant, "name": "Standard", "status": "archived" }),
            &cookie,
            &class_etag,
        ))
        .await
        .expect("route the second archive");
    assert_eq!(
        allowed.status(),
        StatusCode::OK,
        "with no active item referencing it, the archive goes through"
    );
}

