#[tokio::test]
async fn table_qr_mints_a_signed_token_per_active_table() {
    let admin = provisioned_admin();
    let floor = FakeFloor::default();
    let mine = tenant();
    let store = store_id();
    let area = AreaId::new(Ulid::from_u128(1));
    let active = TableId::new(Ulid::from_u128(0xA1));
    let archived = TableId::new(Ulid::from_u128(0xA2));
    let mut archived_version = None;
    for (table_id, label) in [(active, "T1"), (archived, "T2")] {
        let version = TableStore::create(
            &floor,
            &NewTable {
                table_id,
                tenant_id: mine,
                store_id: store,
                area_id: area,
                label: label.to_owned(),
                seats: 4,
                position: None,
            },
        )
        .await
        .expect("seed table");
        if table_id == archived {
            archived_version = Some(version);
        }
    }
    // Archive T2 — an archived table is not printed on the QR sheet. The write is conditional on the
    // version the create returned (ADR-0094), the same token a reader would have been handed.
    TableStore::update(
        &floor,
        &TableUpdate {
            table_id: archived,
            tenant_id: mine,
            area_id: area,
            label: "T2".to_owned(),
            seats: 4,
            position: None,
            status: EntityStatus::Archived,
        },
        &archived_version.expect("T2 was seeded"),
    )
    .await
    .expect("archive T2");

    let secret = TableTokenSecret::new("a-test-secret");
    let router = http::router(app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        FakeConfigTrees::default(),
        FakeWebhooks::default(),
    ))
    .merge(http::table_qr_router(floor, admin, clock(), secret.clone()));
    let cookie = admin_cookie(&router).await;

    let response = router
        .oneshot(get_with_cookie(
            &format!(
                "/admin/floor/qr?tenant_id={}&store_id={}",
                mine.as_ulid(),
                store.as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route table qr");
    assert_eq!(response.status(), StatusCode::OK);
    let body = json_body(response).await;
    let tokens = body["tokens"].as_array().expect("tokens array");
    assert_eq!(tokens.len(), 1, "only the active table is printed");
    let token = tokens[0]["token"].as_str().expect("a token");
    // The minted token verifies and names the active table — the same value the guest QR carries.
    let table_ref = pos_cloud::qr::verify_table_token(&secret, token).expect("verifies");
    assert_eq!(table_ref.table_id, active);
    assert_eq!(table_ref.store_id, store);
}

/// A staff code the tenant already uses is a conflict, not an outage: `409` `ALREADY_EXISTS` naming
/// `code`, saying to choose another, and never quoting the code, which identifies a person. The
/// refused one writes nothing, records nothing in the trail and publishes nothing.
#[tokio::test]
async fn a_second_employee_with_a_staff_code_in_use_is_refused_409_and_changes_nothing() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    let router = people_app(
        provisioned_admin(),
        people.clone(),
        registry,
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let owner = admin_cookie(&router).await;
    let hire = |name: &str| {
        let body = serde_json::json!({
            "tenant_id": tenant().as_ulid().to_string(),
            "code": "B07",
            "name": name,
        });
        router
            .clone()
            .oneshot(post_with_cookie("/admin/employees", &body, &owner))
    };
    let recorded = async || audit.list(None, 100).await.expect("list audit").len();

    let created = hire("Bao").await.expect("route the create");
    assert_eq!(created.status(), StatusCode::CREATED);
    let (published, entries) = (versions_at(&config, store_id()).await, recorded().await);

    let again = hire("Binh").await.expect("route the create");
    assert_eq!(again.status(), StatusCode::CONFLICT);
    let error = json_body(again).await;
    assert_eq!(error["error"]["status"], "ALREADY_EXISTS", "{error}");
    assert_eq!(error["error"]["details"][0]["field"], "code", "{error}");
    assert_eq!(
        error["error"]["details"][0]["reason"], "ALREADY_EXISTS",
        "{error}"
    );
    assert!(
        error["error"]["message"]
            .as_str()
            .is_some_and(|message| message.contains("choose another")),
        "it says what resolves it: {error}"
    );
    assert!(
        !error.to_string().contains("B07"),
        "never the code: {error}"
    );
    assert_eq!(
        versions_at(&config, store_id()).await,
        published,
        "nothing published"
    );
    assert_eq!(recorded().await, entries, "nothing recorded");
    let holders: Vec<String> = EmployeeStore::list(&people, tenant())
        .await
        .expect("the roster")
        .into_iter()
        .filter(|row| row.record.code == "B07")
        .map(|row| row.record.name)
        .collect();
    assert_eq!(holders, ["Bao"], "the refused one wrote nothing");
}

/// An assignment names the person it grants, so the console can label it without reading the roster.
///
/// This is what has to be true before the People screen's employee table can be paged
/// ([ADR-0098](../../docs/adr/0098-paged-admin-reads.md), B3-4): the screen used to turn an
/// assignment's `employee_id` into a name by searching the whole loaded roster, which stops working
/// the moment the roster arrives a page at a time. The resolution moves to the read that needs it.
#[tokio::test]
async fn an_assignment_names_the_person_it_grants_so_the_console_need_not_read_the_roster() {
    let admin = provisioned_admin();
    let router = people_app_with_audit(
        admin,
        FakePeople::default(),
        Arc::new(AuditSink::new(FakeAudit::default())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/employees",
            &serde_json::json!({ "tenant_id": tenant_ulid, "code": "C77", "name": "Mai" }),
            &cookie,
        ))
        .await
        .expect("route create employee");
    assert_eq!(created.status(), StatusCode::CREATED);
    let employee_id = json_body(created).await["id"]
        .as_str()
        .expect("an id")
        .to_owned();

    let role = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/roles",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Server",
                "permissions": ["billing.discount.apply"],
            }),
            &cookie,
        ))
        .await
        .expect("route create role");
    assert_eq!(role.status(), StatusCode::CREATED);
    let role_id = json_body(role).await["id"].as_str().expect("id").to_owned();

    let assigned = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/assignments",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "employee_id": employee_id,
                "store_id": store_ulid,
                "role_template_id": role_id,
            }),
            &cookie,
        ))
        .await
        .expect("route assign");
    assert_eq!(assigned.status(), StatusCode::CREATED);

    // Both directions of the read carry the person, not just their id.
    for query in [
        format!("tenant_id={tenant_ulid}&store_id={store_ulid}"),
        format!("tenant_id={tenant_ulid}&employee_id={employee_id}"),
    ] {
        let listed = router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/assignments?{query}"),
                &cookie,
            ))
            .await
            .expect("route list assignments");
        assert_eq!(listed.status(), StatusCode::OK);
        let rows = json_body(listed).await;
        let row = &rows[0];
        assert_eq!(
            row["employee_name"], "Mai",
            "the row names the person, so no roster read is needed to label it: {rows}"
        );
        assert_eq!(row["employee_code"], "C77", "and carries their staff code");
        assert_eq!(
            row["employee_id"], employee_id,
            "the id stays, because that is what the remove call takes"
        );
    }
}

#[tokio::test]
#[expect(
    clippy::too_many_lines,
    reason = "one end-to-end lifecycle over the people routes — create/read/set-PIN/update an \
              employee, create a role and reject an unknown permission, assign/list/remove, and the \
              audit + no-PII-in-the-trail assertions — kept together so the invariant is checked \
              against the same data the whole flow produced"
)]
async fn people_routes_crud_lifecycle_audited_without_pii() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let audit = FakeAudit::default();
    let router = people_app_with_audit(admin, people, Arc::new(AuditSink::new(audit.clone())));
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();

    // Create an employee (identity only).
    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/employees",
            &serde_json::json!({ "tenant_id": tenant_ulid, "code": "C01", "name": "Alice" }),
            &cookie,
        ))
        .await
        .expect("route create employee");
    assert_eq!(created.status(), StatusCode::CREATED);
    let employee_id = json_body(created).await["id"]
        .as_str()
        .expect("an id")
        .to_owned();

    // The roster read shows the employee, with no PIN yet.
    let listed = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}"),
            &cookie,
        ))
        .await
        .expect("route list employees");
    assert_eq!(listed.status(), StatusCode::OK);
    let employees = json_body(listed).await;
    assert_eq!(employees.as_array().expect("array").len(), 1);
    assert_eq!(employees[0]["has_pin"], serde_json::json!(false));

    // Set a PIN: non-digits are rejected, four digits accepted.
    let bad_pin = router
        .clone()
        .oneshot(put_with_cookie(
            &format!("/admin/employees/{employee_id}/pin"),
            &serde_json::json!({ "tenant_id": tenant_ulid, "pin": "abcd" }),
            &cookie,
        ))
        .await
        .expect("route bad pin");
    assert_eq!(bad_pin.status(), StatusCode::BAD_REQUEST);
    let set_pin = router
        .clone()
        .oneshot(put_with_cookie(
            &format!("/admin/employees/{employee_id}/pin"),
            &serde_json::json!({ "tenant_id": tenant_ulid, "pin": "1234" }),
            &cookie,
        ))
        .await
        .expect("route set pin");
    assert_eq!(set_pin.status(), StatusCode::NO_CONTENT);

    // Now has_pin is true on a read-one.
    let one = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees/{employee_id}?tenant_id={tenant_ulid}"),
            &cookie,
        ))
        .await
        .expect("route get one");
    assert_eq!(one.status(), StatusCode::OK);
    let employee_etag = etag_of(&one);
    let one_body = json_body(one).await;
    assert_eq!(one_body["has_pin"], serde_json::json!(true));
    assert_eq!(
        one_body["etag"], employee_etag,
        "the header and the body name the same version"
    );

    // Rename, at the version the read-one handed out (ADR-0094). Not an archive: an archived person
    // can no longer be assigned to a store below (ADR-0158 decision 7), and archiving publishes at
    // once, which `archiving_a_person_tells_every_store_they_work_at_and_a_rename_tells_none`
    // covers.
    let updated = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/employees/{employee_id}"),
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Alice Nguyen", "status": "active" }),
            &cookie,
            &employee_etag,
        ))
        .await
        .expect("route update");
    assert_eq!(updated.status(), StatusCode::NO_CONTENT);

    // A second writer still holding the version from before that rename is refused, and the first
    // edit survives.
    let stale = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/employees/{employee_id}"),
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Someone Else", "status": "active" }),
            &cookie,
            &employee_etag,
        ))
        .await
        .expect("route stale update");
    assert_eq!(stale.status(), StatusCode::PRECONDITION_FAILED);

    // The permission catalogue is offered for the role editor.
    let catalogue = router
        .clone()
        .oneshot(get_with_cookie("/admin/people/permissions", &cookie))
        .await
        .expect("route permissions");
    assert_eq!(catalogue.status(), StatusCode::OK);
    assert!(
        !json_body(catalogue)
            .await
            .as_array()
            .expect("array")
            .is_empty()
    );

    // A role naming an unknown permission is refused.
    let bad_role = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/roles",
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Bogus", "permissions": ["not.a.real.permission"] }),
            &cookie,
        ))
        .await
        .expect("route bad role");
    assert_eq!(bad_role.status(), StatusCode::BAD_REQUEST);
    let refusal = json_body(bad_role).await;
    assert_eq!(
        refusal["error"]["details"][0]["field"], "permissions",
        "the field named is the one the caller sent, not a paraphrase: {refusal}"
    );
    assert_eq!(
        refusal["error"]["details"][0]["reason"],
        "INVALID_ENUM_VALUE"
    );

    // A valid role.
    let role = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/roles",
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Cashier", "permissions": ["billing.discount.apply"] }),
            &cookie,
        ))
        .await
        .expect("route create role");
    assert_eq!(role.status(), StatusCode::CREATED);
    let role_id = json_body(role).await["id"].as_str().expect("id").to_owned();

    // Assign the employee to a store with that role.
    let assign = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/assignments",
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "employee_id": employee_id,
                "store_id": store_ulid,
                "role_template_id": role_id,
            }),
            &cookie,
        ))
        .await
        .expect("route assign");
    assert_eq!(assign.status(), StatusCode::CREATED);
    let assignment_id = json_body(assign).await["id"]
        .as_str()
        .expect("id")
        .to_owned();

    // Readable by store and by employee.
    let by_store = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/assignments?tenant_id={tenant_ulid}&store_id={store_ulid}"),
            &cookie,
        ))
        .await
        .expect("route by store");
    assert_eq!(by_store.status(), StatusCode::OK);
    assert_eq!(
        json_body(by_store).await.as_array().expect("array").len(),
        1
    );
    let by_employee = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/assignments?tenant_id={tenant_ulid}&employee_id={employee_id}"),
            &cookie,
        ))
        .await
        .expect("route by employee");
    assert_eq!(by_employee.status(), StatusCode::OK);
    assert_eq!(
        json_body(by_employee)
            .await
            .as_array()
            .expect("array")
            .len(),
        1
    );

    // Remove (offboard). The store is told at once, and the answer says how that went (ADR-0158).
    let remove = router
        .clone()
        .oneshot(delete_with_cookie(
            &format!("/admin/assignments/{assignment_id}?tenant_id={tenant_ulid}"),
            &cookie,
        ))
        .await
        .expect("route remove");
    assert_eq!(remove.status(), StatusCode::OK);

    // Every write was audited — and the trail never carries the employee's name, PIN, or PIN hash.
    let recorded = audit.list(None, 50).await.expect("list audit");
    let actions: Vec<&str> = recorded.iter().map(|entry| entry.action.as_str()).collect();
    for expected in [
        "employee.create",
        "employee.set_pin",
        "employee.update",
        "role.create",
        "assignment.create",
        "assignment.remove",
    ] {
        assert!(actions.contains(&expected), "recorded {expected}");
    }
    let dump = serde_json::to_string(
        &recorded
            .iter()
            .map(|entry| {
                (
                    entry.action.clone(),
                    entry.before.clone(),
                    entry.after.clone(),
                )
            })
            .collect::<Vec<_>>(),
    )
    .expect("serialize the trail");
    assert!(
        !dump.contains("Alice"),
        "the employee's name never enters the audit trail"
    );
    assert!(
        !dump.contains("1234"),
        "the PIN never enters the audit trail"
    );
    assert!(
        !dump.to_lowercase().contains("argon2"),
        "the PIN hash never enters the audit trail"
    );
    // The employee.create entry does record the code (id/code/status), just not the name.
    assert!(dump.contains("C01"), "the staff code is recorded");
}

/// The audit trail shows the staff code an employee write records only to a role holding
/// `console.people.read`
/// ([ADR-0158](../../../docs/adr/0158-the-till-enforces-each-persons-own-permissions.md) decision 9).
///
/// `employee.create` and `employee.update` record the employee's id, code and status (ADR-0070),
/// and every console role reads the trail. A Viewer or an Ops user still sees each entry and who
/// did what to which employee, but not the code; an Owner or Admin reads the entry as written,
/// which is also what shows the trail still records it. The window and the page answer alike, and
/// a role's name, which names no person, stays.
#[tokio::test]
async fn the_audit_trail_shows_a_staff_code_only_to_a_role_that_reads_staff_records() {
    let admin = provisioned_admin();
    let audit = FakeAudit::default();
    let router = people_app_with_audit(
        admin.clone(),
        FakePeople::default(),
        Arc::new(AuditSink::new(audit.clone())),
    )
    .merge(http::audit_router(audit, admin.clone(), clock()));
    let owner = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();

    // An employee created and then archived, each entry recording the code, and a role.
    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/employees",
            &serde_json::json!({ "tenant_id": tenant_ulid, "code": "C01", "name": "Alice" }),
            &owner,
        ))
        .await
        .expect("route create employee");
    assert_eq!(created.status(), StatusCode::CREATED);
    let created_etag = etag_of(&created);
    let employee_id = json_body(created).await["id"]
        .as_str()
        .expect("an id")
        .to_owned();
    let archived = router
        .clone()
        .oneshot(patch_with_etag(
            &format!("/admin/employees/{employee_id}"),
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Alice", "status": "archived" }),
            &owner,
            &created_etag,
        ))
        .await
        .expect("route update employee");
    // An archive publishes at once (ADR-0158 decision 7) — here to no store, as she works at none.
    assert_eq!(archived.status(), StatusCode::OK);
    let cashier = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/roles",
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Cashier", "permissions": [] }),
            &owner,
        ))
        .await
        .expect("route create role");
    assert_eq!(cashier.status(), StatusCode::CREATED);

    for (role, token, names_staff) in [
        (AdminRole::Viewer, "viewer-audit", false),
        (AdminRole::Ops, "ops-audit", false),
        (AdminRole::Admin, "admin-audit", true),
        (AdminRole::Owner, "owner-audit", true),
    ] {
        let cookie = role_session_cookie(&admin, role, token).await;
        for url in [
            format!("/admin/audit?tenant_id={tenant_ulid}"),
            format!("/admin/audit?tenant_id={tenant_ulid}&limit=10&offset=0"),
        ] {
            let read = router
                .clone()
                .oneshot(get_with_cookie(&url, &cookie))
                .await
                .expect("route the audit read");
            assert_eq!(read.status(), StatusCode::OK, "{role:?} reads {url}");
            let body = json_body(read).await;
            let entries = body
                .as_array()
                .or_else(|| body["items"].as_array())
                .expect("the window is an array and the page carries one");
            let mut sides = 0;
            for entry in entries
                .iter()
                .filter(|entry| entry["entity_type"] == "employee")
            {
                for side in ["before", "after"] {
                    let Some(fields) = entry[side].as_object() else {
                        continue; // a create has no before
                    };
                    sides += 1;
                    assert_eq!(fields["id"], employee_id.as_str(), "{role:?}: {url}");
                    assert!(fields.contains_key("status"), "{role:?}: the status stays");
                    assert!(!fields.contains_key("name"), "{role:?}: never a name");
                    let code = names_staff.then(|| serde_json::json!("C01"));
                    assert_eq!(
                        fields.get("code"),
                        code.as_ref(),
                        "{role:?}: a staff code only with console.people.read: {url} {fields:?}"
                    );
                }
            }
            assert_eq!(sides, 3, "{role:?} sees both employee entries: {url}");
            let role_entry = entries
                .iter()
                .find(|entry| entry["entity_type"] == "role")
                .expect("the role entry is read too");
            assert_eq!(
                role_entry["after"]["name"], "Cashier",
                "{role:?}: a role's name names no person"
            );
        }
    }
}

#[tokio::test]
async fn the_roster_read_returns_the_whole_tenant_unpaged_and_a_page_when_a_limit_is_named() {
    let router = people_app_with_audit(
        provisioned_admin(),
        FakePeople::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    for index in 1..=3_u32 {
        let created = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/employees",
                &serde_json::json!({
                    "tenant_id": tenant_ulid,
                    "code": format!("C{index:02}"),
                    "name": format!("Person {index}"),
                }),
                &cookie,
            ))
            .await
            .expect("route create employee");
        assert_eq!(created.status(), StatusCode::CREATED);
    }

    // No limit is the whole roster as a bare array — the read the permission-node publish makes,
    // which a page would leave incomplete (ADR-0098).
    let whole = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}"),
            &cookie,
        ))
        .await
        .expect("route the whole roster");
    assert_eq!(whole.status(), StatusCode::OK);
    let whole = json_body(whole).await;
    assert_eq!(
        whole
            .as_array()
            .expect("a bare array, not an envelope")
            .len(),
        3,
    );

    // Naming a limit asks for a page: the window, plus the tenant's headcount.
    let paged = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}&limit=2"),
            &cookie,
        ))
        .await
        .expect("route the paged roster");
    assert_eq!(paged.status(), StatusCode::OK);
    let paged = json_body(paged).await;
    assert_eq!(paged["items"].as_array().expect("the window").len(), 2);
    assert_eq!(paged["total"], 3, "the headcount, not the window's size");
    assert_eq!(paged["limit"], 2, "the bounds used are echoed back");
    assert_eq!(paged["offset"], 0);
    assert!(
        paged["items"][0]["etag"].is_string(),
        "a paged row keeps the per-row etag ADR-0094 put on it",
    );
    assert_eq!(
        paged["items"][0]["has_pin"],
        serde_json::json!(false),
        "the page carries whether a PIN exists — never the hash (ADR-0070)",
    );

    // The second page holds the remainder, and the two windows do not overlap.
    let rest = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}&limit=2&offset=2"),
            &cookie,
        ))
        .await
        .expect("route the second page");
    let rest = json_body(rest).await;
    assert_eq!(rest["items"].as_array().expect("the window").len(), 1);
    assert_eq!(rest["total"], 3);
    assert_ne!(
        rest["items"][0]["employee_id"], paged["items"][0]["employee_id"],
        "the pages partition the roster rather than repeating it"
    );
}

/// Bounds outside the accepted range are refused by field, and an offset without a limit is refused
/// rather than read as a page of some default size — there is no default size (ADR-0098).
///
/// Its own test rather than a tail on the read above, because a refusal happens before any read: it
/// needs no roster at all, and asserting it against an empty tenant is what proves that.
#[tokio::test]
async fn the_paged_roster_refuses_a_bound_outside_the_range_and_an_offset_without_a_limit() {
    let router = people_app_with_audit(
        provisioned_admin(),
        FakePeople::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();

    for (bound, field) in [
        ("limit=100000", "limit"),
        ("limit=0", "limit"),
        ("offset=1", "offset"),
    ] {
        let refused = router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/employees?tenant_id={tenant_ulid}&{bound}"),
                &cookie,
            ))
            .await
            .expect("route a bad bound");
        assert_eq!(
            refused.status(),
            StatusCode::BAD_REQUEST,
            "{bound} is refused"
        );
        let body = json_body(refused).await;
        assert_eq!(
            body["error"]["details"][0]["field"], field,
            "{bound} names {field}"
        );
    }
}

/// `?q=` narrows the roster page to whoever a name or a staff code matches, and narrows `total` too.
///
/// This is what an assign picker needs before the People screen's table can be paged
/// ([ADR-0098](../../docs/adr/0098-paged-admin-reads.md), B3-4): a picker that offers matches for
/// what the operator typed does not need the whole roster loaded, and one that does cannot survive
/// the table paging out from under it.
#[tokio::test]
async fn the_roster_search_narrows_the_page_and_its_total_by_name_or_code() {
    let router = people_app_with_audit(
        provisioned_admin(),
        FakePeople::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    for (code, name) in [("C01", "Mai Anh"), ("C02", "Bao"), ("MAI99", "Linh")] {
        let created = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/employees",
                &serde_json::json!({ "tenant_id": tenant_ulid, "code": code, "name": name }),
                &cookie,
            ))
            .await
            .expect("route create employee");
        assert_eq!(created.status(), StatusCode::CREATED);
    }

    // "mai" matches one person by name and a different one by code — case-insensitively, and the
    // total counts the match rather than the roster.
    let matched = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}&limit=10&q=mai"),
            &cookie,
        ))
        .await
        .expect("route search");
    assert_eq!(matched.status(), StatusCode::OK);
    let body = json_body(matched).await;
    assert_eq!(
        body["total"], 2,
        "the total counts the match, not the roster: {body}"
    );
    let mut codes: Vec<String> = body["items"]
        .as_array()
        .expect("items")
        .iter()
        .map(|row| row["code"].as_str().expect("a code").to_owned())
        .collect();
    codes.sort();
    assert_eq!(
        codes,
        vec!["C01".to_owned(), "MAI99".to_owned()],
        "one matched on name, the other on code"
    );

    // No match is an empty page and a zero total, not an error — the one true zero.
    let none = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}&limit=10&q=nobody"),
            &cookie,
        ))
        .await
        .expect("route search with no match");
    assert_eq!(none.status(), StatusCode::OK);
    let body = json_body(none).await;
    assert_eq!(body["total"], 0);
    assert!(body["items"].as_array().expect("items").is_empty());

    // `q` shapes a page, so it is refused on the unpaged read rather than silently ignored.
    let unpaged = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}&q=mai"),
            &cookie,
        ))
        .await
        .expect("route search without a limit");
    assert_eq!(
        unpaged.status(),
        StatusCode::BAD_REQUEST,
        "a search with no limit is refused, not answered with the whole roster"
    );
    let body = json_body(unpaged).await;
    assert_eq!(body["error"]["details"][0]["field"], "q");
}

/// `?sort=` and `?order=` reorder the roster page, and an unknown token is refused by name.
///
/// The table's headers are what need this: they sort `name` and `code` client-side today, and a
/// server-paged table whose headers reordered only the visible twelve rows would be telling the
/// operator something false. A refusal that lists the tokens beats silently handing back the
/// default order (ADR-0096).
#[tokio::test]
async fn the_roster_page_sorts_by_name_or_code_and_refuses_an_unknown_token() {
    let router = people_app_with_audit(
        provisioned_admin(),
        FakePeople::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    // Created in an order that matches neither sort, so a page that came back in insertion order
    // would fail both.
    for (code, name) in [("C03", "Bao"), ("C01", "Mai"), ("C02", "An")] {
        let created = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/employees",
                &serde_json::json!({ "tenant_id": tenant_ulid, "code": code, "name": name }),
                &cookie,
            ))
            .await
            .expect("route create employee");
        assert_eq!(created.status(), StatusCode::CREATED);
    }

    // The URL is built outside the async block so the closure borrows `tenant_ulid` rather than
    // moving it, leaving it usable by the refusal cases below.
    let page_of = |query: &str| {
        let router = router.clone();
        let cookie = cookie.clone();
        let url = format!("/admin/employees?tenant_id={tenant_ulid}&limit=10&{query}");
        async move {
            let response = router
                .oneshot(get_with_cookie(&url, &cookie))
                .await
                .expect("route a sorted page");
            assert_eq!(response.status(), StatusCode::OK);
            json_body(response).await["items"]
                .as_array()
                .expect("items")
                .iter()
                .map(|row| row["name"].as_str().expect("a name").to_owned())
                .collect::<Vec<_>>()
        }
    };

    assert_eq!(
        page_of("sort=name").await,
        vec!["An".to_owned(), "Bao".to_owned(), "Mai".to_owned()],
        "by name, ascending"
    );
    assert_eq!(
        page_of("sort=name&order=desc").await,
        vec!["Mai".to_owned(), "Bao".to_owned(), "An".to_owned()],
        "and `desc` is the exact reverse, not a different order sharing a first column"
    );
    assert_eq!(
        page_of("sort=code").await,
        vec!["Mai".to_owned(), "An".to_owned(), "Bao".to_owned()],
        "by staff code — a different sequence from the name order, so one cannot pass for the other"
    );
    assert_eq!(
        page_of("sort=newest&order=asc").await.len(),
        3,
        "the default order names a token too, so a caller can ask for it explicitly"
    );

    // An unknown token is refused, naming the field and what it accepts.
    for (query, field) in [
        ("sort=hired", "sort"),
        ("sort=name&order=sideways", "order"),
    ] {
        let refused = router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/employees?tenant_id={tenant_ulid}&limit=10&{query}"),
                &cookie,
            ))
            .await
            .expect("route a bad token");
        assert_eq!(
            refused.status(),
            StatusCode::BAD_REQUEST,
            "{query} is refused"
        );
        let body = json_body(refused).await;
        assert_eq!(body["error"]["details"][0]["field"], field);
        assert_eq!(body["error"]["details"][0]["reason"], "INVALID_ENUM_VALUE");
    }

    // Both shape a page, so both are refused on the unpaged read rather than ignored.
    for (query, field) in [("sort=name", "sort"), ("order=desc", "order")] {
        let refused = router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/employees?tenant_id={tenant_ulid}&{query}"),
                &cookie,
            ))
            .await
            .expect("route an unpaged shaping param");
        assert_eq!(refused.status(), StatusCode::BAD_REQUEST);
        assert_eq!(
            json_body(refused).await["error"]["details"][0]["field"],
            field
        );
    }
}

#[tokio::test]
async fn people_writes_require_manage_people_and_the_roster_needs_people_read() {
    let admin = provisioned_admin();
    let router = people_app_with_audit(
        admin.clone(),
        FakePeople::default(),
        Arc::new(NoopAuditRecorder),
    );
    let tenant_ulid = tenant().as_ulid().to_string();

    // A Viewer may not read the roster — a staff record needs console.people.read (ADR-0158)…
    let viewer = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/employees?tenant_id={tenant_ulid}"),
            &viewer,
        ))
        .await
        .expect("route read");
    assert_eq!(
        read.status(),
        StatusCode::FORBIDDEN,
        "the roster needs console.people.read, not console.data.read"
    );

    // …still reads the role templates, which name nobody…
    let roles = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/roles?tenant_id={tenant_ulid}"),
            &viewer,
        ))
        .await
        .expect("route list roles");
    assert_eq!(
        roles.status(),
        StatusCode::OK,
        "role templates need only console.data.read"
    );

    // …and may not create an employee (that needs console.people.manage).
    let forbidden = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/employees",
            &serde_json::json!({ "tenant_id": tenant_ulid, "code": "C01", "name": "Alice" }),
            &viewer,
        ))
        .await
        .expect("route create");
    assert_eq!(forbidden.status(), StatusCode::FORBIDDEN);

    // Ops cannot manage people either.
    let ops = role_session_cookie(&admin, AdminRole::Ops, "ops-token").await;
    let ops_forbidden = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/roles",
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Cashier", "permissions": [] }),
            &ops,
        ))
        .await
        .expect("route create role");
    assert_eq!(ops_forbidden.status(), StatusCode::FORBIDDEN);
}

/// Every read that hands back a person — the roster, one employee, and the assignment list, whose
/// rows name who they grant — needs `console.people.read`, which only Owner and Admin hold
/// ([ADR-0158](../../docs/adr/0158-the-till-enforces-each-persons-own-permissions.md) decision 9).
///
/// A name and a staff code are T1 personal data (ADR-0070), and these reads sat behind
/// `console.data.read`, which Ops and Viewer hold too. The permission catalogue and the role
/// templates name nobody, so every role keeps them.
#[tokio::test]
async fn staff_records_need_people_read_which_ops_and_viewer_do_not_hold() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let (alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let router = people_app_with_audit(admin.clone(), people, Arc::new(NoopAuditRecorder));

    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let alice_ulid = alice.as_ulid().to_string();
    let staff_records = [
        format!("/admin/employees?tenant_id={tenant_ulid}"),
        format!("/admin/employees?tenant_id={tenant_ulid}&limit=10"),
        format!("/admin/employees/{alice_ulid}?tenant_id={tenant_ulid}"),
        format!("/admin/assignments?tenant_id={tenant_ulid}&store_id={store_ulid}"),
        format!("/admin/assignments?tenant_id={tenant_ulid}&employee_id={alice_ulid}"),
    ];
    let naming_nobody = [
        "/admin/people/permissions".to_owned(),
        format!("/admin/roles?tenant_id={tenant_ulid}"),
        format!("/admin/roles/{}?tenant_id={tenant_ulid}", cashier.as_ulid()),
    ];

    for (role, token, reads_staff) in [
        (AdminRole::Viewer, "viewer-staff", false),
        (AdminRole::Ops, "ops-staff", false),
        (AdminRole::Admin, "admin-staff", true),
        (AdminRole::Owner, "owner-staff", true),
    ] {
        let cookie = role_session_cookie(&admin, role, token).await;
        for url in &staff_records {
            let response = router
                .clone()
                .oneshot(get_with_cookie(url, &cookie))
                .await
                .expect("route a staff read");
            if reads_staff {
                assert_eq!(response.status(), StatusCode::OK, "{role:?} reads {url}");
                let body = json_body(response).await.to_string();
                assert!(
                    body.contains("Alice"),
                    "{role:?} is shown the person: {body}"
                );
            } else {
                assert_eq!(
                    response.status(),
                    StatusCode::FORBIDDEN,
                    "{role:?} lacks console.people.read, so {url} is refused"
                );
            }
        }
        for url in &naming_nobody {
            let response = router
                .clone()
                .oneshot(get_with_cookie(url, &cookie))
                .await
                .expect("route a read that names nobody");
            assert_eq!(
                response.status(),
                StatusCode::OK,
                "{role:?} reads {url}, which needs only console.data.read"
            );
        }
    }
}

/// The main app merged with the people-publish router, sharing one config-tree fake so the test can
/// read back the node the publish wrote.
fn people_publish_app(
    admin: FakeAdmin,
    people: FakePeople,
    config: FakeConfigTrees,
    audit: Arc<dyn AuditRecorder>,
) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config.clone(),
        FakeWebhooks::default(),
    );
    http::router(app).merge(http::people_publish_router(
        people,
        config,
        admin,
        clock(),
        audit,
    ))
}

#[tokio::test]
async fn publishing_permissions_writes_the_config_node_without_pii_in_the_audit() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let mine = tenant();
    let store = store_id();

    // Seed a store's people directly through the seam: an employee with a PIN, a role, an assignment.
    seed_a_cashier(&people, store).await;

    let router = people_publish_app(
        admin,
        people.clone(),
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;

    let published = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/people/publish",
            &serde_json::json!({
                "tenant_id": mine.as_ulid().to_string(),
                "store_id": store.as_ulid().to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route publish");
    assert_eq!(published.status(), StatusCode::OK);
    let version = json_body(published).await["config_version_id"]
        .as_str()
        .expect("a version id")
        .to_owned();
    assert!(!version.is_empty());

    // The compiled node landed on the store layer, flattening the role and carrying the PIN hash.
    let state = config
        .load(mine, store)
        .await
        .expect("load")
        .expect("a published tree");
    let node = &state.record.layers[2]["permissions"];
    assert_eq!(
        node["store_id"],
        serde_json::json!(store.as_ulid().to_string())
    );
    let staff = node["staff"].as_array().expect("staff array");
    assert_eq!(staff.len(), 1);
    assert_eq!(staff[0]["code"], serde_json::json!("C01"));
    assert_eq!(
        staff[0]["permissions"],
        serde_json::json!(["billing.discount.apply"])
    );
    assert_eq!(
        staff[0]["pin_phc"],
        serde_json::json!("argon2id$phc$alice"),
        "the PIN hash rides to the store for offline verification"
    );

    // The audit records the publish — the config version and staff count, never a name or PIN.
    let recorded = audit.list(None, 10).await.expect("list audit");
    let entry = recorded
        .iter()
        .find(|entry| entry.action == "permissions.publish")
        .expect("the publish was recorded");
    let dump = serde_json::to_string(&entry.after).expect("serialize");
    assert!(dump.contains("staff_count"), "the staff count is recorded");
    assert!(
        !dump.contains("Alice"),
        "no employee name in the audit trail"
    );
    assert!(
        !dump.to_lowercase().contains("argon2"),
        "no PIN hash in the audit trail"
    );
}

// --- ADR-0158 decision 7: what the console authors is what the store enforces -------------------

/// The staff a store's `permissions` node lists on its Store layer now — none without a tree.
async fn staff_at(config: &FakeConfigTrees, store: StoreId) -> Vec<serde_json::Value> {
    config
        .load(tenant(), store)
        .await
        .expect("load the tree")
        .and_then(|tree| {
            tree.record.layers[2]["permissions"]["staff"]
                .as_array()
                .cloned()
        })
        .unwrap_or_default()
}

/// How many versions a store's tree has been published at.
async fn versions_at(config: &FakeConfigTrees, store: StoreId) -> usize {
    config
        .load(tenant(), store)
        .await
        .expect("load the tree")
        .map_or(0, |tree| tree.record.history.len())
}

/// Publishes a store's people the way the console's button does.
async fn publish_people(router: &axum::Router, cookie: &str, store: StoreId) {
    let published = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/people/publish",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": store.as_ulid().to_string(),
            }),
            cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
}

/// The `(store, outcome)` pairs a write that publishes at once answers with.
async fn publish_report(response: axum::response::Response) -> Vec<(String, String)> {
    json_body(response).await["stores"]
        .as_array()
        .expect("a stores array")
        .iter()
        .map(|row| {
            (
                row["store_id"].as_str().expect("a store id").to_owned(),
                row["outcome"].as_str().expect("an outcome").to_owned(),
            )
        })
        .collect()
}

/// A store as the report names one it published to.
fn applied(store: StoreId) -> (String, String) {
    (
        store.as_ulid().to_string(),
        "PERMISSIONS_PUBLISH_APPLIED".to_owned(),
    )
}

/// Seeds, through the seam, a person and a role that existed and have since been archived.
async fn seed_archived_person_and_role(people: &FakePeople) -> (EmployeeId, RoleTemplateId) {
    let gone = EmployeeId::new(Ulid::from_u128(0x60E));
    let version = EmployeeStore::create(
        people,
        &NewEmployee {
            employee_id: gone,
            tenant_id: tenant(),
            code: "C09".to_owned(),
            name: "Gone".to_owned(),
        },
    )
    .await
    .expect("create employee");
    let archive = EmployeeUpdate {
        employee_id: gone,
        tenant_id: tenant(),
        name: "Gone".to_owned(),
        status: EntityStatus::Archived,
    };
    EmployeeStore::update(people, &archive, &version)
        .await
        .expect("archive employee");
    let retired = RoleTemplateId::new(Ulid::from_u128(0x01D));
    let version = RoleTemplateStore::create(
        people,
        &NewRoleTemplate {
            role_template_id: retired,
            tenant_id: tenant(),
            name: "Old".to_owned(),
            permissions: Vec::new(),
            permissions_with_approval: Vec::new(),
            discount_ceiling_minor: None,
        },
    )
    .await
    .expect("create role");
    let retire = RoleTemplateUpdate {
        role_template_id: retired,
        tenant_id: tenant(),
        name: "Old".to_owned(),
        permissions: Vec::new(),
        permissions_with_approval: Vec::new(),
        discount_ceiling_minor: None,
        status: EntityStatus::Archived,
    };
    RoleTemplateStore::update(people, &retire, &version)
        .await
        .expect("archive role");
    (gone, retired)
}

/// The assignment route checks every id it binds before writing
/// ([ADR-0158](../../../docs/adr/0158-the-till-enforces-each-persons-own-permissions.md) decision 7,
/// and ADR-0070's route check). An employee, store or role the tenant does not have is `404`, one
/// it has archived is `409`, and each refusal names the field that carried the id.
#[tokio::test]
async fn an_assignment_to_an_unknown_or_archived_person_store_or_role_is_refused() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let (alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let (gone, retired) = seed_archived_person_and_role(&people).await;
    let registry = FakeRegistry::default();
    let open = StoreId::new(Ulid::from_u128(0x0BE));
    let closed = StoreId::new(Ulid::from_u128(0xC1));
    seed_store(&registry, tenant(), open, true);
    seed_store(&registry, tenant(), closed, false);
    let router = people_app(
        admin,
        people.clone(),
        registry,
        FakeConfigTrees::default(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    // Every id good: Alice, at a second store that is open, as a Cashier.
    let good = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "employee_id": alice.as_ulid().to_string(),
        "store_id": open.as_ulid().to_string(),
        "role_template_id": cashier.as_ulid().to_string(),
    });

    // Each field in turn names something the tenant never had, then something it has archived.
    let nobody = Ulid::from_u128(0xDEAD).to_string();
    for (field, archived) in [
        ("employee_id", gone.as_ulid().to_string()),
        ("store_id", closed.as_ulid().to_string()),
        ("role_template_id", retired.as_ulid().to_string()),
    ] {
        for (id, status, reason) in [
            (&nobody, StatusCode::NOT_FOUND, "NOT_FOUND"),
            (&archived, StatusCode::CONFLICT, "ARCHIVED"),
        ] {
            let mut request = good.clone();
            request[field] = serde_json::json!(id);
            let refused = router
                .clone()
                .oneshot(post_with_cookie("/admin/assignments", &request, &owner))
                .await
                .expect("route the assignment");
            assert_eq!(refused.status(), status, "{field} {reason}");
            let error = json_body(refused).await;
            let detail = &error["error"]["details"][0];
            assert_eq!(detail["field"], field, "{error}");
            assert_eq!(detail["reason"], reason, "{error}");
        }
    }
    let held = AssignmentStore::list_for_employee(&people, tenant(), alice)
        .await
        .expect("list");
    assert_eq!(
        held.len(),
        1,
        "no refusal wrote anything: Alice holds only her seeded grant"
    );

    let assigned = router
        .clone()
        .oneshot(post_with_cookie("/admin/assignments", &good, &owner))
        .await
        .expect("route the assignment");
    assert_eq!(
        assigned.status(),
        StatusCode::CREATED,
        "every id good, so it is written"
    );
}

/// Removing an assignment publishes its store's `permissions` node at once, so the person cannot
/// sign in there a moment longer (ADR-0158 decision 7). The answer says how the store's publish
/// went; the trail records the removal by the ids it bound and the publish by its version and
/// count.
#[tokio::test]
async fn removing_an_assignment_takes_the_person_off_the_stores_node_at_once() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let (alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let router = people_app(
        admin,
        people,
        FakeRegistry::default(),
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let owner = admin_cookie(&router).await;
    publish_people(&router, &owner, store_id()).await;
    assert_eq!(
        staff_at(&config, store_id()).await.len(),
        1,
        "Alice is on the node"
    );

    let grant = AssignmentId::new(Ulid::from_u128(1));
    let removed = router
        .clone()
        .oneshot(delete_with_cookie(
            &format!(
                "/admin/assignments/{}?tenant_id={}",
                grant.as_ulid(),
                tenant().as_ulid()
            ),
            &owner,
        ))
        .await
        .expect("route the removal");
    assert_eq!(removed.status(), StatusCode::OK);
    assert_eq!(publish_report(removed).await, vec![applied(store_id())]);
    assert!(
        staff_at(&config, store_id()).await.is_empty(),
        "the store's node no longer lists her, without anyone pressing publish"
    );

    let recorded = audit.list(None, 20).await.expect("list audit");
    let removal = recorded
        .iter()
        .find(|entry| entry.action == "assignment.remove")
        .expect("the removal is recorded");
    assert_eq!(
        removal.before,
        Some(serde_json::json!({
            "id": grant.to_string(),
            "employee_id": alice.to_string(),
            "scope_kind": "ASSIGNMENT_SCOPE_STORE",
            "store_id": store_id().to_string(),
            "role_template_id": cashier.to_string(),
        })),
        "the ids it bound, and no name or code"
    );
    let caused = recorded
        .iter()
        .find(|entry| {
            entry.action == "permissions.publish"
                && entry
                    .after
                    .as_ref()
                    .is_some_and(|after| after.get("assignment_id").is_some())
        })
        .expect("the publish the removal caused is recorded");
    assert_eq!(caused.entity_id, store_id().to_string());
    let after = caused.after.as_ref().expect("an after");
    assert_eq!(after["assignment_id"], serde_json::json!(grant.to_string()));
    assert_eq!(after["staff_count"], 0);
    assert!(
        !serde_json::to_string(after)
            .expect("serialise")
            .contains("Alice"),
        "never a name"
    );
}

/// Archiving a person publishes the node at once to every store they work at; a rename publishes as
/// before, which is to say not until someone presses publish (ADR-0158 decision 7).
#[tokio::test]
async fn archiving_a_person_tells_every_store_they_work_at_and_a_rename_tells_none() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let second = StoreId::new(Ulid::from_u128(0x5EC));
    AssignmentStore::assign(
        &people,
        &NewAssignment {
            assignment_id: AssignmentId::new(Ulid::from_u128(2)),
            tenant_id: tenant(),
            employee_id: alice,
            scope: AssignmentScope::Store(second),
            role_template_id: cashier,
        },
    )
    .await
    .expect("assign the second store");
    let router = people_app(
        admin,
        people,
        FakeRegistry::default(),
        config.clone(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    for store in [store_id(), second] {
        publish_people(&router, &owner, store).await;
    }
    let tenant_ulid = tenant().as_ulid().to_string();
    let url = format!("/admin/employees/{}", alice.as_ulid());

    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("{url}?tenant_id={tenant_ulid}"),
            &owner,
        ))
        .await
        .expect("route the read");
    let renamed = router
        .clone()
        .oneshot(patch_with_etag(
            &url,
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Alice Nguyen", "status": "active" }),
            &owner,
            &etag_of(&read),
        ))
        .await
        .expect("route the rename");
    assert_eq!(
        renamed.status(),
        StatusCode::NO_CONTENT,
        "a rename answers as before"
    );
    for store in [store_id(), second] {
        assert_eq!(
            versions_at(&config, store).await,
            1,
            "and publishes nothing"
        );
    }

    let archived = router
        .clone()
        .oneshot(patch_with_etag(
            &url,
            &serde_json::json!({ "tenant_id": tenant_ulid, "name": "Alice Nguyen", "status": "archived" }),
            &owner,
            &etag_of(&renamed),
        ))
        .await
        .expect("route the archive");
    assert_eq!(archived.status(), StatusCode::OK);
    assert!(
        !etag_of(&archived).is_empty(),
        "the person's new version still comes back"
    );
    let mut expected = vec![applied(store_id()), applied(second)];
    expected.sort();
    assert_eq!(
        publish_report(archived).await,
        expected,
        "both of her stores, at once"
    );
    for store in [store_id(), second] {
        assert!(
            staff_at(&config, store).await.is_empty(),
            "she is off {store}'s node"
        );
        assert_eq!(versions_at(&config, store).await, 2);
    }
}

/// Archiving a role publishes the node at once to every store where someone holds it, and there it
/// grants nothing: the person stays on the roster through the assignment and holds what their other
/// roles grant, here nothing (ADR-0158 decision 7). A store where nobody holds the role is left
/// alone.
#[tokio::test]
async fn archiving_a_role_takes_what_it_granted_off_every_store_that_held_it() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let elsewhere = StoreId::new(Ulid::from_u128(0x5EC));
    let cook = RoleTemplateId::new(Ulid::from_u128(0xC00C));
    RoleTemplateStore::create(
        &people,
        &NewRoleTemplate {
            role_template_id: cook,
            tenant_id: tenant(),
            name: "Cook".to_owned(),
            permissions: vec!["sales.ticket.bump".to_owned()],
            permissions_with_approval: Vec::new(),
            discount_ceiling_minor: None,
        },
    )
    .await
    .expect("create role");
    AssignmentStore::assign(
        &people,
        &NewAssignment {
            assignment_id: AssignmentId::new(Ulid::from_u128(2)),
            tenant_id: tenant(),
            employee_id: alice,
            scope: AssignmentScope::Store(elsewhere),
            role_template_id: cook,
        },
    )
    .await
    .expect("assign");
    let router = people_app(
        admin,
        people,
        FakeRegistry::default(),
        config.clone(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    for store in [store_id(), elsewhere] {
        publish_people(&router, &owner, store).await;
    }
    let tenant_ulid = tenant().as_ulid().to_string();
    let url = format!("/admin/roles/{}", cashier.as_ulid());
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("{url}?tenant_id={tenant_ulid}"),
            &owner,
        ))
        .await
        .expect("route the read");

    let archived = router
        .clone()
        .oneshot(patch_with_etag(
            &url,
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Cashier",
                "permissions": ["billing.discount.apply"],
                "status": "archived",
            }),
            &owner,
            &etag_of(&read),
        ))
        .await
        .expect("route the archive");
    assert_eq!(archived.status(), StatusCode::OK);
    assert_eq!(
        publish_report(archived).await,
        vec![applied(store_id())],
        "only the store where someone holds the role"
    );
    let staff = staff_at(&config, store_id()).await;
    assert_eq!(
        staff.len(),
        1,
        "Alice stays on the roster through her assignment"
    );
    assert_eq!(
        staff[0]["permissions"],
        serde_json::json!([]),
        "but the archived role grants her nothing"
    );
    assert_eq!(
        versions_at(&config, elsewhere).await,
        1,
        "the other store was left alone"
    );
    assert_eq!(
        staff_at(&config, elsewhere).await[0]["permissions"],
        serde_json::json!(["sales.ticket.bump"])
    );
}

/// A person with a store's role and a tenant-wide one holds, at that store, the union of their
/// permissions and the highest of their ceilings (ADR-0158 decision 3). The tenant-wide grant is
/// made through the route, which publishes it to the store at once.
#[tokio::test]
async fn a_person_with_a_stores_role_and_a_tenant_wide_role_holds_both_there() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (alice, _cashier) = seed_a_cashier(&people, store_id()).await;
    let lead = RoleTemplateId::new(Ulid::from_u128(0x1EAD));
    RoleTemplateStore::create(
        &people,
        &NewRoleTemplate {
            role_template_id: lead,
            tenant_id: tenant(),
            name: "Shift lead".to_owned(),
            permissions: vec![
                "cash.shift.open".to_owned(),
                "billing.discount.apply".to_owned(),
            ],
            permissions_with_approval: Vec::new(),
            discount_ceiling_minor: Some(50_000),
        },
    )
    .await
    .expect("create role");
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    let router = people_app(
        provisioned_admin(),
        people,
        registry,
        config.clone(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    let everywhere = [("scope_kind", "ASSIGNMENT_SCOPE_TENANT".to_owned())];
    let created =
        post_assignment(&router, &owner, &assignment_body(alice, lead, &everywhere)).await;
    assert_eq!(created.status(), StatusCode::CREATED);
    assert_eq!(publish_report(created).await, vec![applied(store_id())]);

    let staff = staff_at(&config, store_id()).await;
    assert_eq!(staff.len(), 1, "one person, listed once");
    assert_eq!(
        staff[0]["permissions"],
        serde_json::json!(["billing.discount.apply", "cash.shift.open"]),
        "both roles, once each"
    );
    assert_eq!(
        staff[0]["discount_ceiling_minor"], 50_000,
        "the higher ceiling"
    );
}

/// A role grants each permission directly or with approval
/// ([ADR-0158](../../../docs/adr/0158-the-till-enforces-each-persons-own-permissions.md)
/// decision 4), and a create says which in two lists. One that leaves `permissions_with_approval`
/// out grants every permission it lists directly, as before the list existed, and reads back as
/// it was sent, PIN-flagged ids included: only a direct holder approves, so a script or an old
/// console tab must not create roles whose holders can no longer approve. The console's role
/// editor, which always sends both lists, is where a PIN-flagged permission starts with approval.
/// The audit entry records both lists apart.
#[tokio::test]
async fn a_new_role_grants_with_approval_only_what_it_says() {
    let admin = provisioned_admin();
    let audit = FakeAudit::default();
    let router = people_app_with_audit(
        admin,
        FakePeople::default(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let owner = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();

    for (body, directly, with_approval) in [
        (
            serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Shift lead",
                "permissions": ["billing.bill.void", "sales.line.add", "cash.drawer.open_no_sale"],
            }),
            serde_json::json!([
                "billing.bill.void",
                "sales.line.add",
                "cash.drawer.open_no_sale"
            ]),
            serde_json::json!([]),
        ),
        (
            serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Manager",
                "permissions": ["billing.bill.void", "sales.line.add"],
                "permissions_with_approval": [],
            }),
            serde_json::json!(["billing.bill.void", "sales.line.add"]),
            serde_json::json!([]),
        ),
        (
            serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Server",
                "permissions": ["sales.line.add"],
                "permissions_with_approval": ["sales.line.void_fired"],
            }),
            serde_json::json!(["sales.line.add"]),
            serde_json::json!(["sales.line.void_fired"]),
        ),
    ] {
        let created = router
            .clone()
            .oneshot(post_with_cookie("/admin/roles", &body, &owner))
            .await
            .expect("route the create");
        assert_eq!(created.status(), StatusCode::CREATED, "{body}");
        let id = json_body(created).await["id"]
            .as_str()
            .expect("an id")
            .to_owned();
        let read = router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/roles/{id}?tenant_id={tenant_ulid}"),
                &owner,
            ))
            .await
            .expect("route the read");
        let role = json_body(read).await;
        assert_eq!(role["permissions"], directly, "granted directly: {body}");
        assert_eq!(
            role["permissions_with_approval"], with_approval,
            "granted with approval: {body}"
        );
    }

    let recorded = audit.list(None, 50).await.expect("list audit");
    let after = recorded
        .iter()
        .filter(|entry| entry.action == "role.create")
        .filter_map(|entry| entry.after.as_ref())
        .find(|after| after["name"] == "Server")
        .expect("the create is audited");
    assert_eq!(after["permissions"], serde_json::json!(["sales.line.add"]));
    assert_eq!(
        after["permissions_with_approval"],
        serde_json::json!(["sales.line.void_fired"])
    );
}

/// What a role grants with approval must be catalogue permissions, each PIN-flagged and none also
/// granted directly (ADR-0158 decision 4). A create or an update that lists otherwise is refused
/// `400`, naming the field and why.
#[tokio::test]
async fn a_role_write_refuses_an_approval_that_is_unknown_unflagged_or_also_direct() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let router = people_app_with_audit(admin, people, Arc::new(NoopAuditRecorder));
    let owner = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let url = format!("/admin/roles/{}", cashier.as_ulid());
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("{url}?tenant_id={tenant_ulid}"),
            &owner,
        ))
        .await
        .expect("route the read");
    let etag = etag_of(&read);

    for (directly, with_approval, refused_fields, reason) in [
        (
            serde_json::json!([]),
            serde_json::json!(["not.a.real.permission"]),
            vec!["permissions_with_approval"],
            "INVALID_ENUM_VALUE",
        ),
        (
            serde_json::json!([]),
            serde_json::json!(["sales.line.add"]),
            vec!["permissions_with_approval"],
            "INVALID_VALUE",
        ),
        (
            serde_json::json!(["billing.bill.void"]),
            serde_json::json!(["billing.bill.void"]),
            vec!["permissions", "permissions_with_approval"],
            "MUTUALLY_EXCLUSIVE",
        ),
    ] {
        let body = serde_json::json!({
            "tenant_id": tenant_ulid,
            "name": "Cashier",
            "permissions": directly,
            "permissions_with_approval": with_approval,
            "status": "active",
        });
        for request in [
            post_with_cookie("/admin/roles", &body, &owner),
            patch_with_etag(&url, &body, &owner, &etag),
        ] {
            let refused = router
                .clone()
                .oneshot(request)
                .await
                .expect("route the write");
            assert_eq!(refused.status(), StatusCode::BAD_REQUEST, "{body}");
            let error = json_body(refused).await;
            let named: Vec<(&str, &str)> = error["error"]["details"]
                .as_array()
                .expect("details")
                .iter()
                .map(|detail| {
                    (
                        detail["field"].as_str().expect("a field"),
                        detail["reason"].as_str().expect("a reason"),
                    )
                })
                .collect();
            let expected: Vec<(&str, &str)> = refused_fields
                .iter()
                .map(|field| (*field, reason))
                .collect();
            assert_eq!(named, expected, "{error}");
        }
    }
}

/// An update written before roles said what they grant with approval keeps working (ADR-0158
/// decision 4). Leaving `permissions_with_approval` out keeps what the role grants with approval,
/// less anything the update now grants directly, and the store's node lists each person's two
/// lists apart.
#[tokio::test]
async fn an_update_that_leaves_approval_out_keeps_it_less_what_it_now_grants_directly() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    // The Cashier as migration 0074 leaves one: the direct list as it was, and two acts with approval.
    people.roles.rows.lock().expect("lock")[0]
        .record
        .permissions_with_approval = vec![
        "billing.bill.void".to_owned(),
        "sales.line.void_fired".to_owned(),
    ];
    let router = people_app(
        admin,
        people,
        FakeRegistry::default(),
        config.clone(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let url = format!("/admin/roles/{}", cashier.as_ulid());
    let read_url = format!("{url}?tenant_id={tenant_ulid}");

    // A console from before the list: the void is now granted directly, and nothing else is said.
    let before = router
        .clone()
        .oneshot(get_with_cookie(&read_url, &owner))
        .await
        .expect("route the read");
    let updated = router
        .clone()
        .oneshot(patch_with_etag(
            &url,
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Cashier",
                "permissions": ["billing.discount.apply", "sales.line.void_fired"],
                "status": "active",
            }),
            &owner,
            &etag_of(&before),
        ))
        .await
        .expect("route the update");
    assert_eq!(updated.status(), StatusCode::NO_CONTENT);
    let after = router
        .clone()
        .oneshot(get_with_cookie(&read_url, &owner))
        .await
        .expect("route the read");
    let after_etag = etag_of(&after);
    let role = json_body(after).await;
    assert_eq!(
        role["permissions_with_approval"],
        serde_json::json!(["billing.bill.void"]),
        "kept, less the void it now grants directly: {role}"
    );
    publish_people(&router, &owner, store_id()).await;
    let staff = staff_at(&config, store_id()).await;
    assert_eq!(
        staff[0]["permissions"],
        serde_json::json!(["billing.discount.apply", "sales.line.void_fired"])
    );
    assert_eq!(
        staff[0]["permissions_with_approval"],
        serde_json::json!(["billing.bill.void"])
    );

    // Saying `[]` is saying something: nothing with approval.
    let cleared = router
        .clone()
        .oneshot(patch_with_etag(
            &url,
            &serde_json::json!({
                "tenant_id": tenant_ulid,
                "name": "Cashier",
                "permissions": ["billing.discount.apply"],
                "permissions_with_approval": [],
                "status": "active",
            }),
            &owner,
            &after_etag,
        ))
        .await
        .expect("route the update");
    assert_eq!(cleared.status(), StatusCode::NO_CONTENT);
    let cleared = router
        .clone()
        .oneshot(get_with_cookie(&read_url, &owner))
        .await
        .expect("route the read");
    let role = json_body(cleared).await;
    assert_eq!(role["permissions_with_approval"], serde_json::json!([]));
}

/// The main app merged with the provider-catalogue router (ADR-0153).
fn provider_catalogue_app(admin: FakeAdmin) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        FakeConfigTrees::default(),
        FakeWebhooks::default(),
    );
    let providers = pos_cloud::providers::registry().expect("the compiled-in catalogue is valid");
    http::router(app).merge(http::provider_catalogue_router(
        Arc::new(providers),
        admin,
        clock(),
    ))
}

#[tokio::test]
async fn the_provider_catalogue_serves_each_vendors_form_to_any_admin() {
    let admin = provisioned_admin();
    let router = provider_catalogue_app(admin.clone());

    // No session, no catalogue: it names the vendors a tenant could connect, which is not public.
    let response = router
        .clone()
        .oneshot(
            Request::builder()
                .uri("/admin/integrations/providers")
                .body(Body::empty())
                .expect("request"),
        )
        .await
        .expect("route the catalogue");
    assert_eq!(response.status(), StatusCode::UNAUTHORIZED);

    // Every console role may read it — a Viewer included — because it describes the platform.
    let viewer = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let response = router
        .oneshot(get_with_cookie("/admin/integrations/providers", &viewer))
        .await
        .expect("route the catalogue");
    assert_eq!(response.status(), StatusCode::OK);
    let body = json_body(response).await;
    let providers = body["providers"].as_array().expect("a providers list");
    let sap = providers
        .iter()
        .find(|provider| provider["provider_id"] == "erp.sap")
        .expect("the ERP adapter is listed");
    assert_eq!(sap["family"], "INTEGRATION_FAMILY_ERP");
    assert_eq!(
        sap["countries"],
        serde_json::json!([]),
        "SAP serves every country"
    );
    let keys: Vec<&str> = sap["fields"]
        .as_array()
        .expect("a schema")
        .iter()
        .filter_map(|field| field["key"].as_str())
        .collect();
    assert_eq!(keys, vec!["base_url", "timeout_seconds"]);
}

/// The main app merged with the capability-catalogue router.
fn capabilities_app(admin: FakeAdmin) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        FakeConfigTrees::default(),
        FakeWebhooks::default(),
    );
    http::router(app).merge(http::capabilities_router(admin, clock()))
}

#[tokio::test]
async fn capability_catalogue_serves_flags_presets_and_rules_to_any_admin() {
    let admin = provisioned_admin();
    let router = capabilities_app(admin.clone());

    // Read is open to every console role — a Viewer may load the catalogue.
    let viewer = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let response = router
        .clone()
        .oneshot(get_with_cookie("/admin/capabilities", &viewer))
        .await
        .expect("route the catalogue");
    assert_eq!(response.status(), StatusCode::OK);
    let body = json_body(response).await;

    // Flags carry key/default/description; the well-known ones are present.
    let flags = body["flags"].as_array().expect("flags array");
    assert!(!flags.is_empty());
    let keys: Vec<&str> = flags
        .iter()
        .map(|flag| flag["key"].as_str().expect("a key"))
        .collect();
    assert!(keys.contains(&"tables_enabled"));
    assert!(keys.contains(&"pay_first_enabled"));
    let tables = flags
        .iter()
        .find(|flag| flag["key"] == serde_json::json!("tables_enabled"))
        .expect("the tables flag");
    assert_eq!(tables["default_on"], serde_json::json!(true));
    assert!(tables["description"].as_str().expect("a description").len() > 5);

    // The three presets are offered, each as a set of keys.
    let presets = body["presets"].as_array().expect("presets array");
    let preset_ids: Vec<&str> = presets
        .iter()
        .map(|preset| preset["id"].as_str().expect("an id"))
        .collect();
    assert!(preset_ids.contains(&"full_service"));
    assert!(preset_ids.contains(&"counter"));
    assert!(preset_ids.contains(&"retail"));

    // The inter-flag rules are served for the console's conflict preview.
    let rules = body["rules"].as_array().expect("rules array");
    let rule_ids: Vec<&str> = rules
        .iter()
        .map(|rule| rule["id"].as_str().expect("an id"))
        .collect();
    assert!(rule_ids.contains(&"pay_first.excludes.tables"));
    assert!(rule_ids.contains(&"seats.requires.tables"));
}

/// The console offers a switch only where a release reads it (ADR-0160 decision 5): tabs, pay-first,
/// barcode entry and queue numbers stay in the catalogue, marked not offered, and the presets that
/// turn them on still name them; every other flag is offered.
#[tokio::test]
async fn the_catalogue_offers_only_the_switches_a_release_reads() {
    let admin = provisioned_admin();
    let router = capabilities_app(admin.clone());
    let viewer = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let body = json_body(
        router
            .oneshot(get_with_cookie("/admin/capabilities", &viewer))
            .await
            .expect("route the catalogue"),
    )
    .await;

    let offered: Vec<(&str, bool)> = body["flags"]
        .as_array()
        .expect("flags array")
        .iter()
        .map(|flag| {
            (
                flag["key"].as_str().expect("a key"),
                flag["offered"].as_bool().expect("offered is a boolean"),
            )
        })
        .collect();
    assert_eq!(
        offered,
        vec![
            ("tables_enabled", true),
            ("tabs_enabled", false),
            ("seats_enabled", true),
            ("kds_enabled", true),
            ("courses_enabled", true),
            ("pay_first_enabled", false),
            ("barcode_enabled", false),
            ("queue_number_enabled", false),
            ("tips_enabled", true),
            ("qr_ordering_enabled", true),
        ]
    );
    let counter = body["presets"]
        .as_array()
        .expect("presets array")
        .iter()
        .find(|preset| preset["id"] == "counter")
        .expect("the counter preset");
    assert!(
        counter["keys"]
            .as_array()
            .expect("keys")
            .contains(&serde_json::json!("pay_first_enabled")),
        "the preset is unchanged: {counter}"
    );
}

// --- ADR-0158 decision 3: an assignment reaches a store, a store group or every store -----------

/// A store these tests assign people through, numbered so the reports' store order is the order
/// the tests list them in.
fn shop(n: u128) -> StoreId {
    StoreId::new(Ulid::from_u128(0x4000 + n))
}

/// Seeds a person through the seam and returns their id.
async fn seed_person(people: &FakePeople, n: u128, code: &str, name: &str) -> EmployeeId {
    let employee_id = EmployeeId::new(Ulid::from_u128(n));
    EmployeeStore::create(
        people,
        &NewEmployee {
            employee_id,
            tenant_id: tenant(),
            code: code.to_owned(),
            name: name.to_owned(),
        },
    )
    .await
    .expect("create employee");
    employee_id
}

/// Seeds an active store group holding `members`, in the groups the roster's group assignments
/// reach through, and returns its id.
fn seed_group(people: &FakePeople, n: u128, members: &[StoreId]) -> StoreGroupId {
    let group_id = StoreGroupId::new(Ulid::from_u128(n));
    people.groups().seed(
        StoreGroup {
            group_id,
            tenant_id: tenant(),
            name: format!("Group {n}"),
            status: EntityStatus::Active,
        },
        members,
    );
    group_id
}

/// Seeds an assignment through the seam, as one written earlier.
async fn seed_assignment(
    people: &FakePeople,
    n: u128,
    employee_id: EmployeeId,
    scope: AssignmentScope,
    role_template_id: RoleTemplateId,
) -> AssignmentId {
    let assignment_id = AssignmentId::new(Ulid::from_u128(n));
    AssignmentStore::assign(
        people,
        &NewAssignment {
            assignment_id,
            tenant_id: tenant(),
            employee_id,
            scope,
            role_template_id,
        },
    )
    .await
    .expect("assign");
    assignment_id
}

/// The staff codes a store's node lists now.
async fn codes_at(config: &FakeConfigTrees, store: StoreId) -> Vec<String> {
    staff_at(config, store)
        .await
        .iter()
        .map(|member| member["code"].as_str().expect("a code").to_owned())
        .collect()
}

/// A `POST /admin/assignments` body for `employee` with `role`, at the target `fields` name.
fn assignment_body(
    employee: EmployeeId,
    role: RoleTemplateId,
    fields: &[(&str, String)],
) -> serde_json::Value {
    let mut body = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "employee_id": employee.as_ulid().to_string(),
        "role_template_id": role.as_ulid().to_string(),
    });
    for (field, value) in fields {
        body[*field] = serde_json::json!(value);
    }
    body
}

/// Assigns through the route, as the console does.
async fn post_assignment(
    router: &axum::Router,
    cookie: &str,
    body: &serde_json::Value,
) -> axum::response::Response {
    router
        .clone()
        .oneshot(post_with_cookie("/admin/assignments", body, cookie))
        .await
        .expect("route the assignment")
}

/// The assignments a listing returns, read through the route.
async fn listed(router: &axum::Router, cookie: &str, query: &str) -> Vec<serde_json::Value> {
    let response = router
        .clone()
        .oneshot(get_with_cookie(
            &format!(
                "/admin/assignments?tenant_id={}&{query}",
                tenant().as_ulid()
            ),
            cookie,
        ))
        .await
        .expect("route the listing");
    assert_eq!(response.status(), StatusCode::OK, "{query}");
    json_body(response)
        .await
        .as_array()
        .expect("an array")
        .clone()
}

/// The people routes and the store-group routes over one roster and one set of groups, as
/// `main.rs` wires them: a membership change reaches the people the group's assignments name.
fn people_and_groups_app(
    admin: FakeAdmin,
    people: FakePeople,
    registry: FakeRegistry,
    config: FakeConfigTrees,
    audit: Arc<dyn AuditRecorder>,
) -> axum::Router {
    people_app(
        admin.clone(),
        people.clone(),
        registry.clone(),
        config.clone(),
        Arc::clone(&audit),
    )
    .merge(http::store_group_router(
        people.groups(),
        registry,
        config,
        Vec::new(),
        people,
        admin,
        clock(),
        audit,
    ))
}

/// An assignment to every store publishes at once to each open store of the tenant, and not to an
/// archived one; a store opened afterwards lists the person from its first publish (ADR-0158
/// decision 3).
#[tokio::test]
async fn an_assignment_to_every_store_reaches_each_open_store_and_one_opened_later() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    seed_store(&registry, tenant(), shop(1), true);
    seed_store(&registry, tenant(), shop(2), false);
    let router = people_app(
        provisioned_admin(),
        people,
        registry.clone(),
        config.clone(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;

    let everywhere = [("scope_kind", "ASSIGNMENT_SCOPE_TENANT".to_owned())];
    let created =
        post_assignment(&router, &owner, &assignment_body(bao, cashier, &everywhere)).await;
    assert_eq!(created.status(), StatusCode::CREATED);
    assert_eq!(
        publish_report(created).await,
        vec![applied(store_id()), applied(shop(1))],
        "published at once to each open store, and not to the archived one"
    );
    assert_eq!(codes_at(&config, store_id()).await, vec!["C01", "C02"]);
    assert_eq!(codes_at(&config, shop(1)).await, vec!["C02"]);
    assert_eq!(versions_at(&config, shop(2)).await, 0);

    // A store the tenant opens afterwards: nobody names it, and its first publish lists Bao.
    seed_store(&registry, tenant(), shop(3), true);
    publish_people(&router, &owner, shop(3)).await;
    assert_eq!(codes_at(&config, shop(3)).await, vec!["C02"]);
    let rows = listed(&router, &owner, "scope_kind=ASSIGNMENT_SCOPE_TENANT").await;
    assert_eq!(rows.len(), 1, "the tenant's rows, listed by their kind");
    assert_eq!(rows[0]["scope_kind"], "ASSIGNMENT_SCOPE_TENANT");
    assert!(rows[0].get("store_id").is_none() && rows[0].get("store_group_id").is_none());
}

/// An assignment to a store group publishes at once to exactly the stores the group holds, and
/// each listing shows the scope it is at (ADR-0158 decision 3).
#[tokio::test]
async fn an_assignment_to_a_group_reaches_exactly_its_members() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let registry = FakeRegistry::default();
    for store in [shop(1), shop(2), shop(3)] {
        seed_store(&registry, tenant(), store, true);
    }
    let airport = seed_group(&people, 0x6A1, &[shop(1), shop(2)]);
    let router = people_app(
        provisioned_admin(),
        people,
        registry,
        config.clone(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;

    let through = [("store_group_id", airport.as_ulid().to_string())];
    let created = post_assignment(&router, &owner, &assignment_body(bao, cashier, &through)).await;
    assert_eq!(created.status(), StatusCode::CREATED);
    assert_eq!(
        publish_report(created).await,
        vec![applied(shop(1)), applied(shop(2))],
        "each member, and nobody else"
    );
    for member in [shop(1), shop(2)] {
        assert_eq!(codes_at(&config, member).await, vec!["C02"]);
    }
    assert_eq!(versions_at(&config, shop(3)).await, 0, "not a member");
    assert_eq!(
        versions_at(&config, store_id()).await,
        0,
        "nor a store outside the group"
    );

    let by_group = listed(
        &router,
        &owner,
        &format!("store_group_id={}", airport.as_ulid()),
    )
    .await;
    assert_eq!(by_group.len(), 1);
    assert_eq!(by_group[0]["scope_kind"], "ASSIGNMENT_SCOPE_STORE_GROUP");
    assert_eq!(by_group[0]["store_group_id"], airport.as_ulid().to_string());
    assert_eq!(by_group[0]["employee_name"], "Bao");
    let at_member = listed(&router, &owner, &format!("store_id={}", shop(1).as_ulid())).await;
    assert_eq!(
        at_member, by_group,
        "a member's listing shows who works there through it"
    );
    assert!(
        listed(&router, &owner, &format!("store_id={}", shop(3).as_ulid()))
            .await
            .is_empty()
    );
    let refused = router
        .clone()
        .oneshot(get_with_cookie(
            &format!(
                "/admin/assignments?tenant_id={}&scope_kind=ASSIGNMENT_SCOPE_STORE",
                tenant().as_ulid()
            ),
            &owner,
        ))
        .await
        .expect("route the listing");
    assert_eq!(refused.status(), StatusCode::BAD_REQUEST);
    let body = json_body(refused).await;
    assert_eq!(body["error"]["details"][0]["field"], "scope_kind");
    assert_eq!(body["error"]["details"][0]["reason"], "INVALID_ENUM_VALUE");
}

/// A store that joins or leaves a group some assignment names gains or loses those people, and is
/// told at once; a group nothing names changes nobody's node (ADR-0158 decisions 3 and 7).
#[tokio::test]
async fn a_store_that_joins_or_leaves_a_named_group_is_told_at_once() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let registry = FakeRegistry::default();
    for store in [shop(1), shop(2), shop(3)] {
        seed_store(&registry, tenant(), store, true);
    }
    let airport = seed_group(&people, 0x6A1, &[shop(1)]);
    let quiet = seed_group(&people, 0x6A2, &[shop(1)]);
    seed_assignment(
        &people,
        2,
        bao,
        AssignmentScope::StoreGroup(airport),
        cashier,
    )
    .await;
    let router = people_and_groups_app(
        provisioned_admin(),
        people.clone(),
        registry,
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let owner = admin_cookie(&router).await;
    publish_people(&router, &owner, shop(1)).await;
    assert_eq!(codes_at(&config, shop(1)).await, vec!["C02"]);

    let move_members = |group: StoreGroupId, members: Vec<StoreId>| {
        let router = router.clone();
        let owner = owner.clone();
        let groups = people.groups();
        async move {
            let etag = StoreGroupStore::list_groups(&groups, tenant())
                .await
                .expect("list groups")
                .into_iter()
                .find(|row| row.record.group_id == group)
                .expect("the group")
                .etag;
            let ids: Vec<String> = members.iter().map(|id| id.as_ulid().to_string()).collect();
            router
                .oneshot(put_with_etag(
                    &format!("/admin/store-groups/{}/members", group.as_ulid()),
                    &serde_json::json!({ "tenant_id": tenant().as_ulid().to_string(), "store_ids": ids }),
                    &owner,
                    etag.as_str(),
                ))
                .await
                .expect("route the membership")
        }
    };

    let moved = move_members(airport, vec![shop(2)]).await;
    assert_eq!(moved.status(), StatusCode::OK);
    assert_eq!(
        publish_report(moved).await,
        vec![applied(shop(1)), applied(shop(2))],
        "the store that left and the store that joined"
    );
    assert!(
        codes_at(&config, shop(1)).await.is_empty(),
        "off the store that left"
    );
    assert_eq!(
        codes_at(&config, shop(2)).await,
        vec!["C02"],
        "on the one that joined"
    );
    assert_eq!(
        versions_at(&config, shop(3)).await,
        0,
        "untouched by the change"
    );
    let recorded = audit.list(None, 50).await.expect("list audit");
    assert!(
        recorded
            .iter()
            .any(|entry| entry.action == "permissions.publish"
                && entry.after.as_ref().is_some_and(|after| {
                    after["store_group_id"] == serde_json::json!(airport.to_string())
                })),
        "the publish names the group that caused it"
    );

    let unnamed = move_members(quiet, vec![shop(3)]).await;
    assert_eq!(unnamed.status(), StatusCode::OK);
    assert!(
        publish_report(unnamed).await.is_empty(),
        "no assignment names it"
    );
    assert_eq!(versions_at(&config, shop(3)).await, 0);
}

/// Assigning a person where they already hold an assignment is a conflict, not an outage: `409`
/// `ALREADY_EXISTS` naming the field that names the place, at each scope. The refused one writes
/// nothing, records nothing in the trail and publishes nothing, so a store the first reached is
/// published once (ADR-0158 decision 3).
#[tokio::test]
async fn a_second_assignment_at_the_same_place_is_refused_409_and_changes_nothing() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let registry = FakeRegistry::default();
    for store in [store_id(), shop(1)] {
        seed_store(&registry, tenant(), store, true);
    }
    let airport = seed_group(&people, 0x6A1, &[shop(1)]);
    let router = people_app(
        provisioned_admin(),
        people.clone(),
        registry,
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let owner = admin_cookie(&router).await;
    let published = async || {
        [
            versions_at(&config, store_id()).await,
            versions_at(&config, shop(1)).await,
        ]
    };
    let recorded = async || audit.list(None, 100).await.expect("list audit").len();

    for (field, value) in [
        ("store_id", store_id().as_ulid().to_string()),
        ("store_group_id", airport.as_ulid().to_string()),
        ("scope_kind", "ASSIGNMENT_SCOPE_TENANT".to_owned()),
    ] {
        let body = assignment_body(bao, cashier, &[(field, value)]);
        let created = post_assignment(&router, &owner, &body).await;
        assert_eq!(created.status(), StatusCode::CREATED, "{field}");
        let (versions, entries) = (published().await, recorded().await);

        let again = post_assignment(&router, &owner, &body).await;
        assert_eq!(again.status(), StatusCode::CONFLICT, "{field}");
        let error = json_body(again).await;
        assert_eq!(error["error"]["status"], "ALREADY_EXISTS", "{error}");
        assert_eq!(error["error"]["details"][0]["field"], field, "{error}");
        assert_eq!(
            error["error"]["details"][0]["reason"], "ALREADY_EXISTS",
            "{error}"
        );
        assert!(
            error["error"]["message"]
                .as_str()
                .is_some_and(|message| message.contains("change or remove")),
            "it says what resolves it: {error}"
        );
        assert_eq!(published().await, versions, "nothing published ({field})");
        assert_eq!(recorded().await, entries, "nothing recorded ({field})");
    }
    let held = AssignmentStore::list_for_employee(&people, tenant(), bao)
        .await
        .expect("list");
    assert_eq!(
        held.len(),
        3,
        "one at each place, and no refused one written"
    );
}

/// Removing an assignment to a group or to every store publishes at once to every store it
/// reached, and the trail records its scope (ADR-0158 decision 7).
#[tokio::test]
async fn removing_a_wider_assignment_tells_every_store_it_reached() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let cam = seed_person(&people, 0xCA3, "C03", "Cam").await;
    let registry = FakeRegistry::default();
    for store in [store_id(), shop(1), shop(2)] {
        seed_store(&registry, tenant(), store, true);
    }
    let airport = seed_group(&people, 0x6A1, &[shop(1), shop(2)]);
    let grouped = seed_assignment(
        &people,
        2,
        bao,
        AssignmentScope::StoreGroup(airport),
        cashier,
    )
    .await;
    let everywhere = seed_assignment(&people, 3, cam, AssignmentScope::Tenant, cashier).await;
    let router = people_app(
        provisioned_admin(),
        people,
        registry,
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let owner = admin_cookie(&router).await;
    for store in [store_id(), shop(1), shop(2)] {
        publish_people(&router, &owner, store).await;
    }
    let remove = |assignment: AssignmentId| {
        router.clone().oneshot(delete_with_cookie(
            &format!(
                "/admin/assignments/{}?tenant_id={}",
                assignment.as_ulid(),
                tenant().as_ulid()
            ),
            &owner,
        ))
    };

    let removed = remove(grouped).await.expect("route the removal");
    assert_eq!(removed.status(), StatusCode::OK);
    assert_eq!(
        publish_report(removed).await,
        vec![applied(shop(1)), applied(shop(2))]
    );
    assert_eq!(codes_at(&config, shop(1)).await, vec!["C03"], "Bao is off");
    assert_eq!(
        versions_at(&config, store_id()).await,
        1,
        "not a member: untouched"
    );

    let removed = remove(everywhere).await.expect("route the removal");
    assert_eq!(
        publish_report(removed).await,
        vec![applied(store_id()), applied(shop(1)), applied(shop(2))]
    );
    assert_eq!(
        codes_at(&config, store_id()).await,
        vec!["C01"],
        "Cam is off every store"
    );
    assert!(codes_at(&config, shop(2)).await.is_empty());

    let recorded = audit.list(None, 50).await.expect("list audit");
    let removal = recorded
        .iter()
        .find(|entry| entry.action == "assignment.remove" && entry.entity_id == grouped.to_string())
        .expect("the removal is recorded");
    assert_eq!(
        removal.before,
        Some(serde_json::json!({
            "id": grouped.to_string(),
            "employee_id": bao.to_string(),
            "scope_kind": "ASSIGNMENT_SCOPE_STORE_GROUP",
            "store_group_id": airport.to_string(),
            "role_template_id": cashier.to_string(),
        })),
        "the ids and the scope, and no name or code"
    );
}

/// Archiving a person, or a role, publishes at once to every store their assignments reach through
/// a group or the tenant, not only those named one by one (ADR-0158 decision 7).
#[tokio::test]
async fn an_archive_reaches_the_stores_a_group_or_the_tenant_reaches() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let cam = seed_person(&people, 0xCA3, "C03", "Cam").await;
    let lead = RoleTemplateId::new(Ulid::from_u128(0x1EAD));
    RoleTemplateStore::create(
        &people,
        &NewRoleTemplate {
            role_template_id: lead,
            tenant_id: tenant(),
            name: "Shift lead".to_owned(),
            permissions: vec!["cash.shift.open".to_owned()],
            permissions_with_approval: Vec::new(),
            discount_ceiling_minor: None,
        },
    )
    .await
    .expect("create role");
    let registry = FakeRegistry::default();
    for store in [store_id(), shop(1), shop(2)] {
        seed_store(&registry, tenant(), store, true);
    }
    let airport = seed_group(&people, 0x6A1, &[shop(1)]);
    seed_assignment(
        &people,
        2,
        bao,
        AssignmentScope::StoreGroup(airport),
        cashier,
    )
    .await;
    seed_assignment(&people, 3, cam, AssignmentScope::Tenant, lead).await;
    let router = people_app(
        provisioned_admin(),
        people,
        registry,
        config,
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let archive = |url: String, body: serde_json::Value| {
        let router = router.clone();
        let owner = owner.clone();
        let tenant_ulid = tenant_ulid.clone();
        async move {
            let read = router
                .clone()
                .oneshot(get_with_cookie(
                    &format!("{url}?tenant_id={tenant_ulid}"),
                    &owner,
                ))
                .await
                .expect("route the read");
            let archived = router
                .oneshot(patch_with_etag(&url, &body, &owner, &etag_of(&read)))
                .await
                .expect("route the archive");
            assert_eq!(archived.status(), StatusCode::OK, "{url}");
            publish_report(archived).await
        }
    };

    let person = archive(
        format!("/admin/employees/{}", bao.as_ulid()),
        serde_json::json!({ "tenant_id": tenant_ulid, "name": "Bao", "status": "archived" }),
    )
    .await;
    assert_eq!(person, vec![applied(shop(1))], "the group's member");
    let role = archive(
        format!("/admin/roles/{}", lead.as_ulid()),
        serde_json::json!({
            "tenant_id": tenant_ulid,
            "name": "Shift lead",
            "permissions": ["cash.shift.open"],
            "status": "archived",
        }),
    )
    .await;
    assert_eq!(
        role,
        vec![applied(store_id()), applied(shop(1)), applied(shop(2))],
        "every open store, through the tenant-wide assignment"
    );
}

/// A refused assignment's status and the `(field, reason)` pairs its refusal names, in order.
async fn refusal_of(
    router: &axum::Router,
    cookie: &str,
    body: &serde_json::Value,
) -> (StatusCode, Vec<(String, String)>) {
    let refused = post_assignment(router, cookie, body).await;
    let status = refused.status();
    let named = json_body(refused).await["error"]["details"]
        .as_array()
        .expect("details")
        .iter()
        .map(|detail| {
            (
                detail["field"].as_str().expect("a field").to_owned(),
                detail["reason"].as_str().expect("a reason").to_owned(),
            )
        })
        .collect();
    (status, named)
}

/// `(field, reason)` pairs, owned, as [`refusal_of`] returns them.
fn named(pairs: &[(&str, &str)]) -> Vec<(String, String)> {
    pairs
        .iter()
        .map(|(field, reason)| ((*field).to_owned(), (*reason).to_owned()))
        .collect()
}

/// An assignment names exactly one target: its scope's own id, and no other. Anything else is a
/// `400` naming each field at fault, and writes nothing; with no `scope_kind`, or
/// `ASSIGNMENT_SCOPE_UNSPECIFIED`, the id sent names the scope (ADR-0158 decision 3).
#[tokio::test]
async fn an_assignment_names_exactly_its_scopes_own_id() {
    let people = FakePeople::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    let airport = seed_group(&people, 0x6A1, &[store_id()]);
    let router = people_app(
        provisioned_admin(),
        people.clone(),
        registry,
        FakeConfigTrees::default(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    let store = ("store_id", store_id().as_ulid().to_string());
    let group = ("store_group_id", airport.as_ulid().to_string());
    let kind = |token: &str| ("scope_kind", token.to_owned());
    for (fields, expected) in [
        (
            vec![store.clone(), group.clone()],
            named(&[
                ("store_id", "MUTUALLY_EXCLUSIVE"),
                ("store_group_id", "MUTUALLY_EXCLUSIVE"),
            ]),
        ),
        (vec![], named(&[("store_id", "REQUIRED")])),
        (
            vec![kind("ASSIGNMENT_SCOPE_TENANT"), store.clone()],
            named(&[("store_id", "MUTUALLY_EXCLUSIVE")]),
        ),
        (
            vec![kind("ASSIGNMENT_SCOPE_STORE_GROUP"), store.clone()],
            named(&[
                ("store_id", "MUTUALLY_EXCLUSIVE"),
                ("store_group_id", "REQUIRED"),
            ]),
        ),
        (
            vec![kind("ASSIGNMENT_SCOPE_BRAND"), store.clone()],
            named(&[("scope_kind", "INVALID_ENUM_VALUE")]),
        ),
    ] {
        let body = assignment_body(bao, cashier, &fields);
        assert_eq!(
            refusal_of(&router, &owner, &body).await,
            (StatusCode::BAD_REQUEST, expected),
            "{fields:?}"
        );
    }
    assert!(
        AssignmentStore::list_for_employee(&people, tenant(), bao)
            .await
            .expect("list")
            .is_empty(),
        "no refusal wrote anything"
    );

    // `ASSIGNMENT_SCOPE_UNSPECIFIED` is no scope of its own: the id sent says which, and a store's
    // assignment publishes as before, when someone presses publish.
    let body = assignment_body(bao, cashier, &[kind("ASSIGNMENT_SCOPE_UNSPECIFIED"), store]);
    let created = post_assignment(&router, &owner, &body).await;
    assert_eq!(created.status(), StatusCode::CREATED);
    let body = json_body(created).await;
    assert!(body.get("stores").is_none(), "nothing published: {body}");
}

/// An assignment to a group the tenant does not have — another tenant's included — is `404`, and
/// to one it has archived `409`, naming `store_group_id` (ADR-0158 decision 7).
#[tokio::test]
async fn an_assignment_to_a_group_needs_one_of_its_tenants_own_open_groups() {
    let people = FakePeople::default();
    let (_alice, cashier) = seed_a_cashier(&people, store_id()).await;
    let bao = seed_person(&people, 0xB40, "C02", "Bao").await;
    let closed = StoreGroupId::new(Ulid::from_u128(0x6A2));
    let foreign = StoreGroupId::new(Ulid::from_u128(0x6A3));
    for (group_id, tenant_id, status) in [
        (closed, tenant(), EntityStatus::Archived),
        (
            foreign,
            TenantId::new(Ulid::from_u128(0xB0B)),
            EntityStatus::Active,
        ),
    ] {
        let group = StoreGroup {
            group_id,
            tenant_id,
            name: "Elsewhere".to_owned(),
            status,
        };
        people.groups().seed(group, &[store_id()]);
    }
    let router = people_app(
        provisioned_admin(),
        people.clone(),
        FakeRegistry::default(),
        FakeConfigTrees::default(),
        Arc::new(NoopAuditRecorder),
    );
    let owner = admin_cookie(&router).await;
    for (group_id, status, reason) in [
        (
            StoreGroupId::new(Ulid::from_u128(0xDEAD)),
            StatusCode::NOT_FOUND,
            "NOT_FOUND",
        ),
        (foreign, StatusCode::NOT_FOUND, "NOT_FOUND"),
        (closed, StatusCode::CONFLICT, "ARCHIVED"),
    ] {
        let fields = [("store_group_id", group_id.as_ulid().to_string())];
        let body = assignment_body(bao, cashier, &fields);
        assert_eq!(
            refusal_of(&router, &owner, &body).await,
            (status, named(&[("store_group_id", reason)])),
            "{group_id}"
        );
    }
    assert!(
        AssignmentStore::list_for_employee(&people, tenant(), bao)
            .await
            .expect("list")
            .is_empty(),
        "no refusal wrote anything"
    );
}

// --- ADR-0158 Rollout: what each role at a store lacks before the store enforces -----------------

/// The readiness read over the people and settings fakes, with the one store these tests read
/// seeded active.
fn readiness_app(admin: FakeAdmin, people: &FakePeople, settings: FakeSettings) -> axum::Router {
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        FakeConfigTrees::default(),
        FakeWebhooks::default(),
    );
    http::router(app).merge(http::permissions_readiness_router(
        people.clone(),
        settings,
        registry,
        people.groups(),
        admin,
        clock(),
    ))
}

/// The readiness read's address for `store`.
fn readiness_url(store: StoreId) -> String {
    format!(
        "/admin/stores/{}/permissions/readiness?tenant_id={}",
        store.as_ulid(),
        tenant().as_ulid()
    )
}

/// Seeds the three people the readiness test reads: Alice as a Cashier at the store, Bao with a
/// tenant-wide role granting everything a store decides, and Cam with only a role since archived.
async fn seed_readiness(people: &FakePeople) {
    let (_alice, _cashier) = seed_a_cashier(people, store_id()).await;
    let everything: Vec<String> = pos_core::permission::Permission::ALL
        .iter()
        .map(|permission| permission.meta())
        .filter(|meta| meta.group != pos_core::permission::PermissionGroup::CloudAdministration)
        .map(|meta| meta.id.to_owned())
        .collect();
    let (lead, old) = (
        RoleTemplateId::new(Ulid::from_u128(0x1EAD)),
        RoleTemplateId::new(Ulid::from_u128(0x01D)),
    );
    for (role_template_id, name, permissions) in [(lead, "Lead", everything), (old, "Old", vec![])]
    {
        let new = NewRoleTemplate {
            role_template_id,
            tenant_id: tenant(),
            name: name.to_owned(),
            permissions,
            permissions_with_approval: Vec::new(),
            discount_ceiling_minor: None,
        };
        RoleTemplateStore::create(people, &new)
            .await
            .expect("create role");
    }
    people
        .roles
        .rows
        .lock()
        .expect("lock")
        .iter_mut()
        .for_each(|row| {
            if row.record.role_template_id == old {
                row.record.status = EntityStatus::Archived;
            }
        });
    let bao = seed_person(people, 0xB40, "C02", "Bao").await;
    let cam = seed_person(people, 0xCA3, "C03", "Cam").await;
    seed_assignment(people, 2, bao, AssignmentScope::Tenant, lead).await;
    seed_assignment(people, 3, cam, AssignmentScope::Store(store_id()), old).await;
}

/// Before a store enforces each person's own permissions, the console reads what each role held
/// there does not grant (ADR-0158, Rollout). It needs `console.people.read`, as every read of the
/// store's staff does; it names roles and counts people, and names nobody.
#[tokio::test]
async fn the_readiness_read_lists_each_roles_gaps_and_names_nobody() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    seed_readiness(&people).await;
    let settings = FakeSettings::default();
    let router = readiness_app(admin.clone(), &people, settings.clone());

    for (role, token) in [
        (AdminRole::Viewer, "viewer-ready"),
        (AdminRole::Ops, "ops-ready"),
    ] {
        let cookie = role_session_cookie(&admin, role, token).await;
        let refused = router
            .clone()
            .oneshot(get_with_cookie(&readiness_url(store_id()), &cookie))
            .await
            .expect("route the read");
        assert_eq!(
            refused.status(),
            StatusCode::FORBIDDEN,
            "{role:?} lacks console.people.read"
        );
    }

    let owner = role_session_cookie(&admin, AdminRole::Owner, "owner-ready").await;
    let read = router
        .clone()
        .oneshot(get_with_cookie(&readiness_url(store_id()), &owner))
        .await
        .expect("route the read");
    assert_eq!(read.status(), StatusCode::OK);
    let body = json_body(read).await;
    assert_eq!(body["store_id"], store_id().as_ulid().to_string());
    assert_eq!(body["enforced"], false, "the default");
    assert!(body.get("enforced_scope").is_none() && body.get("enforced_scope_id").is_none());
    assert_eq!(
        body["people_without_role"], 1,
        "Cam holds only an archived role"
    );
    let roles = body["roles"].as_array().expect("roles");
    let names: Vec<&str> = roles
        .iter()
        .filter_map(|role| role["name"].as_str())
        .collect();
    assert_eq!(
        names,
        vec!["Cashier", "Lead"],
        "the archived role is not listed"
    );
    assert_eq!(roles[0]["people"], 1);
    assert_eq!(
        roles[0]["missing"][0],
        serde_json::json!({ "id": "sales.item.mark_unavailable", "group": "SALES", "risk": "LOW" }),
        "an everyday permission first, the catalogue's first"
    );
    assert!(
        !roles[0]["missing"]
            .as_array()
            .expect("missing")
            .iter()
            .any(|permission| permission["id"] == "billing.discount.apply"),
        "what the role grants is not missing"
    );
    assert_eq!(roles[1]["people"], 1, "reached through the tenant");
    assert_eq!(roles[1]["missing"], serde_json::json!([]));
    let text = body.to_string();
    for person in ["Alice", "Bao", "Cam", "C01", "C02", "C03"] {
        assert!(!text.contains(person), "no person is named: {text}");
    }

    // The store's own value, and where it comes from.
    pos_cloud::settings::SettingsStore::put(
        &settings,
        tenant(),
        &pos_cloud::settings::SettingValue {
            setting_key: "permissions.enforced".to_owned(),
            scope: Open::from_known(pos_proto::settings::SettingScope::Store),
            scope_id: store_id().to_string(),
            value: serde_json::json!(true),
            update_time: Timestamp::from_milliseconds_since_epoch(NOW_MS).expect("valid"),
        },
    )
    .await
    .expect("write the value");
    let read = router
        .clone()
        .oneshot(get_with_cookie(&readiness_url(store_id()), &owner))
        .await
        .expect("route the read");
    let body = json_body(read).await;
    assert_eq!(body["enforced"], true);
    assert_eq!(body["enforced_scope"], "SETTING_SCOPE_STORE");
    assert_eq!(body["enforced_scope_id"], store_id().to_string());

    let elsewhere = router
        .oneshot(get_with_cookie(
            &readiness_url(StoreId::new(Ulid::from_u128(0xDEAD))),
            &owner,
        ))
        .await
        .expect("route the read");
    assert_eq!(
        elsewhere.status(),
        StatusCode::NOT_FOUND,
        "a store the tenant does not have"
    );
}

// --- Remote device retirement (`POST /admin/stores/{id}/devices/revoke`, ADR-0118 §6) -----------

/// The main app merged with the device-revoke router, sharing one config-tree fake so the test can
/// read back the deny-list the publish appended to.
fn device_revoke_app(admin: FakeAdmin, config: FakeConfigTrees) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config.clone(),
        FakeWebhooks::default(),
    );
    http::router(app).merge(http::device_revoke_router(
        config,
        admin,
        clock(),
        Arc::new(NoopAuditRecorder),
    ))
}

/// The `revoked_devices` deny-list on a store's Store layer, as the tree currently holds it.
///
/// Empty when the store has no tree at all, which is the state a refused publish leaves it in — so
/// this answers "what is on the list" rather than asserting a publish happened.
async fn published_deny_list(
    config: &FakeConfigTrees,
    tenant: TenantId,
    store: StoreId,
) -> Vec<String> {
    let Some(state) = config
        .load(tenant, store)
        .await
        .expect("read the tree")
        .map(|held| held.record)
    else {
        return Vec::new();
    };
    state
        .layer(ConfigLevel::Store)
        .get("revoked_devices")
        .and_then(|node| node.get("device_ids"))
        .and_then(serde_json::Value::as_array)
        .map(|ids| {
            ids.iter()
                .filter_map(|id| id.as_str().map(str::to_owned))
                .collect()
        })
        .unwrap_or_default()
}

#[tokio::test]
async fn revoking_a_device_appends_to_the_deny_list_and_never_replaces_it() {
    // The property the whole rail rests on. Two tills retired one after the other must both stay on
    // the list: a publish that replaced the node would drop the first, and a device somebody was
    // told had been retired would be trading again after the store's next pull.
    let admin = provisioned_admin();
    let config = FakeConfigTrees::default();
    let router = device_revoke_app(admin, config.clone());
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let uri = format!("/admin/stores/{store_ulid}/devices/revoke");
    let first = Ulid::from_u128(0x21).to_string();
    let second = Ulid::from_u128(0x22).to_string();

    let revoke = |device: String| {
        router.clone().oneshot(post_with_cookie(
            &uri,
            &serde_json::json!({ "tenant_id": tenant_ulid, "local_device_id": device }),
            &cookie,
        ))
    };

    let response = revoke(first.clone()).await.expect("route the revoke");
    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(
        published_deny_list(&config, tenant(), store_id()).await,
        vec![first.clone()]
    );

    let response = revoke(second.clone()).await.expect("route the revoke");
    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(
        published_deny_list(&config, tenant(), store_id()).await,
        vec![first.clone(), second.clone()],
        "the second retirement appends; it does not replace the first"
    );

    // Idempotent: re-revoking an id already listed succeeds and adds nothing. A duplicate entry
    // would make the node malformed, and the store refuses a malformed node whole — so a double
    // tap in the console would disarm the very list it was adding to.
    let response = revoke(second.clone()).await.expect("route the revoke");
    assert_eq!(response.status(), StatusCode::OK);
    assert_eq!(
        published_deny_list(&config, tenant(), store_id()).await,
        vec![first, second]
    );
}

#[tokio::test]
async fn revoking_a_device_needs_a_session_and_the_store_manage_role() {
    let admin = provisioned_admin();
    let config = FakeConfigTrees::default();
    let router = device_revoke_app(admin, config.clone());
    let tenant_ulid = tenant().as_ulid().to_string();
    let store_ulid = store_id().as_ulid().to_string();
    let uri = format!("/admin/stores/{store_ulid}/devices/revoke");
    let body = serde_json::json!({
        "tenant_id": tenant_ulid,
        "local_device_id": Ulid::from_u128(0x21).to_string()
    });

    let unauth = router
        .clone()
        .oneshot(
            Request::builder()
                .method("POST")
                .uri(&uri)
                .header("content-type", "application/json")
                .body(Body::from(serde_json::to_vec(&body).expect("serialise")))
                .expect("build the request"),
        )
        .await
        .expect("route the revoke");
    assert_eq!(
        unauth.status(),
        StatusCode::UNAUTHORIZED,
        "taking a terminal out of service is closed to an unauthenticated caller"
    );
    assert!(
        published_deny_list(&config, tenant(), store_id())
            .await
            .is_empty(),
        "and nothing was published"
    );
}

