#[tokio::test]
async fn a_menus_prices_need_the_revenue_permission_not_plain_read() {
    // production-readiness S5. `ReadRevenue` was carved out of `Read` because prices are T2, and the
    // placements read — which carries every item's price on every channel of the menu — sat behind
    // plain `Read`, which Ops and Viewer both hold. The console refused a Viewer the revenue report
    // and handed them the price book.
    let admin = provisioned_admin();
    let router = catalog_app(admin.clone(), FakeCatalog::default());
    let tenant = ulid_text(1);
    let menu = ulid_text(10);
    let list = format!("/admin/catalog/menus/{menu}/placements?tenant_id={tenant}");

    for (role, token) in [
        (AdminRole::Viewer, "viewer-prices"),
        (AdminRole::Ops, "ops-prices"),
    ] {
        let cookie = role_session_cookie(&admin, role, token).await;
        let refused = router
            .clone()
            .oneshot(get_with_cookie(&list, &cookie))
            .await
            .expect("route list placements");
        assert_eq!(
            refused.status(),
            StatusCode::FORBIDDEN,
            "{role:?} holds console.data.read but not console.reports.revenue"
        );
    }

    // An Admin holds `ReadRevenue` and still reads the menu.
    let cookie = role_session_cookie(&admin, AdminRole::Admin, "admin-prices").await;
    let allowed = router
        .oneshot(get_with_cookie(&list, &cookie))
        .await
        .expect("route list placements");
    assert_eq!(allowed.status(), StatusCode::OK);
}

#[tokio::test]
async fn the_console_config_read_never_carries_a_staff_pin_hash() {
    // production-readiness S7, found while verifying S5. `GET /admin/stores/{id}/config` returns the
    // whole effective document under plain `Read`, and the document's `permissions` node carries each
    // member of staff's Argon2id PIN hash — T1, the credential the edge verifies a sign-in against.
    // A read-only console account could lift the PIN hash of every member of staff in the fleet.
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let mine = tenant();
    let store = StoreId::new(Ulid::from_u128(77));
    seed_a_cashier(&people, store).await;

    let router = people_publish_app(
        admin,
        people,
        config,
        Arc::new(NoopAuditRecorder) as Arc<dyn AuditRecorder>,
    );
    let cookie = admin_cookie(&router).await;
    let tenant_ulid = mine.as_ulid().to_string();
    let store_ulid = store.as_ulid().to_string();

    let published = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/people/publish",
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &cookie,
        ))
        .await
        .expect("route publish");
    assert_eq!(published.status(), StatusCode::OK);

    let effective = router
        .oneshot(get_with_cookie(
            &format!("/admin/stores/{store_ulid}/config?tenant_id={tenant_ulid}"),
            &cookie,
        ))
        .await
        .expect("read effective config");
    assert_eq!(effective.status(), StatusCode::OK);
    let doc = json_body(effective).await;

    let staff = doc["permissions"]["staff"]
        .as_array()
        .expect("the staff array is still there");
    assert_eq!(staff.len(), 1);
    assert_eq!(
        staff[0]["code"],
        serde_json::json!("C01"),
        "an owner still sees who is on the node — only the credential is withheld"
    );
    assert!(
        staff[0].get("pin_phc").is_none(),
        "the field is removed, not blanked: an empty string would read as 'no PIN set', which is a \
         different and real state"
    );
    assert!(
        !serde_json::to_string(&doc)
            .expect("serialize")
            .contains("argon2id"),
        "no hash anywhere in the document"
    );
}

/// A store's config names its staff only to a role holding `console.people.read`
/// ([ADR-0158](../../docs/adr/0158-the-till-enforces-each-persons-own-permissions.md) decision 9).
///
/// The `permissions` node lists every member of staff the store authorises, with their name and
/// staff code. The config read needs only `console.data.read`, so without this a Viewer refused the
/// roster could read every name in the fleet through the config screen, one store at a time. Only
/// the two fields go — the member, what they may do and the rest of the document stay — and both
/// reads take them out, because a past version holds past names.
#[tokio::test]
async fn a_config_read_names_staff_only_to_a_role_that_reads_staff_records() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let mine = tenant();
    let store = store_id();
    let (alice, _cashier) = seed_a_cashier(&people, store).await;

    let router = people_publish_app(
        admin.clone(),
        people,
        config,
        Arc::new(NoopAuditRecorder) as Arc<dyn AuditRecorder>,
    );
    let owner = admin_cookie(&router).await;
    let tenant_ulid = mine.as_ulid().to_string();
    let store_ulid = store.as_ulid().to_string();

    let published = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/people/publish",
            &serde_json::json!({ "tenant_id": tenant_ulid, "store_id": store_ulid }),
            &owner,
        ))
        .await
        .expect("route publish");
    assert_eq!(published.status(), StatusCode::OK);
    let version_ulid = json_body(published).await["config_version_id"]
        .as_str()
        .expect("a version id")
        .to_owned();
    let reads = [
        format!("/admin/stores/{store_ulid}/config?tenant_id={tenant_ulid}"),
        format!(
            "/admin/stores/{store_ulid}/config/versions/{version_ulid}?tenant_id={tenant_ulid}"
        ),
    ];

    for (role, token, names_staff) in [
        (AdminRole::Viewer, "viewer-config", false),
        (AdminRole::Ops, "ops-config", false),
        (AdminRole::Admin, "admin-config", true),
        (AdminRole::Owner, "owner-config", true),
    ] {
        let cookie = role_session_cookie(&admin, role, token).await;
        for url in &reads {
            let response = router
                .clone()
                .oneshot(get_with_cookie(url, &cookie))
                .await
                .expect("route a config read");
            assert_eq!(
                response.status(),
                StatusCode::OK,
                "{role:?} reads {url}: the config read needs only console.data.read"
            );
            let doc = json_body(response).await;
            let member = doc["permissions"]["staff"][0]
                .as_object()
                .expect("the member is still listed");
            assert_eq!(
                member["id"],
                serde_json::json!(alice.as_ulid().to_string()),
                "{role:?}: the member stays"
            );
            assert_eq!(
                member["permissions"],
                serde_json::json!(["billing.discount.apply"]),
                "{role:?}: and so does what they may do"
            );
            assert!(
                !member.contains_key("pin_phc"),
                "{role:?}: never the credential (S7)"
            );
            if names_staff {
                assert_eq!(
                    member["name"], "Alice",
                    "{role:?} holds console.people.read"
                );
                assert_eq!(member["code"], "C01", "{role:?} holds console.people.read");
            } else {
                assert!(
                    !member.contains_key("name") && !member.contains_key("code"),
                    "{role:?} lacks console.people.read, so the name and code are removed: \
                     {member:?}"
                );
                assert!(
                    !doc.to_string().contains("Alice"),
                    "{role:?}: the name is nowhere in the document"
                );
            }
        }
    }
}

/// A store's `origins` node is authored here and refused here, by the very rule the edge applies
/// ([ADR-0111](../../docs/adr/0111-a-second-origin-may-address-the-edge.md)).
///
/// The node is the only writer for a list the edge reads on the front of every request. Two things
/// have to hold for that to be worth anything: what the console saves is the shape the edge parses,
/// and what the edge would refuse the console refuses first. The second is the one that bites — a
/// cloud that stored `https://*.example.com` would leave an operator looking at a saved allow-list
/// their edge had silently thrown away whole.
#[tokio::test]
async fn a_store_publishes_the_origins_its_edge_will_answer() {
    let admin = provisioned_admin();
    let trees = FakeConfigTrees::default();
    let router = http::router(app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        trees.clone(),
        FakeWebhooks::default(),
    ))
    .merge(http::config_channels_router(
        trees,
        admin,
        clock(),
        Arc::new(NoopAuditRecorder),
    ));
    let cookie = admin_cookie(&router).await;
    let scope = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "store_id": store_id().as_ulid().to_string(),
    });

    // A store that has never published one reads `null` — distinct from an empty list, which is a
    // person deliberately withdrawing every second origin.
    let before = router
        .clone()
        .oneshot(get_with_cookie(
            &format!(
                "/admin/config/origins?tenant_id={}&store_id={}",
                tenant().as_ulid(),
                store_id().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the read");
    assert_eq!(before.status(), StatusCode::OK);
    assert!(json_body(before).await.is_null());

    // A valid publish stores the `{ "allowed": [...] }` shape the edge's `apply_origins` reads.
    let mut body = scope.clone();
    body["allowed"] = serde_json::json!(["https://shell.example.com", "http://localhost:1420"]);
    let published = router
        .clone()
        .oneshot(put_with_cookie("/admin/config/origins", &body, &cookie))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);

    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!(
                "/admin/config/origins?tenant_id={}&store_id={}",
                tenant().as_ulid(),
                store_id().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the read");
    assert_eq!(
        json_body(read).await,
        serde_json::json!({
            "allowed": ["https://shell.example.com", "http://localhost:1420"]
        })
    );

    // A wildcard is refused at authoring time, naming the entry and the rule — not stored for an
    // edge to throw away in a log line nobody reads.
    let mut wildcard = scope.clone();
    wildcard["allowed"] = serde_json::json!(["https://*.example.com"]);
    let refused = router
        .clone()
        .oneshot(put_with_cookie("/admin/config/origins", &wildcard, &cookie))
        .await
        .expect("route the publish");
    assert_eq!(refused.status(), StatusCode::BAD_REQUEST);
    let message = json_body(refused).await["error"]["message"]
        .as_str()
        .unwrap_or_default()
        .to_owned();
    assert!(
        message.contains("https://*.example.com"),
        "the refusal must name the entry the operator typed: {message}"
    );

    // And the refusal changed nothing: the previously published list still stands.
    let after = router
        .oneshot(get_with_cookie(
            &format!(
                "/admin/config/origins?tenant_id={}&store_id={}",
                tenant().as_ulid(),
                store_id().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the read");
    assert_eq!(
        json_body(after).await,
        serde_json::json!({
            "allowed": ["https://shell.example.com", "http://localhost:1420"]
        })
    );
}

#[tokio::test]
async fn a_heartbeat_reports_its_print_agents_and_an_empty_list_clears_them() {
    // ADR-0112: for a store whose edge is not in the shop, the print agent is the one moving part
    // with no rail to the cloud of its own. The heartbeat is where its standing arrives, and the
    // three cases below are the three answers a store can give — each of which the console renders
    // differently, and two of which look identical if the wire cannot tell them apart.
    let keys = FakeKeys::default();
    let config_trees = FakeConfigTrees::default();
    let router = http::router(app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        keys.clone(),
        provisioned_admin(),
        config_trees.clone(),
        FakeWebhooks::default(),
    ));
    let store_ulid = store_id().as_ulid().to_string();
    let uri = format!("/sync/stores/{store_ulid}/heartbeat");
    let token = issue_store_key(&keys, tenant(), store_id(), &[Scope::ReadConfig]);

    // One agent, holding a ticket. Two opaque ids and a duration — no document, no line, no name.
    let beat = router
        .clone()
        .oneshot(post_json_bearer(
            &uri,
            &serde_json::json!({
                "print_agents": [{
                    "agent_device_id": "TILL-KITCHEN",
                    "paired_device_id": "PAIR-A",
                    "oldest_unacknowledged_secs": 420,
                }],
            }),
            &token,
        ))
        .await
        .expect("route the heartbeat");
    assert_eq!(beat.status(), StatusCode::NO_CONTENT);
    assert_eq!(
        config_trees.recorded_print_agents(tenant(), store_id()),
        Some(vec![PrintAgentStanding {
            agent_device_id: "TILL-KITCHEN".to_owned(),
            paired_device_id: "PAIR-A".to_owned(),
            oldest_unacknowledged_secs: Some(420),
        }]),
        "the standing the store reported is the standing the cloud recorded"
    );

    // A beat that says nothing about agents leaves the recorded standing alone — an older edge must
    // not silently erase what a newer one reported.
    let quiet = router
        .clone()
        .oneshot(post_json_bearer(&uri, &serde_json::json!({}), &token))
        .await
        .expect("route the heartbeat");
    assert_eq!(quiet.status(), StatusCode::NO_CONTENT);
    assert_eq!(
        config_trees
            .recorded_print_agents(tenant(), store_id())
            .map(|agents| agents.len()),
        Some(1),
        "an absent key is \"did not say\", not \"has none\""
    );

    // An *empty* list is a report, and it replaces. This is the manager-released-the-terminal case:
    // a console still showing an agent nobody is bound to is the stale answer the field exists to
    // prevent, and it is the one an absent-vs-empty conflation would produce.
    let released = router
        .oneshot(post_json_bearer(
            &uri,
            &serde_json::json!({ "print_agents": [] }),
            &token,
        ))
        .await
        .expect("route the heartbeat");
    assert_eq!(released.status(), StatusCode::NO_CONTENT);
    assert_eq!(
        config_trees.recorded_print_agents(tenant(), store_id()),
        Some(Vec::new()),
        "a store that says it has no agent is recorded as having none, not left as it was"
    );
}

#[tokio::test]
async fn the_admin_device_read_lists_approved_devices_for_one_store_and_still_defaults_to_pending()
{
    // ADR-0112's agent picker acts on a printer already in service and names a terminal already
    // created. Until this read could show either, `set_print_agent` had no `/admin` read a console
    // could be written against at all — the same shape of gap as a leased job that carried no
    // printer address. The seam always supported both filters; only the route did not.
    //
    // Defaulting to `pending` is the other half: the onboarding queue is an existing caller that
    // passes neither parameter, and it must keep seeing exactly what it saw.
    let keys = FakeKeys::default();
    let devices = FakeDevices::default();
    let router = device_app(provisioned_admin(), keys.clone(), devices);
    let cookie = admin_cookie(&router).await;
    let token = issue_store_key(&keys, tenant(), store_id(), &[Scope::ManageDevices]);
    let store_ulid = store_id().as_ulid().to_string();
    let tenant_ulid = tenant().as_ulid().to_string();
    let devices_uri = format!("/sync/stores/{store_ulid}/devices");

    let created = router
        .clone()
        .oneshot(post_json_bearer(
            &devices_uri,
            &serde_json::json!({
                "kind": "printer",
                "name": "Kitchen 1",
                "address": "192.168.1.50:9100",
            }),
            &token,
        ))
        .await
        .expect("route the proposal");
    let id = json_body(created).await["id"]
        .as_str()
        .expect("an id")
        .to_owned();

    // Still pending: an `approved` listing is empty, and the default listing is not.
    let approved = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!(
                    "/admin/devices/proposals?tenant_id={tenant_ulid}&store_id={store_ulid}&status=approved"
                ),
                &cookie,
            ))
            .await
            .expect("route the approved listing"),
    )
    .await;
    assert_eq!(
        approved.as_array().expect("array").len(),
        0,
        "a pending printer is not an approved one"
    );

    let approve = router
        .clone()
        .oneshot(post_with_cookie(
            &format!(
                "/admin/devices/proposals/{id}/approve?tenant_id={tenant_ulid}&connection=network"
            ),
            &serde_json::json!({}),
            &cookie,
        ))
        .await
        .expect("route the approval");
    assert_eq!(approve.status(), StatusCode::NO_CONTENT);

    // Now the picker can see it — which is the whole point of the parameter.
    let approved = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!(
                    "/admin/devices/proposals?tenant_id={tenant_ulid}&store_id={store_ulid}&status=approved"
                ),
                &cookie,
            ))
            .await
            .expect("route the approved listing"),
    )
    .await;
    assert_eq!(approved.as_array().expect("array").len(), 1);
    assert_eq!(approved[0]["id"], id);
    assert!(
        approved[0]["version"].is_string(),
        "and carries the version the picker echoes back in If-Match (ADR-0094): {approved:?}"
    );

    // The onboarding queue passes neither parameter and must be unchanged: the printer it was
    // watching has been approved, so the pending queue is now empty.
    let pending = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/devices/proposals?tenant_id={tenant_ulid}"),
                &cookie,
            ))
            .await
            .expect("route the default listing"),
    )
    .await;
    assert_eq!(
        pending.as_array().expect("array").len(),
        0,
        "the default is still pending-only, so an approved row does not leak into the queue"
    );

    // A status nobody defined is refused by name rather than silently narrowed to pending — being
    // handed the pending queue for `aproved` reads as \"this store has no printers\".
    let mistyped = router
        .oneshot(get_with_cookie(
            &format!("/admin/devices/proposals?tenant_id={tenant_ulid}&status=aproved"),
            &cookie,
        ))
        .await
        .expect("route the mistyped listing");
    assert_eq!(mistyped.status(), StatusCode::BAD_REQUEST);
}

// --- Reason-code authoring admin routes (ADR-0115, B2.2 slice 3) --------------------------------

/// An in-memory `ReasonCodeStore` for the route tests.
///
/// Tenant-scoped and version-carrying like the real thing, because that is what the routes under
/// test depend on: a create refuses a taken id, an update applies only at the version a read handed
/// back, and the list is where the console obtains it.
/// One stored entry: which tenant authored it, and the record with the version it stands at.
type ReasonCodeRow = (TenantId, Versioned<PublishedReasonCode>);

#[derive(Default, Clone)]
struct FakeReasonCodes {
    rows: Arc<Mutex<Vec<ReasonCodeRow>>>,
    next_version: Arc<Mutex<u64>>,
}

impl FakeReasonCodes {
    /// The fake's stand-in for `xmin` (ADR-0094): a token that changes on every successful write.
    fn mint(&self) -> Version {
        let mut next = self.next_version.lock().expect("lock");
        *next += 1;
        Version::new(next.to_string())
    }
}

impl ReasonCodeStore for FakeReasonCodes {
    async fn list(
        &self,
        tenant_id: TenantId,
    ) -> Result<Vec<Versioned<PublishedReasonCode>>, ReasonCodeStoreError> {
        let rows = self.rows.lock().expect("lock");
        let mut mine: Vec<Versioned<PublishedReasonCode>> = rows
            .iter()
            .filter(|(owner, _)| *owner == tenant_id)
            .map(|(_, row)| row.clone())
            .collect();
        mine.sort_by_key(|row| row.record.id.as_ulid().to_u128());
        Ok(mine)
    }

    async fn get(
        &self,
        tenant_id: TenantId,
        reason_code_id: ReasonCodeId,
    ) -> Result<Option<Versioned<PublishedReasonCode>>, ReasonCodeStoreError> {
        Ok(self
            .rows
            .lock()
            .expect("lock")
            .iter()
            .find(|(owner, row)| *owner == tenant_id && row.record.id == reason_code_id)
            .map(|(_, row)| row.clone()))
    }

    async fn create(
        &self,
        tenant_id: TenantId,
        reason_code: &PublishedReasonCode,
    ) -> Result<CreateOutcome, ReasonCodeStoreError> {
        let version = self.mint();
        let mut rows = self.rows.lock().expect("lock");
        if rows
            .iter()
            .any(|(owner, row)| *owner == tenant_id && row.record.id == reason_code.id)
        {
            return Ok(CreateOutcome::AlreadyExists);
        }
        rows.push((
            tenant_id,
            Versioned::edited(reason_code.clone(), version.clone(), NOW_MS),
        ));
        Ok(CreateOutcome::Created(version))
    }

    async fn update(
        &self,
        tenant_id: TenantId,
        reason_code: &PublishedReasonCode,
        expected: &Version,
    ) -> Result<UpdateOutcome, ReasonCodeStoreError> {
        let version = self.mint();
        let mut rows = self.rows.lock().expect("lock");
        let Some((_, row)) = rows
            .iter_mut()
            .find(|(owner, row)| *owner == tenant_id && row.record.id == reason_code.id)
        else {
            return Ok(UpdateOutcome::NotFound);
        };
        if &row.etag != expected {
            return Ok(UpdateOutcome::VersionMismatch);
        }
        row.record = reason_code.clone();
        row.etag = version.clone();
        // The real adapter's `updated_at` moves on every write; a fake that stamped only on create
        // would let a read-path bug that pins the create instant pass.
        row.updated_at_ms = Some(NOW_MS);
        Ok(UpdateOutcome::Updated(version))
    }

    async fn delete(
        &self,
        tenant_id: TenantId,
        reason_code_id: ReasonCodeId,
    ) -> Result<(), ReasonCodeStoreError> {
        self.rows
            .lock()
            .expect("lock")
            .retain(|(owner, row)| !(*owner == tenant_id && row.record.id == reason_code_id));
        Ok(())
    }
}

/// The admin surface plus the reason-code router, on fakes, recording into `audit`.
///
/// The trail is a real `AuditSink` over `FakeAudit` rather than the no-op the inventory routes use:
/// these entries are the record of who changed a **fraud control**, so what lands in them is part
/// of what this slice has to get right, not incidental.
fn reason_code_app(
    admin: FakeAdmin,
    reason_codes: FakeReasonCodes,
    audit: Arc<dyn AuditRecorder>,
) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        FakeConfigTrees::default(),
        FakeWebhooks::default(),
    );
    http::router(app).merge(http::reason_code_router(
        reason_codes,
        admin,
        clock(),
        audit,
    ))
}

/// A reason-code write body: the report handle, the name staff read, one Vietnamese translation, and
/// the actions it may be cited for.
fn reason_code_body(tenant: &str, code: &str, actions: &[&str], active: bool) -> serde_json::Value {
    serde_json::json!({
        "tenant_id": tenant,
        "code": code,
        "display_name": "Waste or spoilage",
        "display_name_translations": { "vi": "Hàng hỏng hoặc hết hạn" },
        "applies_to": actions,
        "active": active,
    })
}

/// The most recent trail entry for `action`, or `None`.
async fn last_trail_entry(audit: &FakeAudit, action: &str) -> Option<AuditEntry> {
    audit
        .list(None, 50)
        .await
        .expect("read the trail")
        .into_iter()
        .find(|entry| entry.action == action)
}

/// Authoring an entry mints its id, hands back the version to edit it at, and records in the trail
/// the two facts that decide whether the control holds: which actions it covers, and that it is live.
#[tokio::test]
async fn authoring_a_reason_code_mints_its_id_and_the_trail_records_what_it_covers() {
    let audit = FakeAudit::default();
    let router = reason_code_app(
        provisioned_admin(),
        FakeReasonCodes::default(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(
                &tenant,
                "WASTE",
                &["REASON_ACTION_VOID_LINE", "REASON_ACTION_STOCK_WASTE"],
                true,
            ),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(created.status(), StatusCode::CREATED);
    let at_create = etag_of(&created);
    let body = json_body(created).await;
    let minted = body["id"]
        .as_str()
        .expect("the create answers the entry it stored")
        .to_owned();
    assert_eq!(
        minted.len(),
        26,
        "the server minted the id, so a caller cannot choose one an event already names"
    );
    assert_eq!(
        body["etag"].as_str().expect("an etag field"),
        at_create,
        "the version is in the body as well as the header, so the console can edit straight from a \
         create without re-reading"
    );
    assert_eq!(
        body["display_name_translations"]["vi"], "Hàng hỏng hoặc hết hạn",
        "§12: the picker's Vietnamese name survives the round trip, got {body}"
    );

    let entry = last_trail_entry(&audit, "reason_codes.create")
        .await
        .expect("the create is in the trail");
    assert_eq!(entry.entity_type, "reason_code");
    assert_eq!(entry.entity_id, minted);
    let after = entry.after.expect("the trail records what was stored");
    assert_eq!(after["code"], "WASTE");
    assert_eq!(
        after["applies_to"],
        serde_json::json!(["REASON_ACTION_VOID_LINE", "REASON_ACTION_STOCK_WASTE"]),
        "the actions are in the summary: narrowing them is how the control gets defeated, so a \
         trail that omitted them would record that a reason changed while hiding the change"
    );
    assert_eq!(after["active"], true);
}

/// Retiring an entry is the ordinary edit, needs the version the read carried, and shows in the
/// trail as the change of standing it is.
#[tokio::test]
async fn retiring_a_reason_code_needs_the_version_and_is_visible_in_the_trail() {
    let audit = FakeAudit::default();
    let store = FakeReasonCodes::default();
    let router = reason_code_app(
        provisioned_admin(),
        store.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "WASTE", &["REASON_ACTION_VOID_LINE"], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    let at_create = etag_of(&created);
    let id = json_body(created).await["id"]
        .as_str()
        .expect("an id")
        .to_owned();
    let row = format!("/admin/reason-codes/{id}");
    let retire = reason_code_body(&tenant, "WASTE", &["REASON_ACTION_VOID_LINE"], false);

    let unconditional = router
        .clone()
        .oneshot(put_with_cookie(&row, &retire, &cookie))
        .await
        .expect("route the unconditional edit");
    assert_eq!(
        unconditional.status(),
        StatusCode::BAD_REQUEST,
        "ADR-0094: an edit without If-Match is refused rather than clobbering"
    );

    let retired = router
        .clone()
        .oneshot(put_with_etag(&row, &retire, &cookie, &at_create))
        .await
        .expect("route the retire");
    assert_eq!(retired.status(), StatusCode::OK);
    let at_retire = etag_of(&retired);
    assert_ne!(at_retire, at_create, "an applied edit moves the version");

    let replayed = router
        .clone()
        .oneshot(put_with_etag(&row, &retire, &cookie, &at_create))
        .await
        .expect("route the replay");
    assert_eq!(
        replayed.status(),
        StatusCode::PRECONDITION_FAILED,
        "a second manager holding the stale version is refused, not silently applied"
    );

    let entry = last_trail_entry(&audit, "reason_codes.update")
        .await
        .expect("the retire is in the trail");
    let before = entry.before.expect("the trail records what stood before");
    let after = entry.after.expect("and what stands now");
    assert_eq!(before["active"], true);
    assert_eq!(
        after["active"], false,
        "the trail says a reason left service, which is the half of the control an auditor asks \
         about: whether the reason a colleague's void would have had to cite was removed"
    );

    // And retiring keeps it resolvable: the list still holds it, because a historic
    // `sales.order_line.voided` names its id forever.
    let listed = json_body(
        router
            .oneshot(get_with_cookie(
                &format!("/admin/reason-codes?tenant_id={tenant}"),
                &cookie,
            ))
            .await
            .expect("route the list"),
    )
    .await;
    let rows = listed.as_array().expect("an array");
    assert_eq!(rows.len(), 1, "a retired entry stays in the list");
    assert_eq!(rows[0]["active"], false);
}

/// The three data-entry faults a reason-code form can make, each naming its own field.
#[tokio::test]
async fn a_reason_that_could_be_cited_for_nothing_is_refused_and_the_refusal_names_the_field() {
    let router = reason_code_app(
        provisioned_admin(),
        FakeReasonCodes::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    // No action at all: it would sit in the table and appear on no picker.
    let unusable = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "WASTE", &[], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(unusable.status(), StatusCode::BAD_REQUEST);
    let body = json_body(unusable).await;
    assert_eq!(body["error"]["details"][0]["field"], "applies_to");
    assert_eq!(body["error"]["details"][0]["reason"], "REQUIRED");

    // An action this cloud does not know matches nothing at the till, so storing it would author a
    // reason that silently applies to nothing.
    let unknown = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "WASTE", &["REASON_ACTION_TELEPORT"], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(unknown.status(), StatusCode::BAD_REQUEST);
    let body = json_body(unknown).await;
    assert_eq!(body["error"]["details"][0]["field"], "applies_to");
    assert_eq!(body["error"]["details"][0]["reason"], "INVALID_ENUM_VALUE");

    // A blank handle: a report would group by an empty string.
    let blank = router
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "   ", &["REASON_ACTION_VOID_LINE"], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(blank.status(), StatusCode::BAD_REQUEST);
    let body = json_body(blank).await;
    assert_eq!(body["error"]["details"][0]["field"], "code");
    assert_eq!(body["error"]["details"][0]["reason"], "REQUIRED");
}

/// Deleting is for the entry created by mistake, and it leaves the whole summary in the trail —
/// which is the only thing that can be done for an id an event may already name.
#[tokio::test]
async fn deleting_a_reason_code_leaves_a_readable_trail_and_the_entry_stops_resolving() {
    let audit = FakeAudit::default();
    let router = reason_code_app(
        provisioned_admin(),
        FakeReasonCodes::default(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "TYPO", &["REASON_ACTION_VOID_LINE"], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    let id = json_body(created).await["id"]
        .as_str()
        .expect("an id")
        .to_owned();
    let row = format!("/admin/reason-codes/{id}?tenant_id={tenant}");

    let removed = router
        .clone()
        .oneshot(delete_with_cookie(&row, &cookie))
        .await
        .expect("route the delete");
    assert_eq!(removed.status(), StatusCode::NO_CONTENT);

    let entry = last_trail_entry(&audit, "reason_codes.delete")
        .await
        .expect("the delete is in the trail");
    let before = entry.before.expect("the trail keeps the whole entry");
    assert_eq!(before["code"], "TYPO");
    assert_eq!(before["name"], "Waste or spoilage");
    assert_eq!(
        before["applies_to"],
        serde_json::json!(["REASON_ACTION_VOID_LINE"]),
        "so a reader of the trail can still say what the deleted id meant"
    );

    let gone = router
        .clone()
        .oneshot(get_with_cookie(&row, &cookie))
        .await
        .expect("route the read");
    assert_eq!(gone.status(), StatusCode::NOT_FOUND);

    // A second delete is refused as a `404` rather than answered as a success: the seam is
    // idempotent, but the route reads the row first so it has a `before` to record.
    let again = router
        .oneshot(delete_with_cookie(&row, &cookie))
        .await
        .expect("route the second delete");
    assert_eq!(again.status(), StatusCode::NOT_FOUND);
}

/// Authoring the list and reading it are different permissions: a viewer may see what a store's
/// staff must cite, and may not change it.
#[tokio::test]
async fn a_viewer_reads_the_reason_codes_and_cannot_author_them() {
    let admin = provisioned_admin();
    let cookie = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let router = reason_code_app(
        admin,
        FakeReasonCodes::default(),
        Arc::new(NoopAuditRecorder),
    );
    let tenant = ulid_text(1);

    let listed = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/reason-codes?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route the list");
    assert_eq!(
        listed.status(),
        StatusCode::OK,
        "console.data.read is granted to every role, so a viewer may read the list"
    );

    let denied = router
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "WASTE", &["REASON_ACTION_VOID_LINE"], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(
        denied.status(),
        StatusCode::FORBIDDEN,
        "authoring is behind console.reason_codes.manage — Owner and Admin only, because \
         removing a reason or adding a vague catch-all is how the fraud control gets defeated"
    );
}

/// The list carries when each entry was last written, so the console can tell the operator whether
/// what is on their screen is newer than what the shop is running.
///
/// Every one of these tables has had an `updated_at` since it was created and not one read returned
/// it, so the publish bar had to approximate from a within-session signal that forgot on reload — an
/// operator who edited yesterday and came back today was told the store was up to date (Wave 4).
///
/// Asserted on the wire rather than on the seam because the field's whole job is to leave the
/// process: a `Versioned` that holds the instant and a response that drops it would pass every
/// test above this one.
#[tokio::test]
async fn the_reason_code_list_says_when_each_entry_was_last_written() {
    let router = reason_code_app(
        provisioned_admin(),
        FakeReasonCodes::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&tenant, "WASTE", &["REASON_ACTION_VOID_LINE"], true),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(created.status(), StatusCode::CREATED);

    let listed = router
        .oneshot(get_with_cookie(
            &format!("/admin/reason-codes?tenant_id={tenant}"),
            &cookie,
        ))
        .await
        .expect("route the list");
    assert_eq!(listed.status(), StatusCode::OK);
    let rows = json_body(listed).await;
    let first = &rows.as_array().expect("an array")[0];
    assert!(
        first["updated_at_ms"].as_i64().is_some_and(|at| at > 0),
        "the row carries the instant it was written, in Unix milliseconds: {first}"
    );
}

/// One tenant's list never reaches another's, and a malformed tenant is a refusal rather than a
/// cross-tenant read.
#[tokio::test]
async fn a_tenants_reason_codes_are_its_own() {
    let router = reason_code_app(
        provisioned_admin(),
        FakeReasonCodes::default(),
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let mine = ulid_text(1);
    let theirs = ulid_text(2);

    router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/reason-codes",
            &reason_code_body(&mine, "WASTE", &["REASON_ACTION_VOID_LINE"], true),
            &cookie,
        ))
        .await
        .expect("route the create");

    let others = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/reason-codes?tenant_id={theirs}"),
                &cookie,
            ))
            .await
            .expect("route the other tenant's list"),
    )
    .await;
    assert_eq!(
        others.as_array().expect("an array").len(),
        0,
        "the other tenant authored nothing, and sees nothing"
    );

    let mistyped = router
        .oneshot(get_with_cookie(
            "/admin/reason-codes?tenant_id=nope",
            &cookie,
        ))
        .await
        .expect("route the mistyped listing");
    assert_eq!(mistyped.status(), StatusCode::BAD_REQUEST);
}

// --- Reason-code publish (ADR-0115, B2.2 slice 4) -----------------------------------------------

/// The admin surface plus the reason-code publish route, on fakes.
fn reason_code_publish_app(
    admin: FakeAdmin,
    reason_codes: FakeReasonCodes,
    config_trees: FakeConfigTrees,
) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
        FakeWebhooks::default(),
    );
    http::router(app).merge(http::config_reason_codes_router(
        reason_codes,
        config_trees,
        admin,
        clock(),
        Arc::new(NoopAuditRecorder),
    ))
}

/// Seeds one authored entry directly into the store, valid for `actions`.
fn seed_reason_code(store: &FakeReasonCodes, n: u128, code: &str, actions: &[ReasonAction]) {
    store.rows.lock().expect("lock").push((
        tenant(),
        Versioned::new(
            PublishedReasonCode::new(
                ReasonCodeId::new(Ulid::from_u128(n)),
                ReasonCode::new(code),
                DisplayName::new(code),
                actions.to_vec(),
            ),
            Version::new("1"),
        ),
    ));
}

/// The publish writes the node onto the Store layer and says what the store can no longer record.
#[tokio::test]
async fn publishing_reason_codes_writes_the_node_and_names_what_nothing_now_covers() {
    let store = FakeReasonCodes::default();
    seed_reason_code(
        &store,
        10,
        "WASTE",
        &[ReasonAction::VoidLine, ReasonAction::StockWaste],
    );
    let config_trees = FakeConfigTrees::default();
    let router = reason_code_publish_app(provisioned_admin(), store, config_trees.clone());
    let cookie = admin_cookie(&router).await;
    let body = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "store_id": store_id().as_ulid().to_string(),
    });

    let published = router
        .oneshot(put_with_cookie(
            "/admin/config/reason-codes",
            &body,
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
    let answered = json_body(published).await;
    assert_eq!(answered["published"], 1);
    assert_eq!(answered["active"], 1);

    // The heart of it: a store that publishes one void reason can no longer record a comp, a
    // refund, a drawer opening or a cash movement, because the node REPLACED the framework set and
    // offers nothing for those. That may be what the operator meant; it must not be a surprise.
    let uncovered = answered["uncovered_actions"]
        .as_array()
        .expect("the publish reports coverage");
    assert!(
        uncovered.contains(&serde_json::json!("REASON_ACTION_COMP")),
        "a comp has no reason to cite after this publish, and the response says so: {answered}"
    );
    assert!(
        !uncovered.contains(&serde_json::json!("REASON_ACTION_VOID_LINE")),
        "while the action they did author for is not listed"
    );
    assert!(
        !uncovered.contains(&serde_json::json!("REASON_ACTION_UNSPECIFIED")),
        "the wire enum's zero value is not an act anyone performs, so it is not a gap"
    );
    assert!(
        !uncovered.contains(&serde_json::json!("REASON_ACTION_CASH_VARIANCE")),
        "a list with no reason for a variance still lets every drawer close (ADR-0167 decision \
         12), so it is not a gap either: {answered}"
    );

    // And the node is on the store's Store layer (index 2), beside the other keys.
    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    let node = &state.record.layers[2]["reason_codes"];
    assert_eq!(
        node["codes"].as_array().expect("the codes array").len(),
        1,
        "the published node is the authored list"
    );
}

/// Publishing an empty list is refused, because the node replaces the framework set.
///
/// This is the hazard ADR-0115's "absence is not a brick" reasoning creates in the other direction:
/// absence is safe *because* the framework default is still there, and an empty publish is the one
/// way to take it away. A store that took it would be unable to void a mis-keyed line at all.
#[tokio::test]
async fn publishing_an_empty_reason_list_is_refused_rather_than_disarming_the_store() {
    let config_trees = FakeConfigTrees::default();
    let router = reason_code_publish_app(
        provisioned_admin(),
        FakeReasonCodes::default(),
        config_trees.clone(),
    );
    let cookie = admin_cookie(&router).await;

    let refused = router
        .oneshot(put_with_cookie(
            "/admin/config/reason-codes",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": store_id().as_ulid().to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(refused.status(), StatusCode::CONFLICT);
    let body = json_body(refused).await;
    assert_eq!(body["error"]["details"][0]["field"], "reason_codes");
    assert_eq!(body["error"]["details"][0]["reason"], "EMPTY_NOT_ALLOWED");

    assert!(
        config_trees
            .load(tenant(), store_id())
            .await
            .expect("load")
            .is_none(),
        "and nothing was written, so the store keeps the framework set it was trading on"
    );
}

/// An entry valid for no action is refused at publish — the guarantee ADR-0115 puts here.
#[tokio::test]
async fn publishing_a_reason_valid_for_nothing_is_refused_and_names_it() {
    let store = FakeReasonCodes::default();
    seed_reason_code(&store, 10, "WASTE", &[ReasonAction::VoidLine]);
    seed_reason_code(&store, 11, "ORPHAN", &[]);
    let config_trees = FakeConfigTrees::default();
    let router = reason_code_publish_app(provisioned_admin(), store, config_trees.clone());
    let cookie = admin_cookie(&router).await;

    let refused = router
        .oneshot(put_with_cookie(
            "/admin/config/reason-codes",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": store_id().as_ulid().to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(refused.status(), StatusCode::CONFLICT);
    let body = json_body(refused).await;
    assert!(
        body["error"]["message"]
            .as_str()
            .expect("a message")
            .contains("ORPHAN"),
        "the refusal names the entry so an operator knows which row to fix, got {body}"
    );
    assert_eq!(body["error"]["details"][0]["field"], "applies_to");
    assert!(
        config_trees
            .load(tenant(), store_id())
            .await
            .expect("load")
            .is_none(),
        "and the whole publish is refused rather than half-applied"
    );
}

// --- Store groups and the batch publish (ADR-0122) ---------------------------------------------

/// An in-memory `StoreGroupStore` for the batch-publish route tests.
///
/// Version-carrying like the real thing, because the membership write is conditional (ADR-0094),
/// and it keeps the batch tables as flat lists — which is enough to prove the property the record
/// actually promises: **every member gets a row**, whatever happened at it.
/// One stored group: the tenant that owns it, and the record with the version it stands at.
type StoreGroupRow = (TenantId, Versioned<StoreGroup>);

/// A cohort's membership, keyed as `store_group_members` is.
type StoreGroupMembers = HashMap<(TenantId, StoreGroupId), Vec<StoreId>>;

/// One recorded per-store outcome, keyed as `config_batch_results` is.
type BatchResultRow = (TenantId, ConfigBatchId, BatchResult);

#[derive(Clone, Default)]
struct FakeStoreGroups {
    groups: Arc<Mutex<Vec<StoreGroupRow>>>,
    members: Arc<Mutex<StoreGroupMembers>>,
    batches: Arc<Mutex<Vec<ConfigBatch>>>,
    results: Arc<Mutex<Vec<BatchResultRow>>>,
    next_version: Arc<Mutex<u64>>,
}

impl FakeStoreGroups {
    /// The fake's stand-in for `xmin` (ADR-0094).
    fn mint(&self) -> Version {
        let mut next = self.next_version.lock().expect("lock");
        *next += 1;
        Version::new(next.to_string())
    }

    /// Seeds a group and its membership without going through the routes.
    fn seed(&self, group: StoreGroup, members: &[StoreId]) {
        let version = self.mint();
        let key = (group.tenant_id, group.group_id);
        self.groups
            .lock()
            .expect("lock")
            .push((group.tenant_id, Versioned::new(group, version)));
        self.members
            .lock()
            .expect("lock")
            .insert(key, members.to_vec());
    }
}

impl StoreGroupStore for FakeStoreGroups {
    async fn create_group(&self, group: &StoreGroup) -> Result<Version, StoreGroupStoreError> {
        let version = self.mint();
        self.groups.lock().expect("lock").push((
            group.tenant_id,
            Versioned::new(group.clone(), version.clone()),
        ));
        Ok(version)
    }

    async fn list_groups(
        &self,
        tenant_id: TenantId,
    ) -> Result<Vec<Versioned<StoreGroup>>, StoreGroupStoreError> {
        Ok(self
            .groups
            .lock()
            .expect("lock")
            .iter()
            .filter(|(owner, _)| *owner == tenant_id)
            .map(|(_, row)| row.clone())
            .collect())
    }

    async fn update_group(
        &self,
        group: &StoreGroup,
        expected: &Version,
    ) -> Result<UpdateOutcome, StoreGroupStoreError> {
        let version = self.mint();
        let mut rows = self.groups.lock().expect("lock");
        let Some(row) = rows.iter_mut().find(|(owner, row)| {
            *owner == group.tenant_id && row.record.group_id == group.group_id
        }) else {
            return Ok(UpdateOutcome::NotFound);
        };
        if row.1.etag != *expected {
            return Ok(UpdateOutcome::VersionMismatch);
        }
        row.1 = Versioned::new(group.clone(), version.clone());
        Ok(UpdateOutcome::Updated(version))
    }

    async fn list_members(
        &self,
        tenant_id: TenantId,
        group_id: StoreGroupId,
    ) -> Result<Vec<StoreId>, StoreGroupStoreError> {
        Ok(self
            .members
            .lock()
            .expect("lock")
            .get(&(tenant_id, group_id))
            .cloned()
            .unwrap_or_default())
    }

    async fn set_members(
        &self,
        tenant_id: TenantId,
        group_id: StoreGroupId,
        members: &[StoreId],
        expected: &Version,
    ) -> Result<UpdateOutcome, StoreGroupStoreError> {
        let version = self.mint();
        let mut rows = self.groups.lock().expect("lock");
        let Some(row) = rows
            .iter_mut()
            .find(|(owner, row)| *owner == tenant_id && row.record.group_id == group_id)
        else {
            return Ok(UpdateOutcome::NotFound);
        };
        if row.1.etag != *expected {
            return Ok(UpdateOutcome::VersionMismatch);
        }
        row.1 = Versioned::new(row.1.record.clone(), version.clone());
        self.members
            .lock()
            .expect("lock")
            .insert((tenant_id, group_id), members.to_vec());
        Ok(UpdateOutcome::Updated(version))
    }

    async fn start_batch(&self, batch: &ConfigBatch) -> Result<(), StoreGroupStoreError> {
        self.batches.lock().expect("lock").push(batch.clone());
        Ok(())
    }

    async fn record_result(
        &self,
        tenant_id: TenantId,
        batch_id: ConfigBatchId,
        result: &BatchResult,
    ) -> Result<(), StoreGroupStoreError> {
        self.results
            .lock()
            .expect("lock")
            .push((tenant_id, batch_id, result.clone()));
        Ok(())
    }

    async fn finish_batch(
        &self,
        tenant_id: TenantId,
        batch_id: ConfigBatchId,
        finished_at_ms: i64,
    ) -> Result<(), StoreGroupStoreError> {
        if let Some(batch) = self
            .batches
            .lock()
            .expect("lock")
            .iter_mut()
            .find(|batch| batch.tenant_id == tenant_id && batch.batch_id == batch_id)
        {
            batch.finished_at_ms = Some(finished_at_ms);
        }
        Ok(())
    }

    async fn list_batches(
        &self,
        tenant_id: TenantId,
        group_id: StoreGroupId,
        limit: u32,
    ) -> Result<Vec<ConfigBatch>, StoreGroupStoreError> {
        let batches = self.batches.lock().expect("lock");
        let mut mine: Vec<ConfigBatch> = batches
            .iter()
            .filter(|batch| batch.tenant_id == tenant_id && batch.group_id == group_id)
            .cloned()
            .collect();
        mine.sort_by(|left, right| right.started_at_ms.cmp(&left.started_at_ms));
        mine.truncate(limit as usize);
        Ok(mine)
    }

    async fn batch_results(
        &self,
        tenant_id: TenantId,
        batch_id: ConfigBatchId,
    ) -> Result<Vec<BatchResult>, StoreGroupStoreError> {
        Ok(self
            .results
            .lock()
            .expect("lock")
            .iter()
            .filter(|(owner, batch, _)| *owner == tenant_id && *batch == batch_id)
            .map(|(_, _, result)| result.clone())
            .collect())
    }
}

/// A `CampaignStore` that holds nothing — the batch registry needs all seven authoring seams, and
/// these tests exercise the `menu` and `tax` nodes.
