    let ledger = Arc::new(FakeAnchors::holding(&[held_anchor(42, "ab")]));
    let cloud = Cloud::new(FakeStore::new()).with_anchor_ledger(ledger.clone());

    cloud
        .ingest(&[anchor_event(1, 42, "ab")])
        .await
        .expect("ingest");

