// --- Vendor connections (ADR-0153) ----------------------------------------------------------------

/// A version-carrying, tenant-scoped in-memory `ConnectionStore`, like [`FakeReasonCodes`], that
/// also lets a test read back exactly what reached the store — which is where "sealed before it is
/// stored" is proved.
/// One stored connection: the tenant that owns it, and the record at its version.
type ConnectionRow = (TenantId, Versioned<pos_cloud::connections::Connection>);

#[derive(Default, Clone)]
struct FakeConnections {
    rows: Arc<Mutex<Vec<ConnectionRow>>>,
    next_version: Arc<Mutex<u64>>,
}

impl FakeConnections {
    fn mint(&self) -> Version {
        let mut next = self.next_version.lock().expect("lock");
        *next += 1;
        Version::new(next.to_string())
    }

    /// The stored record, sealed values included.
    fn stored(&self, connection_id: &str) -> Option<pos_cloud::connections::Connection> {
        self.rows
            .lock()
            .expect("lock")
            .iter()
            .find(|(_, row)| row.record.connection_id == connection_id)
            .map(|(_, row)| row.record.clone())
    }
}

impl pos_cloud::connections::ConnectionStore for FakeConnections {
    async fn list(
        &self,
        tenant_id: TenantId,
    ) -> Result<
        Vec<Versioned<pos_cloud::connections::Connection>>,
        pos_cloud::connections::ConnectionStoreError,
    > {
        let mut mine: Vec<_> = self
            .rows
            .lock()
            .expect("lock")
            .iter()
            .filter(|(owner, _)| *owner == tenant_id)
            .map(|(_, row)| row.clone())
            .collect();
        mine.sort_by(|a, b| a.record.connection_id.cmp(&b.record.connection_id));
        Ok(mine)
    }

    async fn get(
        &self,
        tenant_id: TenantId,
        connection_id: &str,
    ) -> Result<
        Option<Versioned<pos_cloud::connections::Connection>>,
        pos_cloud::connections::ConnectionStoreError,
    > {
        Ok(self
            .rows
            .lock()
            .expect("lock")
            .iter()
            .find(|(owner, row)| *owner == tenant_id && row.record.connection_id == connection_id)
            .map(|(_, row)| row.clone()))
    }

    async fn create(
        &self,
        tenant_id: TenantId,
        connection: &pos_cloud::connections::Connection,
    ) -> Result<CreateOutcome, pos_cloud::connections::ConnectionStoreError> {
        let version = self.mint();
        let mut rows = self.rows.lock().expect("lock");
        if rows.iter().any(|(owner, row)| {
            *owner == tenant_id && row.record.connection_id == connection.connection_id
        }) {
            return Ok(CreateOutcome::AlreadyExists);
        }
        rows.push((
            tenant_id,
            Versioned::edited(connection.clone(), version.clone(), NOW_MS),
        ));
        Ok(CreateOutcome::Created(version))
    }

    async fn update(
        &self,
        tenant_id: TenantId,
        connection: &pos_cloud::connections::Connection,
        expected: &Version,
    ) -> Result<UpdateOutcome, pos_cloud::connections::ConnectionStoreError> {
        let version = self.mint();
        let mut rows = self.rows.lock().expect("lock");
        let Some((_, row)) = rows.iter_mut().find(|(owner, row)| {
            *owner == tenant_id && row.record.connection_id == connection.connection_id
        }) else {
            return Ok(UpdateOutcome::NotFound);
        };
        if &row.etag != expected {
            return Ok(UpdateOutcome::VersionMismatch);
        }
        row.record = connection.clone();
        row.etag = version.clone();
        row.updated_at_ms = Some(NOW_MS);
        Ok(UpdateOutcome::Updated(version))
    }

    async fn delete(
        &self,
        tenant_id: TenantId,
        connection_id: &str,
    ) -> Result<(), pos_cloud::connections::ConnectionStoreError> {
        self.rows.lock().expect("lock").retain(|(owner, row)| {
            !(*owner == tenant_id && row.record.connection_id == connection_id)
        });
        Ok(())
    }
}

/// A gateway whose schema has a required secret, and a ledger — a family a scope may have only one
/// of. Test descriptors, so the rules are proved without depending on which real vendors exist.
static TEST_GATEWAY: pos_providers::ProviderDescriptor = pos_providers::ProviderDescriptor {
    provider_id: "qr.test_gateway",
    family: pos_providers::Family::QrPayment,
    name_key: "provider.qr.test_gateway",
    countries: &[],
    fields: &[
        pos_providers::fields::BASE_URL,
        pos_providers::SettingField {
            key: "api_key",
            label_key: "provider.field.api_key",
            kind: pos_providers::FieldKind::Secret { max_len: 64 },
            required: true,
        },
    ],
    capabilities: &[],
    sandbox: true,
};
static TEST_LEDGER: pos_providers::ProviderDescriptor = pos_providers::ProviderDescriptor {
    provider_id: "erp.test_ledger",
    family: pos_providers::Family::Erp,
    name_key: "provider.erp.test_ledger",
    countries: &[],
    fields: &[],
    capabilities: &[],
    sandbox: true,
};

/// The sealing key the tests configure.
fn test_integration_secret() -> pos_cloud::connections::ConnectionSecret {
    pos_cloud::connections::ConnectionSecret::new("ab".repeat(32))
}

fn connection_app(
    admin: FakeAdmin,
    connections: FakeConnections,
    secret: Option<pos_cloud::connections::ConnectionSecret>,
    audit: Arc<dyn AuditRecorder>,
) -> axum::Router {
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        FakeConfigTrees::default(),
        FakeWebhooks::default(),
    );
    let providers =
        pos_providers::Registry::new([&TEST_GATEWAY, &TEST_LEDGER]).expect("valid test catalogue");
    http::router(app).merge(http::connection_router(
        connections,
        Arc::new(providers),
        secret,
        admin,
        clock(),
        audit,
    ))
}

fn gateway_body(tenant: &str, api_key: Option<&str>) -> serde_json::Value {
    let mut body = serde_json::json!({
        "tenant_id": tenant,
        "provider_id": "qr.test_gateway",
        "scope_level": "CONNECTION_SCOPE_TENANT",
        "display_name": "Test gateway",
        "settings": { "base_url": "https://gateway.example" },
    });
    if let Some(api_key) = api_key {
        body["secrets"] = serde_json::json!({ "api_key": api_key });
    }
    body
}

/// A credential is sealed before it reaches the store, answers only as "set", and is not in the
/// audit trail — and it opens again, for the connector, only under the configured key.
#[tokio::test]
async fn a_connection_seals_its_secret_and_no_read_or_trail_carries_it() {
    let audit = FakeAudit::default();
    let store = FakeConnections::default();
    let router = connection_app(
        provisioned_admin(),
        store.clone(),
        Some(test_integration_secret()),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);
    let plaintext = "live-key-do-not-leak";

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &gateway_body(&tenant, Some(plaintext)),
            &cookie,
        ))
        .await
        .expect("route the create");
    assert_eq!(created.status(), StatusCode::CREATED);
    let body = json_body(created).await;
    assert_eq!(body["secrets_set"], serde_json::json!(["api_key"]));
    assert!(
        !body.to_string().contains(plaintext),
        "the create answers no secret: {body}"
    );
    let id = body["connection_id"].as_str().expect("an id").to_owned();

    let stored = store.stored(&id).expect("stored");
    let sealed = stored.sealed_secrets.get("api_key").expect("sealed");
    assert!(
        !sealed.contains(plaintext),
        "what reached the store is ciphertext"
    );
    let opened = pos_cloud::connections::open(
        &test_integration_secret(),
        pos_cloud::connections::SealedFor {
            tenant_id: TenantId::new(Ulid::from_u128(1)),
            connection_id: &id,
            field_key: "api_key",
        },
        sealed,
    )
    .expect("opens under the configured key");
    assert_eq!(opened.as_str(), plaintext);

    let listed = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/integrations/connections?tenant_id={tenant}"),
                &cookie,
            ))
            .await
            .expect("route the list"),
    )
    .await;
    assert!(!listed.to_string().contains(plaintext));
    assert!(listed[0].get("sealed_secrets").is_none(), "{listed}");

    let entry = last_trail_entry(&audit, "integrations.connection.create")
        .await
        .expect("the create is in the trail");
    let after = entry.after.expect("a summary");
    assert_eq!(after["secrets_set"], serde_json::json!(["api_key"]));
    assert!(
        !after.to_string().contains(plaintext) && !after.to_string().contains(sealed.as_str()),
        "the trail names which secret is set, and holds neither its value nor its ciphertext"
    );
}

/// An edit that does not resend the secret keeps it; switching vendor drops it, because one
/// vendor's key is never another's.
#[tokio::test]
async fn an_edit_keeps_the_stored_secret_and_switching_vendor_drops_it() {
    let store = FakeConnections::default();
    let router = connection_app(
        provisioned_admin(),
        store.clone(),
        Some(test_integration_secret()),
        Arc::new(AuditSink::new(FakeAudit::default())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &gateway_body(&tenant, Some("k1")),
            &cookie,
        ))
        .await
        .expect("route the create");
    let version = etag_of(&created);
    let id = json_body(created).await["connection_id"]
        .as_str()
        .expect("an id")
        .to_owned();
    let row = format!("/admin/integrations/connections/{id}");
    let sealed_before = store.stored(&id).expect("stored").sealed_secrets;

    let mut renamed = gateway_body(&tenant, None);
    renamed["display_name"] = serde_json::json!("Renamed gateway");
    let edited = router
        .clone()
        .oneshot(put_with_etag(&row, &renamed, &cookie, &version))
        .await
        .expect("route the edit");
    assert_eq!(edited.status(), StatusCode::OK);
    let version = etag_of(&edited);
    assert_eq!(
        json_body(edited).await["secrets_set"],
        serde_json::json!(["api_key"])
    );
    assert_eq!(
        store.stored(&id).expect("stored").sealed_secrets,
        sealed_before,
        "the sealed value is kept byte for byte"
    );

    let mut switched = renamed.clone();
    switched["provider_id"] = serde_json::json!("erp.test_ledger");
    switched["settings"] = serde_json::json!({});
    let moved = router
        .clone()
        .oneshot(put_with_etag(&row, &switched, &cookie, &version))
        .await
        .expect("route the switch");
    assert_eq!(moved.status(), StatusCode::OK);
    assert_eq!(json_body(moved).await["secrets_set"], serde_json::json!([]));
    assert!(store.stored(&id).expect("stored").sealed_secrets.is_empty());
}

/// Every problem with the settings is named at once; a secret with nowhere to be sealed is
/// refused rather than stored; an unknown vendor is refused by name.
#[tokio::test]
async fn a_connection_the_schema_or_the_key_cannot_accept_is_refused() {
    let without_key = connection_app(
        provisioned_admin(),
        FakeConnections::default(),
        None,
        Arc::new(AuditSink::new(FakeAudit::default())),
    );
    let cookie = admin_cookie(&without_key).await;
    let tenant = ulid_text(1);

    let unsealable = without_key
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &gateway_body(&tenant, Some("k1")),
            &cookie,
        ))
        .await
        .expect("route");
    assert_eq!(unsealable.status(), StatusCode::SERVICE_UNAVAILABLE);
    assert!(
        json_body(unsealable).await["error"]["message"]
            .as_str()
            .is_some_and(|message| message.contains("integration_secret"))
    );

    let mut broken = gateway_body(&tenant, None);
    broken["settings"] = serde_json::json!({ "base_url": "http://plain.example", "colour": "red" });
    let refused = without_key
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &broken,
            &cookie,
        ))
        .await
        .expect("route");
    assert_eq!(refused.status(), StatusCode::BAD_REQUEST);
    let details = json_body(refused).await["error"]["details"].clone();
    let reasons: Vec<(String, String)> = details
        .as_array()
        .expect("details")
        .iter()
        .map(|detail| {
            (
                detail["field"].as_str().unwrap_or_default().to_owned(),
                detail["reason"].as_str().unwrap_or_default().to_owned(),
            )
        })
        .collect();
    assert_eq!(
        reasons,
        vec![
            ("settings.colour".to_owned(), "SETTING_UNKNOWN".to_owned()),
            ("settings.base_url".to_owned(), "SETTING_INVALID".to_owned()),
            ("settings.api_key".to_owned(), "SETTING_MISSING".to_owned()),
        ]
    );

    let mut unknown = gateway_body(&tenant, None);
    unknown["provider_id"] = serde_json::json!("qr.nobody");
    let refused = without_key
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &unknown,
            &cookie,
        ))
        .await
        .expect("route");
    assert_eq!(refused.status(), StatusCode::BAD_REQUEST);
    assert_eq!(
        json_body(refused).await["error"]["details"][0]["reason"],
        "PROVIDER_UNKNOWN"
    );
}

/// A scope has one enabled ledger at most; a second is refused until the first is disabled, and a
/// Viewer may read connections but not write one.
#[tokio::test]
async fn a_scope_has_one_ledger_and_only_a_manager_writes() {
    let admin = provisioned_admin();
    let router = connection_app(
        admin.clone(),
        FakeConnections::default(),
        Some(test_integration_secret()),
        Arc::new(AuditSink::new(FakeAudit::default())),
    );
    let cookie = admin_cookie(&router).await;
    let tenant = ulid_text(1);
    let ledger = |name: &str, enabled: bool| {
        serde_json::json!({
            "tenant_id": tenant,
            "provider_id": "erp.test_ledger",
            "scope_level": "CONNECTION_SCOPE_TENANT",
            "display_name": name,
            "enabled": enabled,
        })
    };

    let first = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &ledger("Books", true),
            &cookie,
        ))
        .await
        .expect("route");
    assert_eq!(first.status(), StatusCode::CREATED);
    let second = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &ledger("Second books", true),
            &cookie,
        ))
        .await
        .expect("route");
    assert_eq!(second.status(), StatusCode::CONFLICT);
    assert_eq!(
        json_body(second).await["error"]["details"][0]["reason"],
        "CONNECTION_SCOPE_TAKEN"
    );
    let parked = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &ledger("Second books, parked", false),
            &cookie,
        ))
        .await
        .expect("route");
    assert_eq!(
        parked.status(),
        StatusCode::CREATED,
        "a disabled one is kept for a switch back"
    );

    let viewer = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let read = router
        .clone()
        .oneshot(get_with_cookie(
            &format!("/admin/integrations/connections?tenant_id={tenant}"),
            &viewer,
        ))
        .await
        .expect("route");
    assert_eq!(read.status(), StatusCode::OK);
    let write = router
        .oneshot(post_with_cookie(
            "/admin/integrations/connections",
            &ledger("A viewer's books", false),
            &viewer,
        ))
        .await
        .expect("route");
    assert_eq!(write.status(), StatusCode::FORBIDDEN);
}

// --- Integrations publish (ADR-0153 decision 5) --------------------------------------------------

/// A store connected to a card terminal of its own, sitting under a brand with a ledger, in a tenant
/// with a tenant-wide ledger and courier: the publish sends it the terminal (with its settings), the
/// brand's ledger alone (the tenant's is shadowed), and the courier (without its settings) — and no
/// secret, which the node cannot carry.
/// The publish router over a seeded tenant: a store under a brand, a tenant-wide ledger and courier,
/// the brand's own ledger, and the store's own card terminal — each with a setting and a sealed
/// secret, so what the node leaves out is as visible as what it keeps.
fn seeded_integrations_publish() -> (axum::Router, FakeConfigTrees) {
    use pos_cloud::connections::{Connection, ScopeLevel};

    static TERMINAL: pos_providers::ProviderDescriptor = pos_providers::ProviderDescriptor {
        provider_id: "card.test_terminal",
        family: pos_providers::Family::CardTerminal,
        name_key: "provider.card.test_terminal",
        countries: &[],
        fields: &[],
        capabilities: &[],
        sandbox: true,
    };
    static COURIER: pos_providers::ProviderDescriptor = pos_providers::ProviderDescriptor {
        provider_id: "courier.test_courier",
        family: pos_providers::Family::Courier,
        ..TERMINAL
    };

    let brand = pos_cloud::registry::BrandId::new(Ulid::from_u128(0xB1));
    let registry = FakeRegistry::default();
    registry.stores.lock().expect("lock").push(Versioned::new(
        StoreRecord {
            store_id: store_id(),
            tenant_id: tenant(),
            brand_id: Some(brand),
            name: "Store".to_owned(),
            status: EntityStatus::Active,
        },
        Version::new("1"),
    ));
    let connection = |id: &str, provider: &str, scope: (ScopeLevel, Option<String>)| Connection {
        connection_id: id.to_owned(),
        provider_id: provider.to_owned(),
        scope_level: scope.0,
        scope_id: scope.1,
        display_name: format!("Connection {id}"),
        enabled: true,
        settings: BTreeMap::from([(
            "address".to_owned(),
            pos_providers::SettingValue::Text("192.0.2.40".to_owned()),
        )]),
        sealed_secrets: BTreeMap::from([("api_key".to_owned(), "c1phertext".to_owned())]),
    };
    let connections = FakeConnections::default();
    for row in [
        connection("01A", "erp.test_ledger", (ScopeLevel::Tenant, None)),
        connection(
            "01B",
            "erp.test_ledger",
            (ScopeLevel::Brand, Some(brand.to_string())),
        ),
        connection("01C", "courier.test_courier", (ScopeLevel::Tenant, None)),
        connection(
            "01D",
            "card.test_terminal",
            (ScopeLevel::Store, Some(store_id().to_string())),
        ),
    ] {
        connections
            .rows
            .lock()
            .expect("lock")
            .push((tenant(), Versioned::new(row, Version::new("1"))));
    }

    let admin = provisioned_admin();
    let config_trees = FakeConfigTrees::default();
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
        FakeWebhooks::default(),
    );
    let providers = pos_providers::Registry::new([&TEST_LEDGER, &COURIER, &TERMINAL])
        .expect("valid test catalogue");
    let router = http::router(app).merge(http::config_integrations_router(
        connections,
        Arc::new(providers),
        registry,
        config_trees.clone(),
        admin,
        clock(),
        Arc::new(NoopAuditRecorder),
    ));
    (router, config_trees)
}

#[tokio::test]
async fn publishing_integrations_sends_a_store_what_serves_it_and_no_secret() {
    let (router, config_trees) = seeded_integrations_publish();
    let cookie = admin_cookie(&router).await;

    let published = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/integrations",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": store_id().as_ulid().to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
    assert_eq!(json_body(published).await["integrations"], 3);

    let state = config_trees
        .load(tenant(), store_id())
        .await
        .expect("load")
        .expect("a published tree");
    let node = &state.record.layers[2]["integrations"];
    let ids: Vec<&str> = node["integrations"]
        .as_array()
        .expect("a list")
        .iter()
        .filter_map(|integration| integration["connection_id"].as_str())
        .collect();
    assert_eq!(ids, vec!["01D", "01B", "01C"]);
    assert_eq!(
        node["integrations"][0]["family"],
        "INTEGRATION_FAMILY_CARD_TERMINAL"
    );
    assert_eq!(node["integrations"][0]["settings"]["address"], "192.0.2.40");
    assert!(
        node["integrations"][2].get("settings").is_none(),
        "a courier is the cloud's to drive; its settings stay there"
    );
    assert!(
        !node.to_string().contains("c1phertext"),
        "no secret, sealed or not: {node}"
    );

    // A store the tenant does not have is refused, not published to.
    let unknown = router
        .oneshot(put_with_cookie(
            "/admin/config/integrations",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": Ulid::from_u128(0xDEAD).to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(unknown.status(), StatusCode::NOT_FOUND);
}

// --- Settings (ADR-0160 decision 3) -----------------------------------------------------------

/// A tenant-scoped in-memory `SettingsStore`: a write replaces the value in its slot.
#[derive(Default, Clone)]
struct FakeSettings {
    rows: Arc<Mutex<Vec<(TenantId, pos_cloud::settings::SettingValue)>>>,
}

impl pos_cloud::settings::SettingsStore for FakeSettings {
    async fn list(
        &self,
        tenant_id: TenantId,
    ) -> Result<Vec<pos_cloud::settings::SettingValue>, pos_cloud::settings::SettingsStoreError>
    {
        Ok(self
            .rows
            .lock()
            .expect("lock")
            .iter()
            .filter(|(owner, _)| *owner == tenant_id)
            .map(|(_, value)| value.clone())
            .collect())
    }

    async fn put(
        &self,
        tenant_id: TenantId,
        value: &pos_cloud::settings::SettingValue,
    ) -> Result<(), pos_cloud::settings::SettingsStoreError> {
        let mut rows = self.rows.lock().expect("lock");
        rows.retain(|(owner, held)| {
            !(*owner == tenant_id
                && held.setting_key == value.setting_key
                && held.scope == value.scope
                && held.scope_id == value.scope_id)
        });
        rows.push((tenant_id, value.clone()));
        Ok(())
    }

    async fn delete(
        &self,
        tenant_id: TenantId,
        setting_key: &str,
        scope: pos_proto::settings::SettingScope,
        scope_id: &str,
    ) -> Result<bool, pos_cloud::settings::SettingsStoreError> {
        let mut rows = self.rows.lock().expect("lock");
        let before = rows.len();
        rows.retain(|(owner, held)| {
            !(*owner == tenant_id
                && held.setting_key == setting_key
                && held.scope.known() == scope
                && held.scope_id == scope_id)
        });
        Ok(rows.len() < before)
    }
}

const NO_SHIFT_SELLING: &str = "shift.no_shift_selling";

fn settings_brand() -> pos_cloud::registry::BrandId {
    pos_cloud::registry::BrandId::new(Ulid::from_u128(0xB4A0D))
}

/// Three stores of one tenant: two of a brand, one without; a group holding the first and the
/// third; and a second group, archived.
fn settings_stores() -> [StoreId; 3] {
    [
        StoreId::new(Ulid::from_u128(0x5A01)),
        StoreId::new(Ulid::from_u128(0x5A02)),
        StoreId::new(Ulid::from_u128(0x5A03)),
    ]
}

fn settings_group() -> StoreGroupId {
    StoreGroupId::new(Ulid::from_u128(0x6A01))
}

fn archived_group() -> StoreGroupId {
    StoreGroupId::new(Ulid::from_u128(0x6A02))
}

/// The settings routes over fakes, with the layout above seeded.
fn settings_app() -> (axum::Router, FakeConfigTrees, FakeStoreGroups) {
    let admin = provisioned_admin();
    let config_trees = FakeConfigTrees::default();
    let registry = FakeRegistry::default();
    let [first, second, third] = settings_stores();
    registry.brands.lock().expect("lock").push(Versioned::new(
        BrandRecord {
            brand_id: settings_brand(),
            tenant_id: tenant(),
            name: "Brand".to_owned(),
            status: EntityStatus::Active,
        },
        Version::new("1"),
    ));
    for (store_id, brand_id) in [
        (first, Some(settings_brand())),
        (second, Some(settings_brand())),
        (third, None),
    ] {
        registry.stores.lock().expect("lock").push(Versioned::new(
            StoreRecord {
                store_id,
                tenant_id: tenant(),
                brand_id,
                name: format!("Store {}", store_id.as_ulid()),
                status: EntityStatus::Active,
            },
            Version::new("1"),
        ));
    }
    let groups = FakeStoreGroups::default();
    groups.seed(
        StoreGroup {
            group_id: settings_group(),
            tenant_id: tenant(),
            name: "North".to_owned(),
            status: EntityStatus::Active,
        },
        &[first, third],
    );
    groups.seed(
        StoreGroup {
            group_id: archived_group(),
            tenant_id: tenant(),
            name: "Closed".to_owned(),
            status: EntityStatus::Archived,
        },
        &[second],
    );
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
        FakeWebhooks::default(),
    );
    let router = http::router(app)
        .merge(http::settings_router(
            FakeSettings::default(),
            registry,
            groups.clone(),
            config_trees.clone(),
            admin.clone(),
            clock(),
            Arc::new(NoopAuditRecorder),
        ))
        // The tender publish, whose node the tip keys share (ADR-0160).
        .merge(http::config_channels_router(
            config_trees.clone(),
            admin,
            clock(),
            Arc::new(NoopAuditRecorder),
        ));
    (router, config_trees, groups)
}

fn put_setting(scope: &str, scope_id: &str, value: &str) -> serde_json::Value {
    serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "setting_key": NO_SHIFT_SELLING,
        "scope": scope,
        "scope_id": scope_id,
        "value": value,
    })
}

/// The value a store's Tenant layer carries for `shift.no_shift_selling`, if any.
async fn tenant_layer_shift(config_trees: &FakeConfigTrees, store_id: StoreId) -> Option<String> {
    let tree = config_trees.load(tenant(), store_id).await.expect("load")?;
    tree.record.layers[0]["shift"]["no_shift_selling"]
        .as_str()
        .map(str::to_owned)
}

/// Each store a write reached and its outcome, in the order the response lists them.
fn outcomes(body: &serde_json::Value) -> Vec<(String, String)> {
    body["stores"]
        .as_array()
        .expect("a list of stores")
        .iter()
        .map(|store| {
            (
                store["store_id"].as_str().unwrap_or_default().to_owned(),
                store["outcome"].as_str().unwrap_or_default().to_owned(),
            )
        })
        .collect()
}

#[tokio::test]
async fn a_brand_value_reaches_the_brands_stores_on_their_tenant_layer_and_no_other() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, second, third] = settings_stores();
    let brand = settings_brand().to_string();

    let written = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/settings",
            &put_setting("SETTING_SCOPE_BRAND", &brand, "NO_SHIFT_SELLING_REFUSE"),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::OK);
    let body = json_body(written).await;
    assert_eq!(
        outcomes(&body),
        vec![
            (first.to_string(), "SETTING_PUBLISH_APPLIED".to_owned()),
            (second.to_string(), "SETTING_PUBLISH_APPLIED".to_owned()),
        ],
        "the brand's two stores, and not the third"
    );
    for store_id in [first, second] {
        assert_eq!(
            tenant_layer_shift(&config_trees, store_id).await.as_deref(),
            Some("NO_SHIFT_SELLING_REFUSE")
        );
        let tree = config_trees
            .load(tenant(), store_id)
            .await
            .expect("load")
            .expect("a tree");
        assert!(
            tree.record.layers[2].get("shift").is_none(),
            "the Store layer, which node routes write, is not touched"
        );
    }
    assert_eq!(tenant_layer_shift(&config_trees, third).await, None);

    // The same write again changes nothing, so no store is given a new version.
    let again = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/settings",
            &put_setting("SETTING_SCOPE_BRAND", &brand, "NO_SHIFT_SELLING_REFUSE"),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert!(
        outcomes(&json_body(again).await)
            .iter()
            .all(|(_, outcome)| outcome == "SETTING_PUBLISH_UNCHANGED")
    );

    // What each store runs, and where it comes from.
    let effective = |store_id: StoreId| {
        get_with_cookie(
            &format!(
                "/admin/settings/effective?tenant_id={}&store_id={store_id}",
                tenant().as_ulid()
            ),
            &cookie,
        )
    };
    let first_runs = json_body(
        router
            .clone()
            .oneshot(effective(first))
            .await
            .expect("route"),
    )
    .await;
    assert_eq!(
        first_runs["settings"][0]["value"],
        "NO_SHIFT_SELLING_REFUSE"
    );
    assert_eq!(first_runs["settings"][0]["scope"], "SETTING_SCOPE_BRAND");
    let third_runs = json_body(router.oneshot(effective(third)).await.expect("route")).await;
    assert_eq!(third_runs["settings"][0]["value"], "NO_SHIFT_SELLING_ALLOW");
    assert!(
        third_runs["settings"][0].get("scope").is_none(),
        "a default comes from no scope"
    );
}

#[tokio::test]
async fn a_store_value_wins_over_its_brand_and_clearing_it_falls_back() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = settings_stores();

    for body in [
        put_setting(
            "SETTING_SCOPE_BRAND",
            &settings_brand().to_string(),
            "NO_SHIFT_SELLING_REFUSE",
        ),
        put_setting(
            "SETTING_SCOPE_STORE",
            &first.to_string(),
            "NO_SHIFT_SELLING_ALLOW",
        ),
    ] {
        let written = router
            .clone()
            .oneshot(put_with_cookie("/admin/settings", &body, &cookie))
            .await
            .expect("route the write");
        assert_eq!(written.status(), StatusCode::OK);
    }
    assert_eq!(
        tenant_layer_shift(&config_trees, first).await.as_deref(),
        Some("NO_SHIFT_SELLING_ALLOW"),
        "the store's own value is the more specific"
    );

    let cleared = router
        .clone()
        .oneshot(delete_with_cookie(
            &format!(
                "/admin/settings?tenant_id={}&setting_key={NO_SHIFT_SELLING}\
                 &scope=SETTING_SCOPE_STORE&scope_id={first}",
                tenant().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the clear");
    assert_eq!(cleared.status(), StatusCode::OK);
    assert_eq!(
        tenant_layer_shift(&config_trees, first).await.as_deref(),
        Some("NO_SHIFT_SELLING_REFUSE"),
        "the brand's value again"
    );

    let nothing_there = router
        .oneshot(delete_with_cookie(
            &format!(
                "/admin/settings?tenant_id={}&setting_key={NO_SHIFT_SELLING}\
                 &scope=SETTING_SCOPE_STORE&scope_id={first}",
                tenant().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the clear");
    assert_eq!(nothing_there.status(), StatusCode::NOT_FOUND);
}

#[tokio::test]
async fn a_new_store_is_given_the_owners_values_once() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [_, _, third] = settings_stores();
    let presets = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "store_id": third.to_string(),
    });

    let applied = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/settings/presets",
            &presets,
            &cookie,
        ))
        .await
        .expect("route the presets");
    assert_eq!(applied.status(), StatusCode::OK);
    assert_eq!(
        json_body(applied).await["applied"],
        serde_json::json!([
            NO_SHIFT_SELLING,
            "shift.drawer_model",
            "session.idle_lock_seconds",
            "permissions.enforced",
            "printing.receipt_language",
            "qr.table_order"
        ])
    );
    assert_eq!(
        tenant_layer_shift(&config_trees, third).await.as_deref(),
        Some("NO_SHIFT_SELLING_REFUSE"),
        "a new store refuses to sell with no shift open (the owner, 2026-09-30)"
    );
    assert_eq!(
        tenant_layer_node(&config_trees, third, "shift").await,
        Some(serde_json::json!({
            "no_shift_selling": "NO_SHIFT_SELLING_REFUSE",
            "drawer_model": "DRAWER_MODEL_PER_TERMINAL",
        })),
        "a new store keeps a drawer for each till (the owner, 2026-10-01; ADR-0167 decision 1)"
    );
    assert_eq!(
        tenant_layer_session(&config_trees, third).await,
        Some(serde_json::json!({ "idle_lock_seconds": 120 })),
        "a new store's till locks after two minutes without a touch (the owner, 2026-10-01)"
    );
    assert_eq!(
        tenant_layer_node(&config_trees, third, "permissions").await,
        Some(serde_json::json!({ "enforced": true })),
        "a new store decides with each person's own permissions from its first day (ADR-0158)"
    );
    // One token for every country, because the store has no country yet when the console gives it
    // these values. Its edge reads the language from its `locale` node once that names one.
    assert_eq!(
        tenant_layer_node(&config_trees, third, "printing").await,
        Some(serde_json::json!({ "receipt_language": "RECEIPT_LANGUAGE_COUNTRY" })),
        "a new store prints its receipts in its country's language (the owner, 2026-10-01)"
    );
    assert_eq!(
        tenant_layer_node(&config_trees, third, "qr").await,
        Some(serde_json::json!({ "table_order": "TABLE_ORDER_JOIN" })),
        "a new store's guest orders join the table's order (the owner, 2026-10-01)"
    );

    let again = router
        .oneshot(post_with_cookie(
            "/admin/settings/presets",
            &presets,
            &cookie,
        ))
        .await
        .expect("route the presets");
    assert_eq!(
        json_body(again).await["applied"],
        serde_json::json!([]),
        "a store that already sets the value keeps it"
    );
}

#[tokio::test]
async fn a_group_value_reaches_a_store_that_joins_once_it_is_republished() {
    let (router, config_trees, groups) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, second, third] = settings_stores();

    let written = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/settings",
            &put_setting(
                "SETTING_SCOPE_STORE_GROUP",
                &settings_group().to_string(),
                "NO_SHIFT_SELLING_REFUSE",
            ),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(
        outcomes(&json_body(written).await)
            .iter()
            .map(|(store, _)| store.clone())
            .collect::<Vec<_>>(),
        vec![first.to_string(), third.to_string()]
    );
    assert_eq!(tenant_layer_shift(&config_trees, second).await, None);

    groups
        .members
        .lock()
        .expect("lock")
        .insert((tenant(), settings_group()), vec![first, second, third]);
    let republished = router
        .oneshot(post_with_cookie(
            "/admin/settings/publish",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "store_id": second.to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(republished.status(), StatusCode::OK);
    assert_eq!(
        tenant_layer_shift(&config_trees, second).await.as_deref(),
        Some("NO_SHIFT_SELLING_REFUSE")
    );
}

#[tokio::test]
async fn a_write_the_register_or_the_tenant_refuses_reaches_no_store() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = settings_stores();
    let store = first.to_string();

    let refused = |body: serde_json::Value| {
        let router = router.clone();
        let cookie = cookie.clone();
        async move {
            router
                .oneshot(put_with_cookie("/admin/settings", &body, &cookie))
                .await
                .expect("route the write")
                .status()
        }
    };
    let unknown_setting = serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "setting_key": "shift.no_such_setting",
        "scope": "SETTING_SCOPE_STORE",
        "scope_id": store,
        "value": "NO_SHIFT_SELLING_REFUSE",
    });
    assert_eq!(refused(unknown_setting).await, StatusCode::BAD_REQUEST);
    assert_eq!(
        refused(put_setting(
            "SETTING_SCOPE_STORE",
            &store,
            "NO_SHIFT_SELLING_LATER"
        ))
        .await,
        StatusCode::BAD_REQUEST
    );
    assert_eq!(
        refused(put_setting(
            "SETTING_SCOPE_PLANET",
            &store,
            "NO_SHIFT_SELLING_REFUSE"
        ))
        .await,
        StatusCode::BAD_REQUEST
    );
    assert_eq!(
        refused(put_setting(
            "SETTING_SCOPE_TENANT",
            &Ulid::from_u128(0xBAD).to_string(),
            "NO_SHIFT_SELLING_REFUSE"
        ))
        .await,
        StatusCode::BAD_REQUEST,
        "a tenant-scope value names its own tenant"
    );
    assert_eq!(
        refused(put_setting(
            "SETTING_SCOPE_BRAND",
            &Ulid::from_u128(0xBAD).to_string(),
            "NO_SHIFT_SELLING_REFUSE"
        ))
        .await,
        StatusCode::NOT_FOUND
    );
    assert_eq!(
        refused(put_setting(
            "SETTING_SCOPE_STORE_GROUP",
            &archived_group().to_string(),
            "NO_SHIFT_SELLING_REFUSE"
        ))
        .await,
        StatusCode::CONFLICT,
        "an archived group's values would reach no store"
    );
    assert_eq!(tenant_layer_shift(&config_trees, first).await, None);
}

#[tokio::test]
async fn the_catalogue_lists_each_setting_with_its_default_and_new_store_value() {
    let (router, _, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let catalogue = router
        .oneshot(get_with_cookie("/admin/settings/catalogue", &cookie))
        .await
        .expect("route the catalogue");
    assert_eq!(catalogue.status(), StatusCode::OK);
    let body = json_body(catalogue).await;
    let shift = body["settings"]
        .as_array()
        .expect("a list")
        .iter()
        .find(|setting| setting["setting_key"] == NO_SHIFT_SELLING)
        .expect("the no-shift setting is listed");
    assert_eq!(shift["default"], "NO_SHIFT_SELLING_ALLOW");
    assert_eq!(shift["preset"], "NO_SHIFT_SELLING_REFUSE");
    assert_eq!(shift["kind"], "SETTING_KIND_CHOICE");
    assert!(
        shift.get("summary").is_none(),
        "the screen labels a setting from its own translations"
    );
    // A choice carries its values and nothing a whole number would: the screen draws its form from
    // which of the two it finds.
    assert_eq!(
        shift["values"],
        serde_json::json!(["NO_SHIFT_SELLING_ALLOW", "NO_SHIFT_SELLING_REFUSE"])
    );
    for absent in ["min", "max", "unit"] {
        assert!(
            shift.get(absent).is_none(),
            "a choice carries no `{absent}`"
        );
    }
}

#[tokio::test]
async fn the_printing_settings_are_offered_as_the_register_says_and_reach_their_node() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = settings_stores();

    // Offered as the screen draws them: a choice of language, and a switch.
    let catalogue = router
        .clone()
        .oneshot(get_with_cookie("/admin/settings/catalogue", &cookie))
        .await
        .expect("route the catalogue");
    let body = json_body(catalogue).await;
    let listed = |key: &str| {
        body["settings"]
            .as_array()
            .expect("a list")
            .iter()
            .find(|setting| setting["setting_key"] == key)
            .cloned()
            .unwrap_or_else(|| panic!("{key} is listed"))
    };
    let language = listed("printing.receipt_language");
    assert_eq!(language["kind"], "SETTING_KIND_CHOICE");
    assert_eq!(language["default"], "RECEIPT_LANGUAGE_DISPLAY");
    assert_eq!(language["preset"], "RECEIPT_LANGUAGE_COUNTRY");
    let on_settle = listed("printing.receipt_printed_on_settle");
    assert_eq!(on_settle["kind"], "SETTING_KIND_BOOL");
    assert_eq!(on_settle["default"], true);
    // Each tax line's components print unless a store turns them off, which every receipt did
    // before the switch (ADR-0168 decision 4), so a new store is given nothing else.
    let components = listed("printing.receipt_tax_components");
    assert_eq!(components["kind"], "SETTING_KIND_BOOL");
    assert_eq!(components["default"], true);
    assert!(components["preset"].is_null(), "{components}");
    // A bilingual receipt is a choice each store makes, so a new store is given none (the owner,
    // 2026-10-01).
    let second = listed("printing.receipt_second_language");
    assert_eq!(second["kind"], "SETTING_KIND_CHOICE");
    assert_eq!(second["default"], "RECEIPT_SECOND_LANGUAGE_NONE");
    assert!(second["preset"].is_null(), "{second}");
    // The size a line the printer cannot draw is drawn at, in printer dots (ADR-0160 decision 6).
    let size = listed("printing.font_size_dots");
    assert_eq!(size["kind"], "SETTING_KIND_INT");
    assert_eq!(size["unit"], "SETTING_UNIT_COUNT");
    assert_eq!(size["min"], 16);
    assert_eq!(size["max"], 48);
    assert_eq!(size["default"], 24);
    assert!(size["preset"].is_null(), "{size}");

    // A store that turns the switches off and sets a size has all three on its `printing` node.
    for (setting_key, value) in [
        (
            "printing.receipt_printed_on_settle",
            serde_json::json!(false),
        ),
        ("printing.font_size_dots", serde_json::json!(32)),
        ("printing.receipt_tax_components", serde_json::json!(false)),
    ] {
        let written = router
            .clone()
            .oneshot(put_with_cookie(
                "/admin/settings",
                &serde_json::json!({
                    "tenant_id": tenant().as_ulid().to_string(),
                    "setting_key": setting_key,
                    "scope": "SETTING_SCOPE_STORE",
                    "scope_id": first.to_string(),
                    "value": value,
                }),
                &cookie,
            ))
            .await
            .expect("route the write");
        assert_eq!(written.status(), StatusCode::OK, "{setting_key}");
    }
    assert_eq!(
        tenant_layer_node(&config_trees, first, "printing").await,
        Some(serde_json::json!({
            "receipt_printed_on_settle": false,
            "font_size_dots": 32,
            "receipt_tax_components": false,
        }))
    );
}

/// `shift.drawer_model` (ADR-0167 decisions 1 and 7) is offered from the release that ships the
/// till's screens for a drawer per till, with a drawer per till for a new store, and a store's value
/// reaches its `shift` node.
#[tokio::test]
async fn the_drawer_model_is_offered_from_its_release_with_a_drawer_per_till_for_a_new_store() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = settings_stores();

    let catalogue = json_body(
        router
            .clone()
            .oneshot(get_with_cookie("/admin/settings/catalogue", &cookie))
            .await
            .expect("route the catalogue"),
    )
    .await;
    let model = catalogue["settings"]
        .as_array()
        .expect("a list")
        .iter()
        .find(|setting| setting["setting_key"] == "shift.drawer_model")
        .cloned()
        .expect("the setting is listed");
    assert_eq!(model["kind"], "SETTING_KIND_CHOICE");
    assert_eq!(
        model["default"], "DRAWER_MODEL_PER_STORE",
        "a store that sets nothing keeps its one drawer"
    );
    assert_eq!(
        model["preset"], "DRAWER_MODEL_PER_TERMINAL",
        "a new store keeps a drawer for each till"
    );
    assert_eq!(
        model["values"],
        serde_json::json!(["DRAWER_MODEL_PER_STORE", "DRAWER_MODEL_PER_TERMINAL"])
    );
    assert_eq!(
        model["since"], "0.14.1",
        "a store on an older release is not offered it, and keeps one drawer"
    );

    let written = router
        .oneshot(put_with_cookie(
            "/admin/settings",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "setting_key": "shift.drawer_model",
                "scope": "SETTING_SCOPE_STORE",
                "scope_id": first.to_string(),
                "value": "DRAWER_MODEL_PER_TERMINAL",
            }),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::OK);
    assert_eq!(
        tenant_layer_node(&config_trees, first, "shift").await,
        Some(serde_json::json!({ "drawer_model": "DRAWER_MODEL_PER_TERMINAL" }))
    );
}

/// `shift.close_report` (ADR-0167 decision 10) is offered from the release whose edge honours it,
/// and a store's value reaches its `shift` node.
#[tokio::test]
async fn the_close_report_is_offered_from_its_release_and_reaches_the_shift_node() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = settings_stores();

    let catalogue = json_body(
        router
            .clone()
            .oneshot(get_with_cookie("/admin/settings/catalogue", &cookie))
            .await
            .expect("route the catalogue"),
    )
    .await;
    let close_report = catalogue["settings"]
        .as_array()
        .expect("a list")
        .iter()
        .find(|setting| setting["setting_key"] == "shift.close_report")
        .cloned()
        .expect("the setting is listed");
    assert_eq!(close_report["kind"], "SETTING_KIND_CHOICE");
    assert_eq!(
        close_report["default"], "CLOSE_REPORT_PER_DRAWER",
        "a store that sets nothing prints each drawer's report where it closes, as before"
    );
    assert!(close_report["preset"].is_null(), "{close_report}");
    assert_eq!(
        close_report["values"],
        serde_json::json!([
            "CLOSE_REPORT_PER_DRAWER",
            "CLOSE_REPORT_COMBINED",
            "CLOSE_REPORT_NONE"
        ])
    );
    assert_eq!(
        close_report["since"], "0.14.1",
        "a store on an older release is not offered it"
    );

    let written = router
        .oneshot(put_with_cookie(
            "/admin/settings",
            &serde_json::json!({
                "tenant_id": tenant().as_ulid().to_string(),
                "setting_key": "shift.close_report",
                "scope": "SETTING_SCOPE_STORE",
                "scope_id": first.to_string(),
                "value": "CLOSE_REPORT_COMBINED",
            }),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::OK);
    assert_eq!(
        tenant_layer_node(&config_trees, first, "shift").await,
        Some(serde_json::json!({ "close_report": "CLOSE_REPORT_COMBINED" }))
    );
}

