/// The message of the refusal a PIN of the wrong length earns, after checking it names the field.
async fn pin_refusal(response: axum::response::Response) -> String {
    assert_eq!(response.status(), StatusCode::BAD_REQUEST);
    let body = json_body(response).await;
    assert_eq!(body["error"]["details"][0]["field"], "pin", "{body}");
    assert_eq!(
        body["error"]["details"][0]["reason"], "OUT_OF_RANGE",
        "{body}"
    );
    body["error"]["message"]
        .as_str()
        .unwrap_or_default()
        .to_owned()
}

/// Whether `employee_id` has a PIN, as the console's read of one person says.
async fn has_pin(router: &axum::Router, cookie: &str, employee_id: EmployeeId) -> bool {
    let person = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!(
                    "/admin/employees/{employee_id}?tenant_id={}",
                    tenant().as_ulid()
                ),
                cookie,
            ))
            .await
            .expect("route the read"),
    )
    .await;
    person["has_pin"] == serde_json::json!(true)
}

/// A PIN is four to eight digits until the tenant writes a minimum. From then on a PIN set or reset
/// has at least that many digits, and never more than eight, and the refusal names the range. A PIN
/// set before is left as it was. The minimum is written through the settings routes and read by the
/// PIN route from the same store, as `main.rs` wires them.
#[tokio::test]
async fn a_pin_set_once_the_tenant_asks_for_more_digits_has_at_least_that_many() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let settings = FakeSettings::default();
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    let config = FakeConfigTrees::default();
    let router = people_app_with_settings(
        admin.clone(),
        people.clone(),
        registry.clone(),
        config.clone(),
        settings.clone(),
        Arc::new(NoopAuditRecorder),
    )
    .merge(http::settings_router(
        settings,
        registry,
        FakeStoreGroups::default(),
        config,
        admin,
        clock(),
        Arc::new(NoopAuditRecorder),
    ));
    let cookie = admin_cookie(&router).await;
    let person = a_person_without_a_pin(&people).await;

    // Nothing written: four to eight digits, as before.
    for pin in ["123", "123456789"] {
        assert_eq!(
            pin_refusal(put_pin(&router, &cookie, person, pin).await).await,
            "the PIN must be 4 to 8 digits",
            "{pin}"
        );
    }
    let four = put_pin(&router, &cookie, person, "1234").await;
    assert_eq!(four.status(), StatusCode::NO_CONTENT);

    let written = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/settings",
            &put_number(PIN_MIN_LENGTH, &serde_json::json!(6)),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::OK);

    // The four-digit PIN is not touched: the store goes on taking it until it is reset.
    assert!(has_pin(&router, &cookie, person).await);
    for pin in ["12345", "123456789"] {
        assert_eq!(
            pin_refusal(put_pin(&router, &cookie, person, pin).await).await,
            "the PIN must be 6 to 8 digits",
            "{pin}"
        );
    }
    for pin in ["123456", "12345678"] {
        let set = put_pin(&router, &cookie, person, pin).await;
        assert_eq!(set.status(), StatusCode::NO_CONTENT, "{pin}");
    }
}

/// A PIN is never held to four when the tenant's minimum cannot be read: the route answers as it
/// does for any store it cannot reach, and no PIN is set.
#[tokio::test]
async fn a_pin_is_refused_while_the_tenants_settings_cannot_be_read() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let registry = FakeRegistry::default();
    seed_store(&registry, tenant(), store_id(), true);
    let router = people_app_with_settings(
        admin,
        people.clone(),
        registry,
        FakeConfigTrees::default(),
        UnreachableSettings,
        Arc::new(NoopAuditRecorder),
    );
    let cookie = admin_cookie(&router).await;
    let person = a_person_without_a_pin(&people).await;

    let refused = put_pin(&router, &cookie, person, "12345678").await;
    assert_eq!(refused.status(), StatusCode::SERVICE_UNAVAILABLE);
    let body = json_body(refused).await;
    assert_eq!(body["error"]["status"], "UNAVAILABLE", "{body}");
    assert!(!has_pin(&router, &cookie, person).await, "no PIN was set");
}

/// The minimum is the tenant's alone, because a person may work at every store: it cannot be
/// written for one store, a brand or a group. Written for every store, it reaches each store's
/// `session` node beside the other session settings, and the node still reads as the edge reads
/// it.
#[tokio::test]
async fn the_pin_minimum_is_written_for_the_whole_tenant_and_rides_the_session_node() {
    let (router, config_trees, _) = settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = settings_stores();

    for (scope, scope_id) in [
        ("SETTING_SCOPE_STORE", first.to_string()),
        ("SETTING_SCOPE_BRAND", settings_brand().to_string()),
        ("SETTING_SCOPE_STORE_GROUP", settings_group().to_string()),
    ] {
        let refused = router
            .clone()
            .oneshot(put_with_cookie(
                "/admin/settings",
                &serde_json::json!({
                    "tenant_id": tenant().as_ulid().to_string(),
                    "setting_key": PIN_MIN_LENGTH,
                    "scope": scope,
                    "scope_id": scope_id,
                    "value": 6,
                }),
                &cookie,
            ))
            .await
            .expect("route the write");
        assert_eq!(refused.status(), StatusCode::BAD_REQUEST, "{scope}");
        let body = json_body(refused).await;
        assert_eq!(body["error"]["details"][0]["field"], "scope", "{scope}");
        assert_eq!(
            body["error"]["details"][0]["reason"], "SCOPE_NOT_ALLOWED",
            "{scope}"
        );
    }
    for store_id in settings_stores() {
        assert_eq!(tenant_layer_session(&config_trees, store_id).await, None);
    }

    for (setting_key, value) in [(PIN_MIN_LENGTH, 6), (LOCKOUT_ATTEMPTS, 3)] {
        let written = router
            .clone()
            .oneshot(put_with_cookie(
                "/admin/settings",
                &put_number(setting_key, &serde_json::json!(value)),
                &cookie,
            ))
            .await
            .expect("route the write");
        assert_eq!(written.status(), StatusCode::OK, "{setting_key}");
    }
    for store_id in settings_stores() {
        let tree = config_trees
            .load(tenant(), store_id)
            .await
            .expect("load")
            .expect("a tree");
        let sent = sent_to(&tree.record)["session"].clone();
        assert_eq!(
            sent,
            serde_json::json!({ "lockout_attempts": 3, "pin_min_length": 6 })
        );
        let session: pos_proto::session::PublishedSession =
            serde_json::from_value(sent).expect("the edge reads the node");
        assert_eq!(session.pin_min_length(), 6);
        assert_eq!(session.lockout_attempts(), 3, "the lockout is unaffected");
        assert_eq!(session.lockout_minutes(), 5);
    }
}

// --- Fees (ADR-0159 decision 1) -----------------------------------------------------------------

fn fees_brand() -> pos_cloud::registry::BrandId {
    pos_cloud::registry::BrandId::new(Ulid::from_u128(0x7A01))
}

/// Two stores of the brand, and a third that no brand holds.
fn fees_stores() -> [StoreId; 3] {
    [
        StoreId::new(Ulid::from_u128(0x7B01)),
        StoreId::new(Ulid::from_u128(0x7B02)),
        StoreId::new(Ulid::from_u128(0x7B03)),
    ]
}

fn fee_item(n: u128) -> MenuItemId {
    MenuItemId::new(Ulid::from_u128(0x7C00 + n))
}

fn fee_category(n: u128) -> ItemCategoryId {
    ItemCategoryId::new(Ulid::from_u128(0x7D00 + n))
}

fn fee_tax_class(n: u128) -> TaxClassId {
    TaxClassId::new(Ulid::from_u128(0x7E00 + n))
}

/// Three items, two of them in the one category, and two tax classes.
fn fee_catalog() -> FakeCatalog {
    let catalog = FakeCatalog::default();
    for (n, category) in [
        (1, Some(fee_category(1))),
        (2, Some(fee_category(1))),
        (3, None),
    ] {
        catalog.items.lock().expect("lock").push(Versioned::new(
            CatalogItem {
                menu_item_id: fee_item(n),
                tenant_id: tenant(),
                name: format!("Item {n}"),
                name_translations: BTreeMap::new(),
                tax_class_id: fee_tax_class(1),
                item_category_id: category,
                item_subcategory_id: None,
                course_id: None,
                image_ref: None,
                status: EntityStatus::Active,
            },
            Version::new("1"),
        ));
    }
    catalog
        .categories
        .lock()
        .expect("lock")
        .push(Versioned::new(
            ItemCategory {
                item_category_id: fee_category(1),
                tenant_id: tenant(),
                name: "Pizza".to_owned(),
                status: EntityStatus::Active,
            },
            Version::new("1"),
        ));
    for n in [1, 2] {
        catalog
            .tax_classes
            .lock()
            .expect("lock")
            .push(Versioned::new(
                TaxClass {
                    tax_class_id: fee_tax_class(n),
                    tenant_id: tenant(),
                    name: format!("Class {n}"),
                    status: EntityStatus::Active,
                },
                Version::new("1"),
            ));
    }
    catalog
}

/// The brand's first store bills in đồng, with a menu of two items and a tax table for one class;
/// its second bills in yen; the third has nothing published.
fn seed_fee_stores(config_trees: &FakeConfigTrees) {
    let [first, second, _] = fees_stores();
    let vnd = pos_proto::money::CurrencyCode::VND;
    let menu = pos_proto::MenuBook::new().with(
        SalesChannel::DineIn,
        pos_proto::MenuCatalog::new()
            .with(pos_proto::MenuEntry::new(
                fee_item(1),
                DisplayName::new("Margherita"),
                pos_proto::money::Money::new(vnd, 95_000),
                fee_tax_class(1),
            ))
            .with(pos_proto::MenuEntry::new(
                fee_item(3),
                DisplayName::new("Lemonade"),
                pos_proto::money::Money::new(vnd, 30_000),
                fee_tax_class(1),
            )),
    );
    let tax = pos_proto::locale::TaxRateTable::new()
        .with(
            fee_tax_class(1),
            SalesChannel::DineIn,
            TaxRate::from_basis_points(800),
        )
        .with(
            fee_tax_class(1),
            SalesChannel::Takeaway,
            TaxRate::from_basis_points(800),
        );
    config_trees.seed_store_layer(
        tenant(),
        first,
        serde_json::json!({
            "locale": { "currency_code": "VND" },
            "tax": serde_json::to_value(&tax).expect("encode the tax table"),
            "menu": serde_json::to_value(&menu).expect("encode the menu"),
        }),
    );
    config_trees.seed_store_layer(
        tenant(),
        second,
        serde_json::json!({ "locale": { "currency_code": "JPY" } }),
    );
}

/// The brand and its three stores, the third held by no brand.
fn fees_registry() -> FakeRegistry {
    let registry = FakeRegistry::default();
    let [first, second, third] = fees_stores();
    registry.brands.lock().expect("lock").push(Versioned::new(
        BrandRecord {
            brand_id: fees_brand(),
            tenant_id: tenant(),
            name: "Brand".to_owned(),
            status: EntityStatus::Active,
        },
        Version::new("1"),
    ));
    for (store_id, brand_id) in [
        (first, Some(fees_brand())),
        (second, Some(fees_brand())),
        (third, None),
    ] {
        registry.stores.lock().expect("lock").push(Versioned::new(
            StoreRecord {
                store_id,
                tenant_id: tenant(),
                brand_id,
                name: format!("Store {}", store_id.as_ulid()),
                status: EntityStatus::Active,
            },
            Version::new("1"),
        ));
    }
    registry
}

/// The fee routes over fakes. The brand's first store bills in đồng with a menu and a tax table,
/// its second bills in yen, and the third has nothing published yet.
fn fees_app() -> (axum::Router, FakeConfigTrees, FakeAudit, FakeAdmin) {
    let admin = provisioned_admin();
    let config_trees = FakeConfigTrees::default();
    let registry = fees_registry();
    let catalog = fee_catalog();
    seed_fee_stores(&config_trees);
    let audit = FakeAudit::default();
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
        FakeWebhooks::default(),
    );
    let router = http::router(app).merge(http::fees_router(
        InMemoryFeeRules::new(),
        registry,
        catalog,
        config_trees.clone(),
        admin.clone(),
        clock(),
        Arc::new(AuditSink::new(audit.clone())),
    ));
    (router, config_trees, audit, admin)
}

/// A `POST` or `PUT /admin/fees` body.
fn fee_body(scope: &str, scope_id: &str, rule: &serde_json::Value) -> serde_json::Value {
    serde_json::json!({
        "tenant_id": tenant().as_ulid().to_string(),
        "scope": scope,
        "scope_id": scope_id,
        "rule": rule,
    })
}

/// A percentage of every line, as the console starts a new rule.
fn percent_fee(code: &str, percent: i64) -> serde_json::Value {
    serde_json::json!({
        "code": code,
        "display_name": "Service charge",
        "display_name_translations": { "vi": "Phí phục vụ" },
        "kind": "FEE_KIND_PERCENT",
        "rate": { "numerator": percent, "denominator": 100 },
    })
}

/// A fee per bill in `currency`.
fn amount_fee(code: &str, currency: &str, amount: i64) -> serde_json::Value {
    serde_json::json!({
        "code": code,
        "display_name": "Delivery",
        "kind": "FEE_KIND_AMOUNT_PER_BILL",
        "amount": { "currency_code": currency, "amount_minor": amount },
    })
}

/// `rule` with its `fee_id` set, as a `PUT` sends it.
fn with_fee_id(rule: &serde_json::Value, fee_id: &str) -> serde_json::Value {
    let mut rule = rule.clone();
    if let Some(fields) = rule.as_object_mut() {
        fields.insert("fee_id".to_owned(), serde_json::json!(fee_id));
    }
    rule
}

/// The `fees` node a store's Store layer carries, parsed as the edge parses it.
async fn store_fees(config_trees: &FakeConfigTrees, store_id: StoreId) -> Option<PublishedFees> {
    let tree = config_trees.load(tenant(), store_id).await.expect("load")?;
    let node = tree.record.layers[2].get("fees")?;
    serde_json::from_str(&node.to_string()).ok()
}

fn tenant_scope_id() -> String {
    tenant().as_ulid().to_string()
}

#[tokio::test]
#[expect(
    clippy::too_many_lines,
    reason = "one fee through its life against the same stores: written for the tenant, overridden \
              for a brand, read back per store, written again unchanged, the override removed, and \
              the list read — split, each part would rebuild the rules the next one starts from"
)]
async fn a_tenant_fee_reaches_every_store_and_a_brand_rule_for_the_same_fee_wins_at_its_stores() {
    let (router, config_trees, _, _) = fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, second, third] = fees_stores();

    let created = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body(
                "FEE_SCOPE_TENANT",
                &tenant_scope_id(),
                &percent_fee("SERVICE", 5),
            ),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(created.status(), StatusCode::CREATED);
    let body = json_body(created).await;
    let fee_id = body["fee_id"].as_str().expect("a minted fee id").to_owned();
    assert_eq!(
        outcomes(&body),
        vec![
            (first.to_string(), "FEE_PUBLISH_APPLIED".to_owned()),
            (second.to_string(), "FEE_PUBLISH_APPLIED".to_owned()),
            (third.to_string(), "FEE_PUBLISH_APPLIED".to_owned()),
        ]
    );
    for store_id in fees_stores() {
        let fees = store_fees(&config_trees, store_id)
            .await
            .expect("a fees node");
        let [fee] = fees.fees.as_slice() else {
            panic!("one fee at {store_id}: {fees:?}");
        };
        assert_eq!(fee.fee_id.to_string(), fee_id);
        assert_eq!(fee.localized_name("vi").as_str(), "Phí phục vụ");
    }

    // The same fee, written for the brand at 10 %, replaces the tenant's at the brand's stores.
    let brand = fees_brand().to_string();
    let overridden = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/fees",
            &fee_body(
                "FEE_SCOPE_BRAND",
                &brand,
                &with_fee_id(&percent_fee("SERVICE", 10), &fee_id),
            ),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(overridden.status(), StatusCode::OK);
    assert_eq!(
        outcomes(&json_body(overridden).await),
        vec![
            (first.to_string(), "FEE_PUBLISH_APPLIED".to_owned()),
            (second.to_string(), "FEE_PUBLISH_APPLIED".to_owned()),
        ],
        "the brand's two stores, and not the third"
    );
    let rate_at = |fees: &PublishedFees| fees.fees.first().and_then(|fee| fee.rate);
    let first_fees = store_fees(&config_trees, first).await.expect("a fees node");
    let third_fees = store_fees(&config_trees, third).await.expect("a fees node");
    assert_eq!(
        rate_at(&first_fees).map(pos_proto::money::Ratio::numerator),
        Some(10)
    );
    assert_eq!(
        rate_at(&third_fees).map(pos_proto::money::Ratio::numerator),
        Some(5)
    );

    // Where each store's fee comes from.
    let effective = |store_id: StoreId| {
        get_with_cookie(
            &format!(
                "/admin/fees/effective?tenant_id={}&store_id={store_id}",
                tenant().as_ulid()
            ),
            &cookie,
        )
    };
    let first_runs = json_body(
        router
            .clone()
            .oneshot(effective(first))
            .await
            .expect("route"),
    )
    .await;
    assert_eq!(first_runs["fees"][0]["scope"], "FEE_SCOPE_BRAND");
    assert_eq!(first_runs["fees"][0]["published"]["rate"]["numerator"], 10);
    assert_eq!(first_runs["publishable"], true);
    let third_runs = json_body(
        router
            .clone()
            .oneshot(effective(third))
            .await
            .expect("route"),
    )
    .await;
    assert_eq!(third_runs["fees"][0]["scope"], "FEE_SCOPE_TENANT");

    // Written again unchanged, no store is given a new version.
    let again = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/fees",
            &fee_body(
                "FEE_SCOPE_BRAND",
                &brand,
                &with_fee_id(&percent_fee("SERVICE", 10), &fee_id),
            ),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert!(
        outcomes(&json_body(again).await)
            .iter()
            .all(|(_, outcome)| outcome == "FEE_PUBLISH_UNCHANGED")
    );

    // The brand's rule removed, its stores run the tenant's again.
    let removed = router
        .clone()
        .oneshot(delete_with_cookie(
            &format!(
                "/admin/fees?tenant_id={}&scope=FEE_SCOPE_BRAND&scope_id={brand}&fee_id={fee_id}",
                tenant().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the delete");
    assert_eq!(removed.status(), StatusCode::OK);
    let first_fees = store_fees(&config_trees, first).await.expect("a fees node");
    assert_eq!(
        rate_at(&first_fees).map(pos_proto::money::Ratio::numerator),
        Some(5)
    );

    let listed = json_body(
        router
            .oneshot(get_with_cookie(
                &format!("/admin/fees?tenant_id={}", tenant().as_ulid()),
                &cookie,
            ))
            .await
            .expect("route the read"),
    )
    .await;
    let rules = listed["rules"].as_array().expect("a list of rules");
    assert_eq!(
        rules.len(),
        1,
        "the tenant's rule, and the brand's no longer"
    );
    assert_eq!(rules[0]["scope"], "FEE_SCOPE_TENANT");
    assert_eq!(rules[0]["rule"]["fee_id"], fee_id.as_str());
}

#[tokio::test]
#[expect(
    clippy::too_many_lines,
    reason = "each refusal a store's configuration causes, against the same stores: a currency on \
              a write and on a delete that would uncover it, a tax class, and a publish to a store \
              that changed currency after its fees reached it"
)]
async fn a_rule_a_store_could_not_apply_is_refused_and_a_store_that_cannot_keeps_its_fees() {
    let (router, config_trees, _, _) = fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, second, third] = fees_stores();

    // A delivery fee in đồng reaches the brand's second store, which bills in yen.
    let refused = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body(
                "FEE_SCOPE_TENANT",
                &tenant_scope_id(),
                &amount_fee("DELIVERY", "VND", 15_000),
            ),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(refused).await;
    assert_eq!(body["error"]["details"][0]["field"], "rule.amount");
    assert_eq!(body["error"]["details"][0]["reason"], "CURRENCY_MISMATCH");
    assert!(
        body["error"]["message"]
            .as_str()
            .is_some_and(|message| message.contains(&second.to_string())),
        "the refusal names the store by id: {body}"
    );
    assert!(
        store_fees(&config_trees, first).await.is_none(),
        "nothing was written"
    );

    // The yen store given its own rule for the fee first, the đồng rule applies everywhere else.
    let fee_id = Ulid::from_u128(0x7F01).to_string();
    for (scope, scope_id, rule) in [
        (
            "FEE_SCOPE_STORE",
            second.to_string(),
            amount_fee("DELIVERY", "JPY", 300),
        ),
        (
            "FEE_SCOPE_TENANT",
            tenant_scope_id(),
            amount_fee("DELIVERY", "VND", 15_000),
        ),
    ] {
        let written = router
            .clone()
            .oneshot(put_with_cookie(
                "/admin/fees",
                &fee_body(scope, &scope_id, &with_fee_id(&rule, &fee_id)),
                &cookie,
            ))
            .await
            .expect("route the write");
        assert_eq!(written.status(), StatusCode::OK, "{scope}");
    }

    // Removing the yen rule would leave the yen store charging đồng.
    let uncovering = router
        .clone()
        .oneshot(delete_with_cookie(
            &format!(
                "/admin/fees?tenant_id={}&scope=FEE_SCOPE_STORE&scope_id={second}&fee_id={fee_id}",
                tenant().as_ulid()
            ),
            &cookie,
        ))
        .await
        .expect("route the delete");
    assert_eq!(uncovering.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(uncovering).await;
    assert_eq!(body["error"]["details"][0]["field"], "fee_id");
    assert_eq!(body["error"]["details"][0]["reason"], "CURRENCY_MISMATCH");

    // A fee taxed at a class the first store has no rate for.
    let taxed = serde_json::json!({
        "code": "SERVICE",
        "display_name": "Service charge",
        "kind": "FEE_KIND_PERCENT",
        "rate": { "numerator": 5, "denominator": 100 },
        "tax": "FEE_TAX_TAX_CLASS",
        "tax_class_id": fee_tax_class(2).to_string(),
    });
    let unrated = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body("FEE_SCOPE_STORE", &first.to_string(), &taxed),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(unrated.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(unrated).await;
    assert_eq!(body["error"]["details"][0]["field"], "rule.tax_class_id");
    assert_eq!(
        body["error"]["details"][0]["reason"],
        "TAX_RATE_NOT_CONFIGURED"
    );

    // A store that comes to bill in yen after the đồng rule reached it is not sent its fees again,
    // and keeps the ones it has.
    config_trees.seed_store_layer(
        tenant(),
        third,
        serde_json::json!({ "locale": { "currency_code": "JPY" } }),
    );
    let published = router
        .oneshot(post_with_cookie(
            "/admin/fees/publish",
            &serde_json::json!({ "tenant_id": tenant_scope_id() }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
    let body = json_body(published).await;
    let stores = body["stores"].as_array().expect("a list of stores");
    let third_result = stores
        .iter()
        .find(|store| store["store_id"] == third.to_string())
        .expect("the third store");
    assert_eq!(third_result["outcome"], "FEE_PUBLISH_REFUSED");
    assert_eq!(third_result["faults"][0]["fee_id"], fee_id.as_str());
    assert_eq!(third_result["faults"][0]["reason"], "CURRENCY_MISMATCH");
    assert!(store_fees(&config_trees, third).await.is_none());
}

#[tokio::test]
async fn a_rule_is_refused_field_by_field() {
    let (router, _, _, _) = fees_app();
    let cookie = admin_cookie(&router).await;
    let tenant_id = tenant_scope_id();
    let unknown_item = serde_json::json!({
        "code": "PACKAGING",
        "display_name": "Packaging",
        "kind": "FEE_KIND_AMOUNT_PER_UNIT",
        "amount": { "currency_code": "VND", "amount_minor": 3_000 },
        "item_scope": "FEE_ITEMS_INCLUDE",
        "menu_item_ids": [Ulid::from_u128(0x7C99).to_string()],
    });
    for (scope, rule, field, reason) in [
        (
            "FEE_SCOPE_TENANT",
            percent_fee("SERVICE", 150),
            "rule.rate",
            "OUT_OF_RANGE",
        ),
        (
            "FEE_SCOPE_TENANT",
            serde_json::json!({
                "code": "SERVICE",
                "display_name": "Service charge",
                "kind": "FEE_KIND_PERCENT",
            }),
            "rule.rate",
            "REQUIRED",
        ),
        (
            "FEE_SCOPE_TENANT",
            serde_json::json!({
                "code": "COVER",
                "display_name": "Cover charge",
                "kind": "FEE_KIND_PER_GUEST",
            }),
            "rule.kind",
            "INVALID_ENUM_VALUE",
        ),
        (
            "FEE_SCOPE_TENANT",
            serde_json::json!({ "code": " ", "display_name": "Service charge" }),
            "rule.code",
            "REQUIRED",
        ),
        (
            "FEE_SCOPE_TENANT",
            unknown_item,
            "rule.menu_item_ids",
            "UNKNOWN_REFERENCE",
        ),
        (
            "FEE_SCOPE_TENANT",
            with_fee_id(&percent_fee("SERVICE", 5), &Ulid::from_u128(1).to_string()),
            "rule.fee_id",
            "INVALID_VALUE",
        ),
        (
            "FEE_SCOPE_STORE_GROUP",
            percent_fee("SERVICE", 5),
            "scope",
            "INVALID_ENUM_VALUE",
        ),
    ] {
        let refused = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/fees",
                &fee_body(scope, &tenant_id, &rule),
                &cookie,
            ))
            .await
            .expect("route the write");
        assert_eq!(
            refused.status(),
            StatusCode::BAD_REQUEST,
            "{field} {reason}"
        );
        let body = json_body(refused).await;
        assert_eq!(body["error"]["details"][0]["field"], field, "{body}");
        assert_eq!(body["error"]["details"][0]["reason"], reason, "{body}");
    }
}

#[tokio::test]
async fn a_category_is_compiled_into_its_items_and_a_list_must_name_one_the_menu_has() {
    let (router, config_trees, _, _) = fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, ..] = fees_stores();

    let packaging = serde_json::json!({
        "code": "PACKAGING",
        "display_name": "Packaging",
        "kind": "FEE_KIND_AMOUNT_PER_UNIT",
        "amount": { "currency_code": "VND", "amount_minor": 3_000 },
        "channels": ["SALES_CHANNEL_TAKEAWAY", "SALES_CHANNEL_DINE_IN"],
        "item_scope": "FEE_ITEMS_INCLUDE",
        "item_category_ids": [fee_category(1).to_string()],
    });
    let written = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body("FEE_SCOPE_STORE", &first.to_string(), &packaging),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::CREATED);
    let fees = store_fees(&config_trees, first).await.expect("a fees node");
    let [fee] = fees.fees.as_slice() else {
        panic!("one fee: {fees:?}");
    };
    assert_eq!(
        fee.menu_item_ids,
        vec![fee_item(1), fee_item(2)],
        "the category's two items, compiled when the store was published"
    );

    // A second fee under the code the store already runs would be charged as a second fee.
    let clash = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body("FEE_SCOPE_TENANT", &tenant_scope_id(), &{
                let mut rule = percent_fee("PACKAGING", 5);
                if let Some(fields) = rule.as_object_mut() {
                    fields.insert("display_name".to_owned(), serde_json::json!("Packaging"));
                }
                rule
            }),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(clash.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(clash).await;
    assert_eq!(body["error"]["details"][0]["field"], "rule.code");
    assert_eq!(body["error"]["details"][0]["reason"], "ALREADY_EXISTS");

    // An include list of an item no store it reaches has on its menu.
    let nothing_on_the_menu = serde_json::json!({
        "code": "BOX",
        "display_name": "Box",
        "kind": "FEE_KIND_AMOUNT_PER_UNIT",
        "amount": { "currency_code": "VND", "amount_minor": 2_000 },
        "item_scope": "FEE_ITEMS_INCLUDE",
        "menu_item_ids": [fee_item(2).to_string()],
    });
    let refused = router
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body("FEE_SCOPE_STORE", &first.to_string(), &nothing_on_the_menu),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
    let body = json_body(refused).await;
    assert_eq!(body["error"]["details"][0]["field"], "rule.menu_item_ids");
    assert_eq!(body["error"]["details"][0]["reason"], "NOT_ON_MENU");
}

#[tokio::test]
async fn the_fee_routes_go_by_role_and_the_trail_keeps_ids_and_counts() {
    let (router, _, audit, admin) = fees_app();
    let ops = role_session_cookie(&admin, AdminRole::Ops, "ops-token").await;
    let viewer = role_session_cookie(&admin, AdminRole::Viewer, "viewer-token").await;
    let list = format!("/admin/fees?tenant_id={}", tenant().as_ulid());

    // A rule's rate and amount are prices: neither Ops nor a Viewer reads them.
    for cookie in [&ops, &viewer] {
        let read = router
            .clone()
            .oneshot(get_with_cookie(&list, cookie))
            .await
            .expect("route the read");
        assert_eq!(read.status(), StatusCode::FORBIDDEN);
    }
    // A write publishes, which Ops may do and a Viewer may not.
    let body = fee_body(
        "FEE_SCOPE_TENANT",
        &tenant_scope_id(),
        &percent_fee("SERVICE", 5),
    );
    let by_viewer = router
        .clone()
        .oneshot(post_with_cookie("/admin/fees", &body, &viewer))
        .await
        .expect("route the write");
    assert_eq!(by_viewer.status(), StatusCode::FORBIDDEN);
    let by_ops = router
        .clone()
        .oneshot(post_with_cookie("/admin/fees", &body, &ops))
        .await
        .expect("route the write");
    assert_eq!(by_ops.status(), StatusCode::CREATED);
    let fee_id = json_body(by_ops).await["fee_id"]
        .as_str()
        .expect("a fee id")
        .to_owned();

    let entries = audit.entries.lock().expect("lock").clone();
    let [entry] = entries.as_slice() else {
        panic!("one audit entry: {entries:?}");
    };
    assert_eq!(entry.action, "fee.create");
    assert_eq!(entry.entity_type, "fee_rule");
    assert_eq!(
        entry.entity_id,
        format!("{fee_id} FEE_SCOPE_TENANT {}", tenant().as_ulid())
    );
    assert_eq!(
        entry.after,
        Some(serde_json::json!({
            "stores": 3, "applied": 3, "unchanged": 0, "refused": 0, "failed": 0,
        }))
    );
    let recorded = serde_json::to_string(&entry.after).expect("encode");
    assert!(
        !recorded.contains("SERVICE") && !recorded.contains("Service charge"),
        "ids and counts only: {recorded}"
    );
}

#[tokio::test]
#[expect(
    clippy::too_many_lines,
    reason = "one sample bill read four ways against the same store — with the rule, without it, \
              with a line its menu does not sell, and at a store with nothing published — and by \
              a role that may not read prices; split, each would rebuild the same fixture"
)]
async fn a_sample_bill_shows_a_rule_before_it_is_written_and_writes_nothing() {
    let (router, config_trees, audit, admin) = fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, third] = fees_stores();
    let preview = |store_id: StoreId, rules: &serde_json::Value, lines: &serde_json::Value| {
        serde_json::json!({
            "tenant_id": tenant_scope_id(),
            "store_id": store_id.to_string(),
            "rules": rules,
            "lines": lines,
        })
    };
    let sample = serde_json::json!([
        { "menu_item_id": fee_item(1).to_string(), "quantity": 2 },
        { "menu_item_id": fee_item(3).to_string(), "quantity": 1 },
    ]);
    let service = serde_json::json!([{
        "scope": "FEE_SCOPE_TENANT",
        "scope_id": tenant_scope_id(),
        "rule": percent_fee("SERVICE", 5),
    }]);

    let previewed = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees/preview",
            &preview(first, &service, &sample),
            &cookie,
        ))
        .await
        .expect("route the preview");
    assert_eq!(previewed.status(), StatusCode::OK);
    let bill = json_body(previewed).await;
    let minor = |value: &serde_json::Value| value["amount_minor"].as_i64();
    assert_eq!(minor(&bill["lines"][0]["line_total"]), Some(190_000));
    assert_eq!(bill["lines"][0]["quantity"], 2);
    assert_eq!(minor(&bill["subtotal"]), Some(220_000));
    assert_eq!(bill["fee_lines"][0]["code"], "SERVICE");
    assert_eq!(minor(&bill["fee_lines"][0]["amount"]), Some(11_000));
    assert_eq!(minor(&bill["fee_lines"][0]["tax"]), Some(880));
    assert_eq!(bill["tax_lines"][0]["rate_basis_points"], 800);
    assert_eq!(minor(&bill["tax_total"]), Some(18_480));
    assert_eq!(minor(&bill["total_due"]), Some(249_480));

    // A preview writes nothing and publishes nothing.
    assert!(store_fees(&config_trees, first).await.is_none());
    let listed = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!("/admin/fees?tenant_id={}", tenant().as_ulid()),
                &cookie,
            ))
            .await
            .expect("route the read"),
    )
    .await;
    assert_eq!(listed["rules"], serde_json::json!([]));
    assert!(audit.entries.lock().expect("lock").is_empty());

    // Without the rule, the same lines carry no fee.
    let plain = json_body(
        router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/fees/preview",
                &preview(first, &serde_json::json!([]), &sample),
                &cookie,
            ))
            .await
            .expect("route the preview"),
    )
    .await;
    assert_eq!(plain["fee_lines"], serde_json::json!([]));
    assert_eq!(minor(&plain["total_due"]), Some(237_600));

    // A line the store's menu does not sell, and a store with nothing published to price from.
    for (store_id, lines, field, reason) in [
        (
            first,
            serde_json::json!([{ "menu_item_id": fee_item(2).to_string(), "quantity": 1 }]),
            "lines",
            "NOT_ON_MENU",
        ),
        (third, sample.clone(), "store_id", "NOT_PUBLISHED"),
    ] {
        let refused = router
            .clone()
            .oneshot(post_with_cookie(
                "/admin/fees/preview",
                &preview(store_id, &service, &lines),
                &cookie,
            ))
            .await
            .expect("route the preview");
        assert_eq!(
            refused.status(),
            StatusCode::UNPROCESSABLE_ENTITY,
            "{reason}"
        );
        let body = json_body(refused).await;
        assert_eq!(body["error"]["details"][0]["field"], field);
        assert_eq!(body["error"]["details"][0]["reason"], reason);
    }

    // A preview shows prices, so it needs what reading a rule needs.
    let ops = role_session_cookie(&admin, AdminRole::Ops, "ops-token").await;
    let by_ops = router
        .oneshot(post_with_cookie(
            "/admin/fees/preview",
            &preview(first, &service, &sample),
            &ops,
        ))
        .await
        .expect("route the preview");
    assert_eq!(by_ops.status(), StatusCode::FORBIDDEN);
}

/// The fee routes, the settings routes and the locale publish over one config tree, as the cloud
/// serves them, so what a setting writes is what a sample bill reads.
fn fees_and_settings_app() -> (axum::Router, FakeConfigTrees) {
    let admin = provisioned_admin();
    let config_trees = FakeConfigTrees::default();
    let registry = fees_registry();
    seed_fee_stores(&config_trees);
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
        FakeWebhooks::default(),
    );
    let router = http::router(app)
        .merge(http::fees_router(
            InMemoryFeeRules::new(),
            registry.clone(),
            fee_catalog(),
            config_trees.clone(),
            admin.clone(),
            clock(),
            Arc::new(NoopAuditRecorder),
        ))
        .merge(http::settings_router(
            FakeSettings::default(),
            registry,
            FakeStoreGroups::default(),
            config_trees.clone(),
            admin.clone(),
            clock(),
            Arc::new(NoopAuditRecorder),
        ))
        .merge(http::config_locale_router(
            &pos_cloud::countries::registry(),
            config_trees.clone(),
            admin,
            clock(),
            Arc::new(NoopAuditRecorder),
        ));
    (router, config_trees)
}

/// The fee, the tax and the total of a sample bill of one Margherita at a 5.05 % fee.
async fn sampled(router: &axum::Router, cookie: &str, store_id: StoreId) -> [Option<i64>; 3] {
    let body = serde_json::json!({
        "tenant_id": tenant_scope_id(),
        "store_id": store_id.to_string(),
        "rules": [{
            "scope": "FEE_SCOPE_TENANT",
            "scope_id": tenant_scope_id(),
            "rule": {
                "code": "SERVICE",
                "display_name": "Service charge",
                "kind": "FEE_KIND_PERCENT",
                "rate": { "numerator": 505, "denominator": 10_000 },
            },
        }],
        "lines": [{ "menu_item_id": fee_item(1).to_string(), "quantity": 1 }],
    });
    let previewed = router
        .clone()
        .oneshot(post_with_cookie("/admin/fees/preview", &body, cookie))
        .await
        .expect("route the preview");
    assert_eq!(previewed.status(), StatusCode::OK);
    let bill = json_body(previewed).await;
    [
        bill["fee_lines"][0]["amount"]["amount_minor"].as_i64(),
        bill["tax_total"]["amount_minor"].as_i64(),
        bill["total_due"]["amount_minor"].as_i64(),
    ]
}

/// A store's tax rounding (ADR-0160) is a setting on its `locale` node, written on its Tenant
/// layer, while a locale publish writes the country's fields on its Store layer. The node the
/// store receives carries both, whichever was written last, and a sample bill at the store rounds
/// its fee and its tax as the store's edge will: 5.05 % of 95,000 is 4,797.5, and 8 % of the line
/// and the fee is 7,983.84 at half-up or 7,983.76 rounded down.
#[tokio::test]
async fn a_store_set_to_round_tax_down_keeps_its_country_and_is_shown_the_tax_it_will_charge() {
    let (router, config_trees) = fees_and_settings_app();
    let cookie = admin_cookie(&router).await;
    let [first, _, _] = fees_stores();
    assert_eq!(
        sampled(&router, &cookie, first).await,
        [Some(4_798), Some(7_984), Some(107_782)],
        "half-up while the store sets nothing"
    );

    let written = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/settings",
            &serde_json::json!({
                "tenant_id": tenant_scope_id(),
                "setting_key": "locale.tax_rounding",
                "scope": "SETTING_SCOPE_STORE",
                "scope_id": first.to_string(),
                "value": "TAX_ROUNDING_DOWN",
            }),
            &cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::OK);
    let tree = config_trees
        .load(tenant(), first)
        .await
        .expect("load")
        .expect("a tree");
    assert_eq!(
        tree.record.layers[0]["locale"],
        serde_json::json!({ "tax_rounding": "TAX_ROUNDING_DOWN" }),
        "the setting alone, on the Tenant layer"
    );
    assert_eq!(
        tree.record.layers[2]["locale"],
        serde_json::json!({ "currency_code": "VND" }),
        "the store's own locale is not touched"
    );
    let down = [Some(4_797), Some(7_983), Some(107_780)];
    assert_eq!(sampled(&router, &cookie, first).await, down);

    // The store's locale published again, as when its country is set: the setting stays.
    let published = router
        .clone()
        .oneshot(put_with_cookie(
            "/admin/config/locale",
            &serde_json::json!({
                "tenant_id": tenant_scope_id(),
                "store_id": first.to_string(),
                "country_code": "VN",
                "currency_code": "VND",
                "timezone": "Asia/Ho_Chi_Minh",
                "cutoff_hour": 4,
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
    let effective = json_body(
        router
            .clone()
            .oneshot(get_with_cookie(
                &format!(
                    "/admin/stores/{}/config?tenant_id={}",
                    first.as_ulid(),
                    tenant().as_ulid()
                ),
                &cookie,
            ))
            .await
            .expect("route the read"),
    )
    .await;
    assert_eq!(effective["locale"]["tax_rounding"], "TAX_ROUNDING_DOWN");
    assert_eq!(effective["locale"]["country_code"], "VN");
    assert_eq!(effective["locale"]["timezone"], "Asia/Ho_Chi_Minh");
    assert_eq!(sampled(&router, &cookie, first).await, down);
}

// --- A menu publish brings the store's fees along (ADR-0159) ------------------------------------

/// Places item `n` on `menu_id` at 95,000 đồng on dine-in.
fn place_fee_item(catalog: &FakeCatalog, menu_id: MenuId, n: u128) {
    catalog
        .placements
        .lock()
        .expect("lock")
        .push(Versioned::new(
            MenuPlacement {
                tenant_id: tenant(),
                menu_id,
                menu_item_id: fee_item(n),
                menu_section_id: None,
                prices: vec![ChannelPrice {
                    sales_channel: Open::from_known(SalesChannel::DineIn),
                    unit_price: pos_proto::money::Money::new(
                        pos_proto::money::CurrencyCode::VND,
                        95_000,
                    ),
                }],
                available: true,
            },
            Version::new("1"),
        ));
}

/// The menu the fee tests publish: items 1 and 3, on dine-in.
fn seed_fee_menu(catalog: &FakeCatalog) -> MenuId {
    let menu_id = MenuId::new(Ulid::from_u128(0x7F01));
    catalog.menus.lock().expect("lock").push(Versioned::new(
        Menu {
            menu_id,
            tenant_id: tenant(),
            name: "Standard".to_owned(),
            parent_menu_id: None,
            status: EntityStatus::Active,
        },
        Version::new("1"),
    ));
    for n in [1, 3] {
        place_fee_item(catalog, menu_id, n);
    }
    menu_id
}

/// A new pizza: item `n`, put in the fee category and on the menu, as an operator adds one before
/// publishing the menu.
fn add_pizza(catalog: &FakeCatalog, menu_id: MenuId, n: u128) {
    catalog.items.lock().expect("lock").push(Versioned::new(
        CatalogItem {
            menu_item_id: fee_item(n),
            tenant_id: tenant(),
            name: format!("Item {n}"),
            name_translations: BTreeMap::new(),
            tax_class_id: fee_tax_class(1),
            item_category_id: Some(fee_category(1)),
            item_subcategory_id: None,
            course_id: None,
            image_ref: None,
            status: EntityStatus::Active,
        },
        Version::new("1"),
    ));
    place_fee_item(catalog, menu_id, n);
}

/// A packaging fee on every pizza, 3,000 đồng a unit, taxed at the pizzas' own class: a rule that
/// names the category, not its items.
fn pizza_packaging() -> serde_json::Value {
    serde_json::json!({
        "code": "PACKAGING",
        "display_name": "Packaging",
        "kind": "FEE_KIND_AMOUNT_PER_UNIT",
        "amount": { "currency_code": "VND", "amount_minor": 3_000 },
        "item_scope": "FEE_ITEMS_INCLUDE",
        "item_category_ids": [fee_category(1).to_string()],
        "tax": "FEE_TAX_TAX_CLASS",
        "tax_class_id": fee_tax_class(1).to_string(),
    })
}

/// A tax table that rates the second class only, so a fee taxed at the first fails every bill.
fn second_class_only() -> serde_json::Value {
    let table = pos_proto::locale::TaxRateTable::new()
        .with(
            fee_tax_class(2),
            SalesChannel::DineIn,
            TaxRate::from_basis_points(800),
        )
        .with(
            fee_tax_class(2),
            SalesChannel::Takeaway,
            TaxRate::from_basis_points(800),
        );
    serde_json::to_value(&table).expect("encode the tax table")
}

/// The menu publish, the fee routes and the generic preview over one catalog, rule store, registry
/// and config-tree fake, as `main.rs` merges them, with the fee tests' stores seeded and a menu of
/// items 1 and 3 to publish.
fn menu_fees_app() -> (axum::Router, FakeConfigTrees, FakeCatalog, MenuId) {
    let admin = provisioned_admin();
    let config_trees = FakeConfigTrees::default();
    let registry = fees_registry();
    let catalog = fee_catalog();
    let rules = InMemoryFeeRules::new();
    seed_fee_stores(&config_trees);
    let menu_id = seed_fee_menu(&catalog);
    let app = app_all(
        Cloud::new(FakeStore::new()),
        FakeRollups::default(),
        FakeKeys::default(),
        admin.clone(),
        config_trees.clone(),
        FakeWebhooks::default(),
    );
    let router = http::router(app)
        .merge(http::fees_router(
            rules.clone(),
            registry.clone(),
            catalog.clone(),
            config_trees.clone(),
            admin.clone(),
            clock(),
            Arc::new(NoopAuditRecorder),
        ))
        .merge(http::config_preview_router(
            config_trees.clone(),
            http::batch_nodes(
                catalog.clone(),
                FakeTaxRates::default(),
                FakeCampaigns,
                FakeInventory::default(),
                FakeReasonCodes::default(),
                FakePeople::default(),
                FakeFloor::default(),
                rules.clone(),
                registry.clone(),
            ),
            admin.clone(),
            clock(),
        ))
        .merge(http::catalog_publish_router(
            catalog.clone(),
            rules,
            registry,
            config_trees.clone(),
            admin,
            clock(),
            Arc::new(NoopAuditRecorder),
        ));
    (router, config_trees, catalog, menu_id)
}

/// Writes [`pizza_packaging`] for the brand's first store, and answers its fee id.
async fn write_pizza_packaging(router: &axum::Router, cookie: &str) -> String {
    let [first, ..] = fees_stores();
    let written = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees",
            &fee_body("FEE_SCOPE_STORE", &first.to_string(), &pizza_packaging()),
            cookie,
        ))
        .await
        .expect("route the write");
    assert_eq!(written.status(), StatusCode::CREATED);
    json_body(written).await["fee_id"]
        .as_str()
        .expect("a fee id")
        .to_owned()
}

/// Publishes `menu_id` to `store`, and answers the body.
async fn publish_fee_menu(
    router: &axum::Router,
    cookie: &str,
    store: StoreId,
    menu_id: MenuId,
) -> serde_json::Value {
    let published = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/catalog/publish",
            &serde_json::json!({
                "tenant_id": tenant_scope_id(),
                "store_id": store.to_string(),
                "menu_id": menu_id.as_ulid().to_string(),
            }),
            cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
    json_body(published).await
}

/// What publishing `menu_id` to `store` would change, as the generic preview says it.
async fn preview_fee_menu(
    router: &axum::Router,
    cookie: &str,
    store: StoreId,
    menu_id: MenuId,
) -> serde_json::Value {
    let previewed = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/config/preview",
            &serde_json::json!({
                "tenant_id": tenant_scope_id(),
                "store_id": store.to_string(),
                "node": "menu",
                "arguments": { "menu_id": menu_id.as_ulid().to_string() },
            }),
            cookie,
        ))
        .await
        .expect("route the preview");
    assert_eq!(previewed.status(), StatusCode::OK);
    json_body(previewed).await
}

/// A store's tree as the fake holds it.
async fn fee_store_tree(config_trees: &FakeConfigTrees, store: StoreId) -> ConfigTreeState {
    config_trees
        .load(tenant(), store)
        .await
        .expect("load")
        .expect("a tree")
        .record
}

/// The nodes the store's latest version wrote.
fn last_written(tree: &ConfigTreeState) -> Vec<String> {
    tree.history.last().expect("a version").nodes.clone()
}

/// A rule naming a category is compiled into the items it holds, so the publish that adds a pizza
/// to the category, the menu's, is the one that brings the store's fees along: in the menu's own
/// version, with no fee publish in between, and the store charges the fee on the new pizza from
/// that version on. The preview says so beforehand, because it composes as the publish does.
#[tokio::test]
async fn a_menu_publish_charges_a_category_fee_on_the_items_it_adds_in_the_same_version() {
    let (router, config_trees, catalog, menu_id) = menu_fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, ..] = fees_stores();
    write_pizza_packaging(&router, &cookie).await;
    add_pizza(&catalog, menu_id, 4);

    let previewed = preview_fee_menu(&router, &cookie, first, menu_id).await;
    assert!(previewed["diff"]["fees"].is_object(), "{previewed}");

    let body = publish_fee_menu(&router, &cookie, first, menu_id).await;
    let version = body["config_version_id"].as_str().expect("a version");
    assert_eq!(body["fees"]["outcome"], "FEE_PUBLISH_APPLIED", "{body}");
    assert_eq!(
        body["fees"]["config_version_id"], version,
        "the menu's own version"
    );
    let fees = store_fees(&config_trees, first).await.expect("a fees node");
    let [fee] = fees.fees.as_slice() else {
        panic!("one fee: {fees:?}");
    };
    assert_eq!(
        fee.menu_item_ids,
        vec![fee_item(1), fee_item(2), fee_item(4)]
    );
    let tree = fee_store_tree(&config_trees, first).await;
    assert_eq!(last_written(&tree), ["menu", "layout", "fees"]);
    assert_eq!(
        tree.history.last().map(|written| written.id.to_string()),
        Some(version.to_owned())
    );

    // The store bills two of the new pizza with two units of packaging.
    let bill = sample_bill(
        &StoreFacts::from_document(&tree.effective()),
        SalesChannel::DineIn,
        &[SampleLine {
            menu_item_id: fee_item(4),
            quantity: pos_proto::quantity::Quantity::from_whole(2).expect("a quantity"),
        }],
        &fees,
    )
    .expect("a bill");
    assert_eq!(
        bill.totals.service_charge,
        pos_proto::money::Money::new(pos_proto::money::CurrencyCode::VND, 6_000)
    );
    let unchanged = preview_fee_menu(&router, &cookie, first, menu_id).await;
    assert_eq!(unchanged["unchanged"], true, "{unchanged}");
}

/// A menu publish to a store whose fees are what its rules resolve to writes no `fees` key: the
/// version names the menu and its layout only, and the answer says the fees are unchanged.
#[tokio::test]
async fn a_menu_publish_writes_no_fees_where_they_are_unchanged() {
    let (router, config_trees, _, menu_id) = menu_fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, ..] = fees_stores();
    write_pizza_packaging(&router, &cookie).await;
    let held = fee_store_tree(&config_trees, first).await.layers[2]["fees"].clone();

    let body = publish_fee_menu(&router, &cookie, first, menu_id).await;
    assert_eq!(
        body["fees"],
        serde_json::json!({ "store_id": first.to_string(), "outcome": "FEE_PUBLISH_UNCHANGED" })
    );
    let tree = fee_store_tree(&config_trees, first).await;
    assert_eq!(last_written(&tree), ["menu", "layout"]);
    assert_eq!(tree.layers[2]["fees"], held);
}

/// A store that cannot apply one of its rules still gets its menu, and the answer says which rule
/// and why, in the fee publish's own tokens; the store keeps the fees it has. The fees are
/// composed on the tree the menu is written over: a tax table that no longer rates the pizzas'
/// class, landing between the publish's read and its write, is the one the rule is checked
/// against.
#[tokio::test]
async fn a_menu_publish_still_publishes_the_menu_where_the_store_cannot_apply_a_fee() {
    let (router, config_trees, catalog, menu_id) = menu_fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, ..] = fees_stores();
    let fee_id = write_pizza_packaging(&router, &cookie).await;
    let held = fee_store_tree(&config_trees, first).await.layers[2]["fees"].clone();
    add_pizza(&catalog, menu_id, 4);
    *config_trees.interpose.lock().expect("lock") = Some(("tax".to_owned(), second_class_only()));

    let body = publish_fee_menu(&router, &cookie, first, menu_id).await;
    assert_eq!(body["fees"]["outcome"], "FEE_PUBLISH_REFUSED", "{body}");
    assert_eq!(
        body["fees"]["faults"],
        serde_json::json!([{ "fee_id": fee_id, "reason": "TAX_RATE_NOT_CONFIGURED" }])
    );
    let tree = fee_store_tree(&config_trees, first).await;
    assert_eq!(last_written(&tree), ["menu", "layout"]);
    assert_eq!(
        tree.layers[2]["tax"],
        second_class_only(),
        "written over, not under"
    );
    assert_eq!(
        tree.layers[2]["fees"], held,
        "the store keeps the fees it had"
    );
    let menu: pos_proto::MenuBook =
        serde_json::from_str(&tree.layers[2]["menu"].to_string()).expect("the edge reads it");
    assert!(
        menu.catalog_for(SalesChannel::DineIn)
            .get(fee_item(4))
            .is_some(),
        "the menu went out with the new pizza"
    );
}

/// The fee publish checks a store's rules against the tree it writes over (the race found in 2b):
/// a tax table that no longer rates the class a rule is taxed at, published between the fee
/// publish's read and its write, is the table the rule is checked against. The store is refused
/// and keeps the fees it had, rather than being sent a rule every bill it applies to would fail.
#[tokio::test]
async fn a_fee_publish_checks_the_rules_against_the_tree_it_writes_over() {
    let (router, config_trees, catalog, menu_id) = menu_fees_app();
    let cookie = admin_cookie(&router).await;
    let [first, ..] = fees_stores();
    let fee_id = write_pizza_packaging(&router, &cookie).await;
    let held = fee_store_tree(&config_trees, first).await.layers[2]["fees"].clone();
    // A pizza added to the category, so the publish has something to send.
    add_pizza(&catalog, menu_id, 4);
    *config_trees.interpose.lock().expect("lock") = Some(("tax".to_owned(), second_class_only()));

    let published = router
        .clone()
        .oneshot(post_with_cookie(
            "/admin/fees/publish",
            &serde_json::json!({
                "tenant_id": tenant_scope_id(),
                "store_id": first.to_string(),
            }),
            &cookie,
        ))
        .await
        .expect("route the publish");
    assert_eq!(published.status(), StatusCode::OK);
    let body = json_body(published).await;
    assert_eq!(
        outcomes(&body),
        vec![(first.to_string(), "FEE_PUBLISH_REFUSED".to_owned())],
        "{body}"
    );
    assert_eq!(
        body["stores"][0]["faults"],
        serde_json::json!([{ "fee_id": fee_id, "reason": "TAX_RATE_NOT_CONFIGURED" }])
    );
    let tree = fee_store_tree(&config_trees, first).await;
    assert_eq!(tree.layers[2]["tax"], second_class_only());
    assert_eq!(
        tree.layers[2]["fees"], held,
        "the store keeps the fees it had"
    );
}

/// A menu published to a store group brings each member's fees along in the member's own version,
/// composed on its own tree, and a member that cannot apply one of its rules still gets its menu,
/// its report saying why in the fee publish's tokens.
#[tokio::test]
async fn a_menu_batch_brings_each_members_fees_along_and_says_which_it_left_behind() {
    let [first, second, _] = fees_stores();
    let config_trees = FakeConfigTrees::default();
    seed_fee_stores(&config_trees);
    let mut tree = fee_store_tree(&config_trees, first).await;
    tree.layers[2]["tax"] = second_class_only();
    config_trees.seed_store_layer(tenant(), second, tree.layers[2].clone());
    let catalog = fee_catalog();
    let menu_id = seed_fee_menu(&catalog);

    // The brand's packaging rule, as a write the second store came to refuse left it.
    let fee_id = FeeId::new(Ulid::from_u128(0x7F11));
    let mut authored = pizza_packaging();
    authored["fee_id"] = serde_json::json!(fee_id.to_string());
    let (rule, item_category_ids) =
        pos_cloud::fees::rule_from_authored(&authored.to_string()).expect("a rule");
    let rules = InMemoryFeeRules::new();
    rules
        .put(
            tenant(),
            &FeeRule {
                scope: FeeScope::Brand,
                scope_id: fees_brand().to_string(),
                rule,
                item_category_ids,
                update_time: Timestamp::from_milliseconds_since_epoch(NOW_MS).expect("a time"),
                updated_by: "admin-1".to_owned(),
            },
        )
        .await
        .expect("put the rule");

    let group_id = StoreGroupId::new(Ulid::from_u128(0x7F21));
    let groups = FakeStoreGroups::default();
    groups.seed(
        StoreGroup {
            group_id,
            tenant_id: tenant(),
            name: "The brand".to_owned(),
            status: EntityStatus::Active,
        },
        &[first, second],
    );
    let router = store_group_app_with_fees(
        provisioned_admin(),
        groups,
        fees_registry(),
        config_trees.clone(),
        catalog,
        rules,
    );
    let cookie = admin_cookie(&router).await;
    let published = router
        .oneshot(post_with_cookie(
            &format!("/admin/store-groups/{}/publish", group_id.as_ulid()),
            &serde_json::json!({
                "tenant_id": tenant_scope_id(),
                "node": "menu",
                "arguments": { "menu_id": menu_id.as_ulid().to_string() },
            }),
            &cookie,
        ))
        .await
        .expect("route the batch publish");
    assert_eq!(published.status(), StatusCode::OK);
    let report = json_body(published).await;
    assert_eq!(report["applied"], 2, "{report}");
    let row = |store: StoreId| {
        report["results"]
            .as_array()
            .expect("results")
            .iter()
            .find(|row| row["store_id"] == store.to_string())
            .cloned()
            .expect("a row")
    };

    let took_them = row(first);
    assert!(took_them.get("detail").is_none(), "{took_them}");
    let tree = fee_store_tree(&config_trees, first).await;
    assert_eq!(last_written(&tree), ["menu", "layout", "fees"]);
    assert_eq!(
        took_them["config_version_id"],
        tree.history.last().expect("a version").id.to_string()
    );
    let fees = store_fees(&config_trees, first).await.expect("a fees node");
    assert_eq!(
        fees.fees.first().map(|fee| fee.menu_item_ids.clone()),
        Some(vec![fee_item(1), fee_item(2)])
    );

    let left_them = row(second);
    let detail = left_them["detail"].as_str().expect("a detail");
    assert!(
        detail.contains("FEE_PUBLISH_REFUSED")
            && detail.contains(&format!("{fee_id} TAX_RATE_NOT_CONFIGURED")),
        "{detail}"
    );
    let tree = fee_store_tree(&config_trees, second).await;
    assert_eq!(last_written(&tree), ["menu", "layout"]);
    assert!(
        tree.layers[2].get("fees").is_none(),
        "nothing it cannot apply"
    );
}

// --- The people republisher (ADR-0158): a grant migration's stores, published again by the cloud --

/// The in-memory queue holds the seam's rules, the ones `PostgresPeopleRepublishes` is held to in
/// `tests/people_republish_store_postgres.rs`: one row per store, read in tenant then store order
/// past the last row read, and cleared only while it carries the time it was read with.
#[tokio::test]
async fn the_in_memory_people_republish_queue_holds_the_contract() {
    people_republish_contract::holds(&InMemoryPeopleRepublishes::new(), 0).await;
}

/// The reason migration 0083 queues every store under.
const REPUBLISH_REASON: &str = "0083_people_republishes";

/// A second store of the tenant.
fn second_store() -> StoreId {
    StoreId::new(Ulid::from_u128(0x0ADB))
}

/// Writes a store's tree as a publish would have left it, its four layers as given and no history.
async fn seed_tree(config: &FakeConfigTrees, store: StoreId, layers: [serde_json::Value; 4]) {
    let state = ConfigTreeState {
        layers,
        history: Vec::new(),
        k: 8,
    };
    let saved = config
        .save(tenant(), store, &state, None)
        .await
        .expect("seed the tree");
    assert!(matches!(saved, UpdateOutcome::Updated(_)), "{saved:?}");
}

/// A tree whose Store layer is `store_layer` and whose other layers are empty.
fn store_layer_only(store_layer: serde_json::Value) -> [serde_json::Value; 4] {
    [
        serde_json::json!({}),
        serde_json::json!({}),
        store_layer,
        serde_json::json!({}),
    ]
}

/// A store's `permissions` node from before a grant: nobody on its roster.
fn people_before_the_grant(store: StoreId) -> serde_json::Value {
    serde_json::json!({ "store_id": store.to_string(), "staff": [] })
}

/// Queues a store as migration 0083 queues it, at `ms`.
async fn queue_store(queue: &InMemoryPeopleRepublishes, store: StoreId, ms: i64) {
    queue
        .enqueue(&PeopleRepublish {
            tenant_id: tenant(),
            store_id: store,
            reason: REPUBLISH_REASON.to_owned(),
            enqueued_time: Timestamp::from_milliseconds_since_epoch(ms).expect("a valid time"),
        })
        .await
        .expect("queue the store");
}

/// Every store still queued, in order.
async fn still_queued(queue: &InMemoryPeopleRepublishes) -> Vec<StoreId> {
    queue
        .pending(None, 1_000)
        .await
        .expect("read the queue")
        .into_iter()
        .map(|row| row.store_id)
        .collect()
}

/// The `permissions.publish` entries the trail holds, oldest first.
async fn people_publishes(audit: &FakeAudit) -> Vec<AuditEntry> {
    let mut entries: Vec<AuditEntry> = audit
        .list(None, 1_000)
        .await
        .expect("read the trail")
        .into_iter()
        .filter(|entry| entry.action == "permissions.publish")
        .collect();
    entries.reverse();
    entries
}

/// Drains the queue once, as the republisher's loop does, recording into `audit`.
async fn drain_once(
    queue: &InMemoryPeopleRepublishes,
    people: &FakePeople,
    config: &FakeConfigTrees,
    audit: &FakeAudit,
) -> DrainTally {
    let recorder: Arc<dyn AuditRecorder> = Arc::new(AuditSink::new(audit.clone()));
    people_republish::drain(queue, people, config, &recorder, &clock())
        .await
        .expect("drain the queue")
}

#[tokio::test]
async fn a_queued_store_is_published_again_under_the_system_actor_and_leaves_the_queue() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let queue = InMemoryPeopleRepublishes::new();
    let store = store_id();
    seed_a_cashier(&people, store).await;
    seed_tree(
        &config,
        store,
        store_layer_only(serde_json::json!({ "permissions": people_before_the_grant(store) })),
    )
    .await;
    queue_store(&queue, store, NOW_MS).await;

    let tally = drain_once(&queue, &people, &config, &audit).await;

    assert_eq!(
        tally,
        DrainTally {
            published: 1,
            ..DrainTally::default()
        }
    );
    let staff = staff_at(&config, store).await;
    assert_eq!(staff.len(), 1, "{staff:?}");
    assert_eq!(
        staff[0]["permissions"],
        serde_json::json!(["billing.discount.apply"]),
        "the node carries what the person's role grants now"
    );
    assert_eq!(versions_at(&config, store).await, 1, "one new version");
    assert!(
        still_queued(&queue).await.is_empty(),
        "a store published again leaves the queue"
    );

    // Recorded as the button's publish is, under the system actor, with the queue's reason.
    let entries = people_publishes(&audit).await;
    assert_eq!(entries.len(), 1);
    let entry = &entries[0];
    assert_eq!(entry.actor.admin_id, SYSTEM_ACTOR_ID);
    assert_eq!(entry.actor.email, SYSTEM_ACTOR_EMAIL);
    assert_eq!(entry.actor.role, AdminRole::Ops);
    assert_eq!(entry.tenant_id, Some(tenant()));
    assert_eq!(
        (entry.entity_type.as_str(), entry.entity_id.as_str()),
        ("store", store.to_string().as_str())
    );
    let version = config
        .load(tenant(), store)
        .await
        .expect("load the tree")
        .and_then(|tree| {
            tree.record
                .history
                .last()
                .map(|version| version.id.to_string())
        })
        .expect("a version");
    assert_eq!(
        entry.after,
        Some(serde_json::json!({
            "config_version_id": version,
            "staff_count": 1,
            "reason": REPUBLISH_REASON,
        })),
        "the version, the staff count and the reason: nothing about anyone"
    );
    assert_eq!(entry.before, None);
    let recorded = format!("{:?} {:?}", entry.after, entry.actor);
    for personal in ["Alice", "C01", "argon2"] {
        assert!(
            !recorded.contains(personal),
            "no name, code or PIN hash in the trail: {recorded}"
        );
    }
}

#[tokio::test]
async fn a_queued_store_whose_node_is_current_is_given_no_version() {
    let admin = provisioned_admin();
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let queue = InMemoryPeopleRepublishes::new();
    let store = store_id();
    seed_a_cashier(&people, store).await;
    // Published by the button: the node is what the store's people compile to.
    let router = people_publish_app(
        admin,
        people.clone(),
        config.clone(),
        Arc::new(AuditSink::new(audit.clone())),
    );
    let cookie = admin_cookie(&router).await;
    publish_people(&router, &cookie, store).await;
    let versions = versions_at(&config, store).await;
    queue_store(&queue, store, NOW_MS).await;

    let tally = drain_once(&queue, &people, &config, &audit).await;

    assert_eq!(
        tally,
        DrainTally {
            unchanged: 1,
            ..DrainTally::default()
        }
    );
    assert_eq!(
        versions_at(&config, store).await,
        versions,
        "a store whose node is current is given no new version"
    );
    assert!(
        still_queued(&queue).await.is_empty(),
        "and leaves the queue"
    );
    assert_eq!(
        people_publishes(&audit).await.len(),
        1,
        "only the button's publish is recorded"
    );
}

#[tokio::test]
async fn a_queued_store_whose_people_were_never_published_is_given_no_node() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let queue = InMemoryPeopleRepublishes::new();
    let (alice, cashier) = seed_a_cashier(&people, store_id()).await;
    AssignmentStore::assign(
        &people,
        &NewAssignment {
            assignment_id: AssignmentId::new(Ulid::from_u128(2)),
            tenant_id: tenant(),
            employee_id: alice,
            scope: AssignmentScope::Store(second_store()),
            role_template_id: cashier,
        },
    )
    .await
    .expect("assign");
    // `store_id()` has no tree at all. `second_store()` has a tree whose only `permissions` node is
    // the switch the settings publish writes on the Tenant layer, and no people node.
    seed_tree(
        &config,
        second_store(),
        [
            serde_json::json!({ "permissions": { "enforced": true } }),
            serde_json::json!({}),
            serde_json::json!({}),
            serde_json::json!({}),
        ],
    )
    .await;
    queue_store(&queue, store_id(), NOW_MS).await;
    queue_store(&queue, second_store(), NOW_MS).await;

    let tally = drain_once(&queue, &people, &config, &audit).await;

    assert_eq!(
        tally,
        DrainTally {
            never_published: 2,
            ..DrainTally::default()
        }
    );
    assert!(
        config
            .load(tenant(), store_id())
            .await
            .expect("load the tree")
            .is_none(),
        "no tree is created for a store that had none"
    );
    let tree = config
        .load(tenant(), second_store())
        .await
        .expect("load the tree")
        .expect("the tree it had");
    assert!(
        tree.record.layers[2].get("permissions").is_none(),
        "no people node is created beside the switch"
    );
    assert!(tree.record.history.is_empty(), "and no version");
    assert!(
        still_queued(&queue).await.is_empty(),
        "both leave the queue"
    );
    assert!(people_publishes(&audit).await.is_empty());
}

/// The tree a rollback leaves ([`ConfigTree::restore_with`]): the restored version whole on the
/// Tenant layer, here a roster from before the grant beside the switch, and the other three empty.
fn rolled_back(store: StoreId) -> [serde_json::Value; 4] {
    let alice = EmployeeId::new(Ulid::from_u128(0xA11));
    [
        serde_json::json!({
            "permissions": {
                "store_id": store.to_string(),
                "enforced": true,
                "staff": [{
                    "id": alice.to_string(),
                    "code": "C01",
                    "name": "Alice",
                    "permissions": [],
                    "pin_phc": "argon2id$phc$alice",
                }],
            },
        }),
        serde_json::json!({}),
        serde_json::json!({}),
        serde_json::json!({}),
    ]
}

#[tokio::test]
async fn a_rolled_back_store_is_published_again_onto_its_store_layer() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let queue = InMemoryPeopleRepublishes::new();
    let store = store_id();
    seed_a_cashier(&people, store).await;
    seed_tree(&config, store, rolled_back(store)).await;
    queue_store(&queue, store, NOW_MS).await;

    let tally = drain_once(&queue, &people, &config, &audit).await;

    assert_eq!(
        tally,
        DrainTally {
            published: 1,
            ..DrainTally::default()
        },
        "a roster a rollback moved onto the Tenant layer is a published roster"
    );
    let tree = config
        .load(tenant(), store)
        .await
        .expect("load the tree")
        .expect("the tree")
        .record;
    let written = &tree.layers[2]["permissions"];
    assert_eq!(
        written["staff"][0]["permissions"],
        serde_json::json!(["billing.discount.apply"]),
        "the node its people compile to now, written on the Store layer"
    );
    let runs = tree.effective();
    assert_eq!(
        runs["permissions"]["staff"], written["staff"],
        "the store runs the compiled roster, not the one the rollback left"
    );
    assert_eq!(
        runs["permissions"]["enforced"],
        serde_json::json!(true),
        "and keeps the switch the rollback restored"
    );
    assert_eq!(tree.history.len(), 1, "one new version");
    assert!(still_queued(&queue).await.is_empty());
    assert_eq!(people_publishes(&audit).await.len(), 1);
}

#[tokio::test]
async fn a_store_whose_store_layer_holds_the_switch_alone_is_given_no_roster() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let queue = InMemoryPeopleRepublishes::new();
    let store = store_id();
    // People who would compile to a roster, and a `permissions` node typed on the Store layer
    // with the switch and no `staff` key: the edge reads that as no roster.
    seed_a_cashier(&people, store).await;
    let switch_alone = serde_json::json!({ "permissions": { "enforced": true } });
    seed_tree(&config, store, store_layer_only(switch_alone.clone())).await;
    queue_store(&queue, store, NOW_MS).await;

    let tally = drain_once(&queue, &people, &config, &audit).await;

    assert_eq!(
        tally,
        DrainTally {
            never_published: 1,
            ..DrainTally::default()
        }
    );
    let tree = config
        .load(tenant(), store)
        .await
        .expect("load the tree")
        .expect("the tree")
        .record;
    assert_eq!(
        tree.layers[2], switch_alone,
        "no roster is created beside the switch"
    );
    assert!(tree.history.is_empty(), "and no version");
    assert!(still_queued(&queue).await.is_empty(), "it leaves the queue");
    assert!(people_publishes(&audit).await.is_empty());
}

#[tokio::test]
async fn a_store_that_cannot_be_published_keeps_its_row_and_the_drain_reaches_every_other() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let audit = FakeAudit::default();
    let queue = InMemoryPeopleRepublishes::new();
    seed_a_cashier(&people, store_id()).await;
    // More stores than one read of the queue hands over. Every other one holds a stale people node
    // beside a rollout no publish can validate, so every publish to it is refused; the rest hold
    // no tree, so their people were never published.
    let count = people_republish::DRAIN_BATCH + 6;
    let mut refusing = Vec::new();
    for n in 0..count {
        let store = StoreId::new(Ulid::from_u128(0xB000 + u128::try_from(n).expect("small")));
        if n % 2 == 1 {
            seed_tree(
                &config,
                store,
                store_layer_only(serde_json::json!({
                    "permissions": people_before_the_grant(store_id()),
                    "fleet_update": "not a rollout",
                })),
            )
            .await;
            refusing.push(store);
        }
        queue_store(&queue, store, NOW_MS).await;
    }
    // And the store with people, published again past all of them.
    seed_tree(
        &config,
        store_id(),
        store_layer_only(serde_json::json!({ "permissions": people_before_the_grant(store_id()) })),
    )
    .await;
    queue_store(&queue, store_id(), NOW_MS).await;

    let tally = drain_once(&queue, &people, &config, &audit).await;

    assert_eq!(
        tally,
        DrainTally {
            published: 1,
            unchanged: 0,
            never_published: count - refusing.len(),
            failed: refusing.len(),
        }
    );
    assert_eq!(
        still_queued(&queue).await,
        refusing,
        "a store that cannot be published keeps its row for the next drain, and only such a store"
    );
    for store in &refusing {
        assert_eq!(
            versions_at(&config, *store).await,
            0,
            "a refused store is given no version"
        );
    }
    assert_eq!(staff_at(&config, store_id()).await.len(), 1);

    // The next drain tries them again, and keeps them again.
    let again = drain_once(&queue, &people, &config, &audit).await;
    assert_eq!(
        again,
        DrainTally {
            failed: refusing.len(),
            ..DrainTally::default()
        }
    );
    assert_eq!(still_queued(&queue).await, refusing);
}

#[tokio::test]
async fn the_people_republisher_drains_at_start_up_and_records_its_tick() {
    let people = FakePeople::default();
    let config = FakeConfigTrees::default();
    let queue = InMemoryPeopleRepublishes::new();
    let task_health = FakeTaskHealth::default();
    let store = store_id();
    seed_a_cashier(&people, store).await;
    seed_tree(
        &config,
        store,
        store_layer_only(serde_json::json!({ "permissions": people_before_the_grant(store) })),
    )
    .await;
    queue_store(&queue, store, NOW_MS).await;

    // Asked to stop before it ever waits: what runs is the drain at start-up.
    people_republish::run(
        queue.clone(),
        people.clone(),
        config.clone(),
        Arc::new(NoopAuditRecorder),
        task_health.clone(),
        clock(),
        people_republish::DRAIN_INTERVAL,
        async {},
    )
    .await;

    assert_eq!(
        staff_at(&config, store).await.len(),
        1,
        "published at start-up"
    );
    assert!(still_queued(&queue).await.is_empty());
    let ticks = task_health.list_health().await.expect("read the ticks");
    let tick = ticks
        .iter()
        .find(|tick| tick.task == PEOPLE_REPUBLISHER)
        .expect("the republisher recorded its tick");
    assert_eq!(
        tick.detail,
        serde_json::json!({
            "ok": true,
            "interval_secs": people_republish::DRAIN_INTERVAL.as_secs(),
            "published": 1,
            "unchanged": 0,
            "never_published": 0,
            "failed": 0,
        })
    );
}
